def test_output_is_yes_or_no(run, x):
    output = run(x).strip()
    assert output in {"YES", "NO"}

def test_output_ends_with_newline(run, x):
    output = run(x)
    assert output.endswith('\n')

def test_output_is_uppercase(run, x):
    output = run(x).strip()
    assert output.isupper()

def test_output_length(run, x):
    output = run(x)
    assert len(output) == 4  # 'YES\n' or 'NO\n'

def test_output_no_extra_spaces(run, x):
    output = run(x)
    stripped = output.strip()
    assert output == stripped + '\n'

def test_example_5(run, x):
    if x == "5\n":
        assert run(x) == "YES\n"

def test_example_13(run, x):
    if x == "13\n":
        assert run(x) == "NO\n"

def test_example_24(run, x):
    if x == "24\n":
        assert run(x) == "NO\n"

def test_example_46(run, x):
    if x == "46\n":
        assert run(x) == "YES\n"

def test_deterministic(run, x):
    assert run(x) == run(x)

