tests_src:
def test_output_is_valid_token(run, x):
    out = run(x).strip()
    assert out in ("YES", "NO"), f"Output must be YES or NO, got {out!r}"

def test_output_has_no_extra_whitespace(run, x):
    out = run(x)
    assert out in ("YES\n", "NO\n"), f"Output must be exactly YES or NO followed by newline, got {out!r}"

def test_example_5_YES(run, x):
    if x == "5\n":
        assert run(x).strip() == "YES", "Example from statement: input 5 must output YES"

def test_example_13_NO(run, x):
    if x == "13\n":
        assert run(x).strip() == "NO", "Example from statement: input 13 must output NO"

def test_example_24_NO(run, x):
    if x == "24\n":
        assert run(x).strip() == "NO", "Example from statement: input 24 must output NO"

def test_example_46_YES(run, x):
    if x == "46\n":
        assert run(x).strip() == "YES", "Example from statement: input 46 must output YES"

def test_metamorphic_identity_same_input(run, x):
    out1 = run(x).strip()
    out2 = run(x).strip()
    assert out1 == out2, "Output must be deterministic for the same input"

def test_metamorphic_identity_adding_zero(run, x):
    # Adding zero to the integer yields the same integer, so input unchanged
    # But we can't change the input string? We can parse and reconstruct.
    a = int(x.strip())
    # a + 0 is the same, so we run on the same input.
    out1 = run(x).strip()
    out2 = run(str(a) + "\n").strip()
    assert out1 == out2, "Output must be the same for the same integer representation"

def test_output_length(run, x):
    out = run(x).strip()
    assert len(out) in (2, 3), f"Output length must be 2 or 3, got {len(out)} for {out!r}"  # YES length 3, NO length 2

def test_no_extra_output(run, x):
    out = run(x)
    lines = out.splitlines()
    assert len(lines) == 1, f"Output must be exactly one line, got {len(lines)} lines"
    token = lines[0]
    assert token in ("YES", "NO"), f"Token must be YES or NO, got {token!r}"

