def test_non_negative(run, x):
    out = run(x)
    ans = int(out.strip())
    assert ans >= 0

def test_upper_bound(run, x):
    n = int(x.strip())
    out = run(x)
    ans = int(out.strip())
    # K from 2 to n inclusive -> at most n-1 choices
    assert ans <= n - 1

def test_at_least_one(run, x):
    n = int(x.strip())
    out = run(x)
    ans = int(out.strip())
    # K=n always works: n -> n - n = 0? Wait, if K=n and n>=2, operation: if n divides n? n//n =1, replace with n/n=1, so ends at 1 immediately.
    # So at least K=n works.
    assert ans >= 1

def test_divisor_of_n_minus_1_works(run, x):
    n = int(x.strip())
    out = run(x)
    ans = int(out.strip())
    # every divisor d of n-1 with d>=2 should be counted
    # we cannot recompute answer, but we can simulate for each such d and verify that if it works, it's counted.
    # However we don't know if the answer counted it. Instead we can check that the answer is at least the number of divisors of n-1 that are >=2.
    # Wait: specification says count of K that work. Divisors of n-1 (>=2) are all valid K? Yes, because with K dividing n-1, n mod K = 1, so first step n-K reduces to n-K = (n-1)-(K-1) ... Actually known property: if K divides n-1, then repeatedly subtract K until 1.
    # So they all work. So answer must be >= count of divisors of n-1 (>=2).
    cnt = 0
    import math
    for i in range(1, int(math.isqrt(n-1)) + 1):
        if (n-1) % i == 0:
            if i >= 2:
                cnt += 1
            j = (n-1) // i
            if j != i and j >= 2:
                cnt += 1
    assert ans >= cnt

def test_simulate_for_small_k(run, x):
    n = int(x.strip())
    out = run(x)
    ans = int(out.strip())
    # simulate for K=2 and K=n (should always work) and verify they are counted.
    # We can't know which K are counted from ans alone. Instead we can simulate and if they work, ensure the program's answer is consistent by checking that the set of working K we find by brute force (for small n) matches the answer.
    # But n can be huge up to 1e12, brute force impossible.
    # However the given test inputs are small enough for brute force? Let's see list: largest is 1000000000000, too big.
    # We need a certificate that works for any n: simulate for K=2 and K=n because we know they work.
    # So we can just verify that K=n works (always).
    # Actually we already have test_at_least_one.
    # For K=2, simulate and see if it works, and if it does, ensure answer >=1 (already). Not enough.
    # Instead we can compute the set of working K by simulation for n <= 10^6 (since inputs up to 10^6 exist). For larger inputs, skip.
    if n <= 10**6:
        working = 0
        for k in range(2, n+1):
            cur = n
            while cur >= k:
                if cur % k == 0:
                    cur //= k
                else:
                    cur -= k
            if cur == 1:
                working += 1
        assert ans == working
    # else skip

def test_prime_n(run, x):
    n = int(x.strip())
    out = run(x)
    ans = int(out.strip())
    # if n is prime >2, then divisors of n are 1 and n.
    # Divisors of n-1 include at least 2 and n-1.
    # Known result: for prime n, working K are: n and divisors of n-1 >=2.
    # So answer should be 1 + number of divisors of n-1 (>=2).
    # We can check this by brute force for small n.
    if n <= 10**6:
        import math
        def is_prime(m):
            if m < 2:
