def test_answer_upper_bound(run, x):
    import io
    data = list(map(int, x.split()))
    if len(data) < 4:
        return
    r, c, n, k = data[0], data[1], data[2], data[3]
    total_rectangles = r * (r + 1) // 2 * c * (c + 1) // 2
    out = int(run(x))
    assert out <= total_rectangles

def test_permute_rows(run, x):
    import io
    lines = x.strip().split('\n')
    header = list(map(int, lines[0].split()))
    if len(header) < 4:
        return
    r, c, n, k = header
    if r == 1:
        return  # no rows to permute
    # Build a permutation of rows: swap first two rows if they exist
    perm = {1:2, 2:1}
    new_lines = [f'{r} {c} {n} {k}']
    for line in lines[1:]:
        x_i, y_i = map(int, line.split())
        if x_i in perm:
            x_i = perm[x_i]
        new_lines.append(f'{x_i} {y_i}')
    new_input = '\n'.join(new_lines)
    out1 = int(run(x))
    out2 = int(run(new_input))
    assert out1 == out2

def test_permute_columns(run, x):
    import io
    lines = x.strip().split('\n')
    header = list(map(int, lines[0].split()))
    if len(header) < 4:
        return
    r, c, n, k = header
    if c == 1:
        return  # no columns to permute
    # Swap first two columns
    perm = {1:2, 2:1}
    new_lines = [f'{r} {c} {n} {k}']
    for line in lines[1:]:
        x_i, y_i = map(int, line.split())
        if y_i in perm:
            y_i = perm[y_i]
        new_lines.append(f'{x_i} {y_i}')
    new_input = '\n'.join(new_lines)
    out1 = int(run(x))
    out2 = int(run(new_input))
    assert out1 == out2

def test_monotonic_k(run, x):
    import io
    lines = x.strip().split('\n')
    header = list(map(int, lines[0].split()))
    if len(header) < 4:
        return
    r, c, n, k = header
    if k == 1:
        return  # cannot decrease k further
    # Increase k by 1 (still ≤ n)
    k2 = k + 1
    if k2 > n:
        return
    new_header = f'{r} {c} {n} {k2}'
    new_input = '\n'.join([new_header] + lines[1:])
    out1 = int(run(x))
    out2 = int(run(new_input))
    # With larger k, number of rectangles cannot increase
    assert out1 >= out2

def test_add_viola(run, x):
    import io
    lines = x.strip().split('\n')
    header = list(map(int, lines[0].split()))
    if len(header) < 4:
        return
    r, c, n, k = header
    # Add a viola at a position not already occupied, if possible
    # We'll try to add at (r, c) if not already present
    existing = set()
    for line in lines[1:]:
        x_i, y_i = map(int, line.split())
        existing.add((x_i, y_i))
    if (r, c) not in existing:
        new_n = n + 1
        if new_n > r * c:
            return  # grid full
        new_header = f'{r} {c} {new_n} {k}'
        new_lines = [new_header] + lines[1:] + [f'{r} {c}']
        new_input = '\n'.join(new_lines)
        out1 = int(run(x))
        out2 = int(run(new_input))
        # Adding a viola cannot decrease the count (k unchanged)
        assert out2 >= out1

def test_small_bruteforce(run, x):
    import io
    data = list(map(int, x.split()))
    if len(data) < 4:
