def test_non_negative(run, x):
    out = run(x)
    ans = int(out.strip())
    assert ans >= 0, "Answer must be non-negative"

def test_integer(run, x):
    out = run(x)
    # ensure it's a valid integer
    ans = int(out.strip())
    # also ensure it's printed without extra spaces
    assert out.strip() == str(ans), "Answer must be a single integer"

def test_bound_distinct(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    visitors = set()
    for i in range(1, n+1):
        parts = lines[i].split()
        if len(parts) == 2:
            visitors.add(int(parts[1]))
    ans = int(run(x).strip())
    assert ans <= len(visitors), f"Answer {ans} exceeds total distinct visitors {len(visitors)}"

def test_feasibility(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    events = []
    for i in range(1, n+1):
        parts = lines[i].split()
        events.append((parts[0], int(parts[1])))
    ans = int(run(x).strip())
    # Determine start visitors: those whose first event is '-'
    first_event = {}
    for idx, (t, a) in enumerate(events):
        if a not in first_event:
            first_event[a] = t
    start_visitors = {a for a, t in first_event.items() if t == '-'}
    present = set(start_visitors)
    # Process events
    for t, a in events:
        if t == '+':
            present.add(a)
        else:  # '-'
            if a in present:
                present.remove(a)
            else:
                # This should not happen if start_visitors included a
                # But if not, then the log is contradictory? We'll still treat as error.
                # However, for feasibility we need to allow that they might have been present at start.
                # So we assume they were present and now leave.
                # Since we didn't add them to start_visitors (because first event is '-'), but first event is '-' indeed.
                # So they should be in start_visitors.
                # If they are not, then the log is invalid, but we'll still handle.
                pass
        if len(present) > ans:
            raise AssertionError(f"Capacity {ans} insufficient at event {t} {a}, present {len(present)}")
    # Feasibility passed

def test_start_visitors_lower_bound(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    first_event = {}
    for i in range(1, n+1):
        parts = lines[i].split()
        a = int(parts[1])
        if a not in first_event:
            first_event[a] = parts[0]
    start_count = sum(1 for t in first_event.values() if t == '-')
    ans = int(run(x).strip())
    assert ans >= start_count, f"Answer {ans} less than number of start visitors {start_count}"

def test_max_d_lower_bound(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    events = []
    for i in range(1, n+1):
        parts = lines[i].split()
        events.append((parts[0], int(parts[1])))
    # Compute max size of set of visitors who entered during log and not left (ignoring start visitors)
    d = set()
    max_d = 0
    for t, a in events:
        if t == '+':
            d.add(a)
            max_d = max(max_d, len(d))
        else:
            if a in d:
                d.remove(a)
    ans = int(run(x).strip())
    assert ans >= max_d, f"Answer {ans} less than max simultaneous entrants {max_d}"

def test_bound_n(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    ans = int(run(x).strip())
    assert ans <= n, f"Answer {ans} exceeds n ({n})"

def test_final_state(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    events = []
    for i in range(1, n+1):
        parts = lines[i].split()
        events.append((parts[0], int(parts[1])))
    # Determine start visitors
    first_event = {}
    for idx, (t, a) in enumerate(events):
        if a not in first_event:
            first_event[a] = t
    start_visitors = {a for a, t in first_event.items() if t == '-'}
    present = set(start_visitors)
    for t, a in events:
        if t == '+':
            present.add(a)
        else:
            if a in present:
                present.remove(a)
    ans = int(run(x).strip())
    assert len(present) <= ans, f"Final number of visitors {len(present)} exceeds capacity {ans}"

def test_at_least_one_if_any_plus(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    has_plus = any(lines[i].startswith('+') for i in range(1, n+1))
    if has_plus:
        ans = int(run(x).strip())
        assert ans >= 1, "There is a '+' event, so capacity must be at least 1"

def test_answer_is_at_least_max_plus_minus(run, x):
    # Another lower bound: the answer must be at least the maximum over prefixes of (plus_count - minus_count)
    # where plus_count is number of '+' events so far, minus_count is number of '-' events so far.
    # This counts net change from zero start, but start visitors add to that.
    # Actually, the minimum capacity must be at least the maximum of (start_visitors_still_present + net_change).
    # We can compute a lower bound by assuming all start visitors are still present (worst case).
    lines = x.strip().split('\n')
    n = int(lines[0])
    events = []
    for i in range(1, n+1):
        parts = lines[i].split()
        events.append((parts[0], int(parts[1])))
    # Determine start visitors count
    first_event = {}
    for idx, (t, a) in enumerate(events):
        if a not in first_event:
            first_event[a] = t
    start_count = sum(1 for t in first_event.values() if t == '-')
    # Compute net change at each step
    cur = start_count
    max_cur = cur
    for t, a in events:
        if t == '+':
            cur += 1
        else:
            cur -= 1
        max_cur = max(max_cur, cur)
    ans = int(run(x).strip())
    assert ans >= max_cur, f"Answer {ans} less than lower bound {max_cur} from net count"

