def test_output_format(run, x):
    out = run(x)
    assert out in ('YES\n', 'NO\n'), f'Output must be YES\n or NO\n, got {repr(out)}'

def test_length_mismatch_implies_no(run, x):
    a, b = x.strip().split('\n')
    if len(a) != len(b):
        assert run(x) == 'NO\n', f'If lengths differ, answer must be NO'

def test_yes_implies_same_length_and_presence_of_one(run, x):
    out = run(x)
    if out == 'YES\n':
        a, b = x.strip().split('\n')
        assert len(a) == len(b), f'YES but lengths differ'
        assert ('1' in a) == ('1' in b), f'YES but presence of 1 differs'

def test_no_implies_length_mismatch_or_one_presence_differs(run, x):
    out = run(x)
    if out == 'NO\n':
        a, b = x.strip().split('\n')
        assert len(a) != len(b) or ('1' in a) != ('1' in b), f'NO but lengths equal and presence of 1 same'

def test_symmetry(run, x):
    a, b = x.strip().split('\n')
    out1 = run(x)
    swapped = f'{b}\n{a}\n'
    out2 = run(swapped)
    assert out1 == out2, f'Answers for (a,b) and (b,a) must match'

def test_all_zeros_same_length_yes(run, x):
    a, b = x.strip().split('\n')
    if len(a) == len(b) and '1' not in a and '1' not in b:
        assert run(x) == 'YES\n', f'Both strings all zeros and same length -> must be YES'

def test_length_one_different_no(run, x):
    a, b = x.strip().split('\n')
    if len(a) == 1 and len(b) == 1 and a != b:
        assert run(x) == 'NO\n', f'Single characters differ -> must be NO'

def test_output_length(run, x):
    out = run(x)
    assert len(out) == 4 or len(out) == 3, f'Output length must be 3 or 4 characters (including newline)'
    if len(out) == 4:
        assert out[-1] == '\n', f'If length 4, last char must be newline'

def test_yes_implies_not_empty(run, x):
    # Strings are guaranteed non-empty by spec, but just in case.
    a, b = x.strip().split('\n')
    out = run(x)
    if out == 'YES\n':
        assert len(a) > 0 and len(b) > 0, f'Strings non-empty by spec'

def test_operation_preserves_length(run, x):
    # This is a metamorphic relation: if we add a prefix of zeros to both strings, answer should stay same?
    # Not safe. Instead, we test that if we duplicate both strings (concatenate with themselves), answer should stay same?
    # Actually operation on each half independent? Not necessarily because operations cross boundaries.
    # So we skip and use another invariant: output must be uppercase.
    out = run(x)
    if out.startswith('YES'):
        assert out[:3] == 'YES', f'YES must be uppercase'
    elif out.startswith('NO'):
        assert out[:2] == 'NO', f'NO must be uppercase'

