                if len(cores) >= 2:
                    # conflict, all writers should lock this step
                    for core in cores:
                        if lock[core] == step:
                            pass
                        else:
                            if lock[core] != 0 and lock[core] < step:
                                pass
                            else:
                                assert False, f'Core {core+1} involved in conflict at step {step} but not locked at that step'
                    # mark cell locked
                    if cell_locked[cell] == 0:
                        cell_locked[cell] = step
                # else single writer, cell not locked -> no lock

def test_pairwise_conflict(run, x):
    out = run(x).strip().split('\n')
    n, m, k = map(int, x.strip().split('\n')[0].split())
    lock = [int(v) for v in out]
    instr = [list(map(int, row.split())) for row in x.strip().split('\n')[1:]]
    # For each step, each cell, if exactly two active cores write to it and neither locked before, both must lock this step.
    for step in range(1, m+1):
        writes = {}
        for core in range(n):
            if lock[core] == 0 or lock[core] >= step:
                cell = instr[core][step-1]
                if cell != 0:
                    writes.setdefault(cell, []).append(core)
