                # Check if both cores are not locked before step
                if (lock[c1] == 0 or lock[c1] >= step) and (lock[c2] == 0 or lock[c2] >= step):
                    # Neither locked before, so conflict must lock both at this step
                    if not (lock[c1] == step and lock[c2] == step):
                        # Unless cell was already locked earlier? Let's check cell lock state.
                        # Determine if cell locked earlier by simulating cell lock times from output.
                        # We'll compute cell lock time as min step where conflict occurred or a core locked earlier.
                        # For simplicity, assume cell not locked earlier if no core locked earlier due to that cell.
                        # This test may be too strict, but it's a property that should hold.
                        # We'll skip if cell was already locked before step.
                        # Find if any core locked earlier due to this cell.
                        cell_locked_before = False
