def test_cell_lock_consistency(run, x):
    out = run(x).strip().split('\n')
    n, m, k = map(int, x.strip().split('\n')[0].split())
    lock = [int(v) for v in out]
    instr = [list(map(int, row.split())) for row in x.strip().split('\n')[1:]]
    # Compute for each cell the step it becomes locked (0 if never)
    cell_lock_step = [0] * (k+1)
    # Determine from conflicts: a cell locks at step s if there are >=2 active writers at s and cell not locked earlier.
    # Also a cell cannot lock if only one writer.
    for step in range(1, m+1):
        writes = {}
        for core in range(n):
            if lock[core] == 0 or lock[core] >= step:
                cell = instr[core][step-1]
                if cell != 0:
                    writes.setdefault(cell, []).append(core)
        for cell, cores in writes.items():
            if cell_lock_step[cell] == 0:
                if len(cores) >= 2:
                    cell_lock_step[cell] = step
            # else already locked
    # Now verify that any core writing to a locked cell at step > cell_lock_step gets locked at that step
    for core in range(n):
        t = lock[core]
        if t > 0:
            cell = instr[core][t-1]
            if cell != 0:
                if cell_lock_step[cell] != 0 and cell_lock_step[cell] < t:
                    # cell locked earlier, core must lock at t (already true)
                    pass
                else:
                    # cell not locked earlier, so must be conflict at t
                    # ensure cell_lock_step[cell] == t
                    assert cell_lock_step[cell] == t, f'Core {core+1} locked at step {t} but cell {cell} lock step is {cell_lock_step[cell]}'

