def test_no_lock_if_no_write(run, x):
    out = run(x).strip().split('\n')
    n, m, k = map(int, x.strip().split('\n')[0].split())
    lock = [int(v) for v in out]
    instr = [list(map(int, row.split())) for row in x.strip().split('\n')[1:]]
    # A core that never writes to any cell (all commands 0) must have lock step 0.
    for core in range(n):
        if all(cell == 0 for cell in instr[core]):
            assert lock[core] == 0, f'Core {core+1} never writes but locked at step {lock[core]}'

