def test_certificate_satisfies_constraints(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    if lines[0] == 'Yes':
        n, m = map(int, x.strip().split('\n')[0].split())
        row_vals = list(map(int, lines[1].split()))
        col_vals = list(map(int, lines[2].split()))
        table = x.strip().split('\n')[1:]
        for i in range(n):
            for j in range(m):
                c = table[i][j]
                if c == '<':
                    assert row_vals[i] < col_vals[j]
                elif c == '>':
                    assert row_vals[i] > col_vals[j]
                else:
                    assert c == '='
                    assert row_vals[i] == col_vals[j]
    else:
        # 'No' answer: nothing to check
        pass


def test_values_positive(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    if lines[0] == 'Yes':
        row_vals = list(map(int, lines[1].split()))
        col_vals = list(map(int, lines[2].split()))
        assert all(v >= 1 for v in row_vals + col_vals)


def test_output_shape(run, x):
    out = run(x).strip()
    lines = out.split('\n')
    n, m = map(int, x.strip().split('\n')[0].split())
    assert 1 <= len(lines) <= 3
    if lines[0] == 'Yes':
        assert len(lines) == 3
        assert len(lines[1].split()) == n
        assert len(lines[2].split()) == m
    else:
        assert lines[0] == 'No'
        assert len(lines) == 1


def test_first_line_valid(run, x):
    out = run(x).strip()
    lines = out.split('\n')
    assert lines[0] in ('Yes', 'No')


def test_no_without_numbers(run, x):
    out = run(x).strip()
    if out == 'No':
        # should be exactly one line
        assert out.count('\n') == 0
    else:
        # 'Yes' case: at least two more lines
        lines = out.split('\n')
        assert len(lines) >= 3


def test_counts_match(run, x):
    out = run(x).strip()
    lines = out.split('\n')
    n, m = map(int, x.strip().split('\n')[0].split())
    if lines[0] == 'Yes':
        assert len(lines[1].split()) == n
        assert len(lines[2].split()) == m


def test_values_bound(run, x):
    out = run(x).strip()
    lines = out.split('\n')
    if lines[0] == 'Yes':
        row_vals = list(map(int, lines[1].split()))
        col_vals = list(map(int, lines[2].split()))
        n, m = map(int, x.strip().split('\n')[0].split())
        # a trivial bound: each value cannot exceed n+m
        # because you can topologically assign levels up to that
        max_val = max(row_vals + col_vals)
        assert max_val <= n + m


def test_metamorphic_swap_sets(run, x):
    # Build a new input where we swap the two sets (rows ↔ cols) and invert relations.
    first = x.strip().split('\n')
    n, m = map(int, first[0].split())
    table = first[1:]
    # Build new m × n table with swapped roles
    new_table = []
    for j in range(m):
        row = []
        for i in range(n):
            c = table[i][j]
            if c == '<':
                row.append('>')
            elif c == '>':
                row.append('<')
            else:
                row.append('=')
        new_table.append(''.join(row))
    new_input = f"{m} {n}\n" + '\n'.join(new_table)
    out1 = run(x).strip()
    out2 = run(new_input).strip()
    # If one is 'No', the other must also be 'No' (consistency).
    if out1.startswith('No'):
        assert out2.startswith('No')
    else:
        # Both are 'Yes'. The values for the swapped sets should be swapped.
        vals1_rows = list(map(int, out1.split('\n')[1].split()))
        vals1_cols = list(map(int, out1.split('\n')[2].split()))
        vals2_rows = list(map(int, out2.split('\n')[1].split()))
        vals2_cols = list(map(int, out2.split('\n')[2].split()))
        assert vals1_rows == vals2_cols
        assert vals1_cols == vals2_rows


def test_equal_dishes_same_value(run, x):
    out = run(x).strip()
    lines = out.split('\n')
    if lines[0] == 'Yes':
        n, m = map(int, x.strip().split('\n')[0].split())
        table = x.strip().split('\n')[1:]
        row_vals = list(map(int, lines[1].split()))
        col_vals = list(map(int, lines[2].split()))
        # For each '=' relation, check equality
        for i in range(n):
            for j in range(m):
                if table[i][j] == '=':
                    assert row_vals[i] == col_vals[j]


def test_strict_inequalities(run, x):
    out = run(x).strip()
    lines = out.split('\n')
    if lines[0] == 'Yes':
        n, m = map(int, x.strip().split('\n')[0].split())
        table = x.strip().split('\n')[1:]
        row_vals = list(map(int, lines[1].split()))
        col_vals = list(map(int, lines[2].split()))
        for i in range(n):
            for j in range(m):
                c = table[i][j]
                if c == '<':
                    assert row_vals[i] < col_vals[j]
                elif c == '>':
                    assert row_vals[i] > col_vals[j]

