def test_answer_between_0_and_N(run, x):
    # The answer is the number of magic uses, must be between 0 and N inclusive.
    N = int(x.strip().split()[0])
    ans = int(run(x).strip())
    assert 0 <= ans <= N

def test_answer_integer(run, x):
    # The answer must be an integer.
    ans = run(x).strip()
    # Check it's a valid integer string.
    int(ans)  # Raises ValueError if not.

def test_add_redundant_constraint(run, x):
    # Adding a constraint between two already connected nodes does not change answer.
    lines = x.strip().split('\n')
    N, M = map(int, lines[0].split())
    if M == 0:
        return
    # Build union-find from existing constraints.
    import sys
    sys.setrecursionlimit(200000)
    class UF:
        def __init__(self, n):
            self.parents = [-1]*n
        def find(self, x):
            if self.parents[x] < 0:
                return x
            self.parents[x] = self.find(self.parents[x])
            return self.parents[x]
        def union(self, x, y):
            x = self.find(x)
            y = self.find(y)
            if x == y:
                return
            if self.parents[x] > self.parents[y]:
                x, y = y, x
            self.parents[x] += self.parents[y]
            self.parents[y] = x
        def connected(self, x, y):
            return self.find(x) == self.find(y)
    uf = UF(N)
    edges = []
    for line in lines[1:]:
        if line.strip() == '':
            continue
        X, Y, Z = map(int, line.split())
        X -= 1
        Y -= 1
        edges.append((X, Y, Z))
        uf.union(X, Y)
    # Find a pair already connected (if any).
    for i in range(N):
        for j in range(i+1, N):
            if uf.connected(i, j):
                # Add a dummy constraint between i+1 and j+1 with arbitrary Z.
                new_input = f'{N} {M+1}\n' + '\n'.join(lines[1:]) + f'\n{i+1} {j+1} 1'
                ans1 = int(run(x).strip())
                ans2 = int(run(new_input).strip())
                assert ans1 == ans2
                return
    # If no connected pair, test passes trivially.
    return

def test_relabel_nodes(run, x):
    # Permuting node indices (with constraints adjusted) should not change answer.
    import random
    lines = x.strip().split('\n')
    N, M = map(int, lines[0].split())
    perm = list(range(1, N+1))
    random.seed(42)  # deterministic.
    random.shuffle(perm)
    # inverse permutation.
    inv = [0]*(N+1)
    for i, p in enumerate(perm, 1):
        inv[p] = i
    new_lines = [f'{N} {M}']
    for line in lines[1:]:
        if line.strip() == '':
            continue
        X, Y, Z = map(int, line.split())
        newX, newY = inv[X], inv[Y]
        if newX > newY:
            newX, newY = newY, newX
        new_lines.append(f'{newX} {newY} {Z}')
    new_input = '\n'.join(new_lines)
    ans1 = int(run(x).strip())
    ans2 = int(run(new_input).strip())
    assert ans1 == ans2

def test_merge_components_decreases_at_most_one(run, x):
    # Adding a constraint between two different components can reduce answer by at most 1.
    lines = x.strip().split('\n')
    N, M = map(int, lines[0].split())
    # Build union-find.
    import sys
    sys.setrecursionlimit(200000)
    class UF:
        def __init__(self, n):
            self.parents = [-1]*n
        def find(self, x):
            if self.parents[x] < 0:
                return x
            self.parents[x] = self.find(self.parents[x])
            return self.parents[x]
        def union(self, x, y):
            x = self.find(x)
            y = self.find(y)
            if x == y:
                return
            if self.parents[x] > self.parents[y]:
                x, y = y, x
            self.parents[x] += self.parents[y]
            self.parents[y] = x
        def connected(self, x, y):
            return self.find(x) == self.find(y)
        def components(self):
            roots = [i for i, p in enumerate(self.parents) if p < 0]
            return len(roots)
    uf = UF(N)
    for line in lines[1:]:
        if line.strip() == '':
            continue
        X, Y, Z = map(int, line.split())
        X -= 1
        Y -= 1
        uf.union(X, Y)
    comps = uf.components()
    # Find two nodes from different components.
    for i in range(N):
        for j in range(i+1, N):
            if not uf.connected(i, j):
                new_input = f'{N} {M+1}\n' + '\n'.join(lines[1:]) + f'\n{i+1} {j+1} 1'
                ans1 = int(run(x).strip())
                ans2 = int(run(new_input).strip())
                assert ans1 - 1 <= ans2 <= ans1
                return
    # If all nodes already connected, test passes.
    return

def test_answer_at_most_N(run, x):
    # The answer cannot exceed N.
    N = int(x.strip().split()[0])
    ans = int(run(x).strip())
    assert ans <= N

def test_empty_constraints(run, x):
    # If M=0, every card is independent, answer must be N.
    lines = x.strip().split('\n')
    N, M = map(int, lines[0].split())
    if M == 0:
        ans = int(run(x).strip())
        assert ans == N

def test_all_Z_even(run, x):
    # If all Z_i are even, then A_x + A_y is even => A_x ≡ A_y (mod 2).
    # Each connected component forces all cards same parity, but we still need to know which parity.
    # Actually, we cannot determine parity without a magic. So each component requires at least 1 magic.
    lines = x.strip().split('\n')
    N, M = map(int, lines[0].split())
    all_even = True
    for line in lines[1:]:
        if line.strip() == '':
            continue
        *_, Z = map(int, line.split())
        if Z % 2 == 1:
            all_even = False
            break
    if all_even:
        ans = int(run(x).strip())
        # Build connected components.
        import sys
        sys.setrecursionlimit(200000)
        class UF:
            def __init__(self, n):
                self.parents = [-1]*n
            def find(self, x):
                if self.parents[x] < 0:
                    return x
                self.parents[x] = self.find(self.parents[x])
                return self.parents[x]
            def union(self, x, y):
                x = self.find(x)
                y = self.find(y)
                if x == y:
                    return
                if self.parents[x] > self.parents[y]:
                    x, y = y, x
                self.parents[x] += self.parents[y]
                self.parents[y] = x
            def components(self):
                roots = [i for i, p in enumerate(self.parents) if p < 0]
                return len(roots)
        uf = UF(N)
        for line in lines[1:]:
            if line.strip() == '':
                continue
            X, Y, _ = map(int, line.split())
            X -= 1
            Y -= 1
            uf.union(X, Y)
        comps = uf.components()
        assert ans == comps

def test_all_Z_odd(run, x):
    # If all Z_i are odd, then A_x + A_y is odd => A_x ≠ A_y.
    # In each component, knowing one card determines all others uniquely.
    # Therefore answer equals number of components.
