def test_duplicate_input(run, x):
    # Duplicating all constraints does not change the answer.
    lines = x.strip().split('\n')
    N, M = map(int, lines[0].split())
    new_lines = [f'{N} {2*M}']
    for line in lines[1:]:
        if line.strip() == '':
            continue
        new_lines.append(line)
    for line in lines[1:]:
        if line.strip() == '':
            continue
        new_lines.append(line)
