    # BFS helper to get path
    def get_path(u, v):
        # BFS to find shortest path (tree)
        parent = {u: -1}
        q = [u]
        for node in q:
            if node == v:
                break
            for nb in adj[node]:
                if nb not in parent:
                    parent[nb] = node
                    q.append(nb)
        # reconstruct
        path = []
        cur = v
        while cur != -1:
            path.append(cur)
            cur = parent[cur]
        return path[::-1]
    allowed = 0
    for u in range(1, n+1):
        for v in range(1, n+1):
            if u == v:
