            iy = path.index(yv) if yv in path else -1
            if ix != -1 and iy != -1 and ix < iy:
                continue  # forbidden
            allowed += 1
    out = int(run(x).strip())
    assert out == allowed, f"Expected {allowed}, got {out}"


