    for line in lines[1:]:
        a,b = map(int, line.split())
        adj[a].append(b)
        adj[b].append(a)
    # compute component size containing xv when avoiding yv
    def bfs_component(start, avoid):
        visited = set()
        stack = [start]
        visited.add(start)
        while stack:
            node = stack.pop()
            for nb in adj[node]:
                if nb != avoid and nb not in visited:
                    visited.add(nb)
                    stack.append(nb)
        return len(visited)
    a = bfs_component(xv, yv)
    b = bfs_component(yv, xv)
