def test_metamorphic_add_pair(run, x):
    lines = x.strip().split('\n')
    if not lines or lines[0] == '0':
        return
    n = int(lines[0])
    # find a day that already has at least one male and one female available
    males = [0]*367
    females = [0]*367
    for line in lines[1:1+n]:
        if not line.strip():
            continue
        sex, l, r = line.split()
        l, r = int(l), int(r)
        if sex == 'M':
            for d in range(l, r+1):
                males[d] += 1
        else:
            for d in range(l, r+1):
                females[d] += 1
    candidate_day = None
    for d in range(1, 367):
