            candidate_day = d
            break
    if candidate_day is None:
        # cannot add a pair that overlaps existing availability, skip
        return
    # add a male and female both available on that day
    new_lines = [str(n+2)] + lines[1:1+n] + [f'M {candidate_day} {candidate_day}', f'F {candidate_day} {candidate_day}']
    new_input = '\n'.join(new_lines)
