        r,g,b,w = map(int, lines[i+1].split())
        if r%2==0 and g%2==0 and b%2==0 and w%2==0:
            assert outs[i].strip() == 'Yes'

def test_one_odd_yes(run, x):
    lines = x.strip().split('\n')
    T = int(lines[0])
    outs = run(x).strip().split('\n')
    for i in range(T):
        r,g,b,w = map(int, lines[i+1].split())
        odd_cnt = (r%2)+(g%2)+(b%2)+(w%2)
        if odd_cnt == 1:
