def test_permutation_rg(run, x):
    lines = x.strip().split('\n')
    T = int(lines[0])
    orig_out = run(x).strip().split('\n')
    # build swapped input
    new_lines = [lines[0]]
    for i in range(1, T+1):
        r,g,b,w = map(int, lines[i].split())
        new_lines.append(f'{g} {r} {b} {w}')
    new_x = '\n'.join(new_lines)
    new_out = run(new_x).strip().split('\n')
    for i in range(T):
