    orig_out = run(x).strip().split('\n')
    for i in range(1, T+1):
        r,g,b,w = map(int, lines[i].split())
        if r>=1 and g>=1 and b>=1:
            # construct a single test case with one operation applied
            new_x = f'1\n{r-1} {g-1} {b-1} {w+3}'
            mod_out = run(new_x).strip()
            if mod_out == 'Yes':
                assert orig_out[i-1] == 'Yes'

def test_necessary_condition_yes(run, x):
    lines = x.strip().split('\n')
    T = int(lines[0])
    outs = run(x).strip().split('\n')
    for i in range(T):
        r,g,b,w = map(int, lines[i+1].split())
        out = outs[i].strip()
        if out == 'Yes':
            odd_orig = (r%2)+(g%2)+(b%2)+(w%2)
            cond1 = odd_orig <= 1
            cond2 = False
            if r>=1 and g>=1 and b>=1:
                odd_op = ((r-1)%2)+((g-1)%2)+((b-1)%2)+((w+3)%2)
                cond2 = odd_op <= 1
            assert cond1 or cond2, f'Yes but condition fails: r={r},g={g},b={b},w={w}'

