def test_group3_unique(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    arr = list(map(int, lines[1].split()))
    out = run(x).strip()
    # recompute st_len and ed_len as in solution
    maxa = max(arr) if arr else 0
    def upd(ftree, x, v, size):
        while x <= size:
            ftree[x] = max(ftree[x], v)
            x += x & -x
    def qry(ftree, x):
        res = 0
        while x:
            res = max(res, ftree[x])
            x -= x & -x
        return res
    st_len = [0]*n
    ftree = [0]*(maxa+2)
    for i in range(n-1, -1, -1):
        st_len[i] = qry(ftree, maxa + 1 - arr[i] - 1) + 1
        upd(ftree, maxa + 1 - arr[i], st_len[i], maxa+1)
    ed_len = [0]*n
    ftree = [0]*(maxa+2)
    for i in range(n):
        ed_len[i] = qry(ftree, arr[i]-1) + 1
        upd(ftree, arr[i], ed_len[i], maxa+1)
    L = max(st_len)
    # count per st_len
    cnt = {}
    for i in range(n):
        if ed_len[i] + st_len[i] - 1 == L:
            cnt[st_len[i]] = cnt.get(st_len[i], 0) + 1
    for i,ch in enumerate(out):
        if ch == '3':
            assert ed_len[i] + st_len[i] - 1 == L, f'Index {i} marked 3 but not on LIS'
            assert cnt.get(st_len[i], 0) == 1, f'Index {i} marked 3 but st_len count >1'
        elif ch == '2':
            assert ed_len[i] + st_len[i] - 1 == L, f'Index {i} marked 2 but not on LIS'
