def test_output_length(run, x):
    output = run(x).strip().split()
    n = int(x.split('\n')[0].strip())
    assert len(output) == n, f'Expected {n} numbers, got {len(output)}'

def test_non_decreasing(run, x):
    output = list(map(int, run(x).strip().split()))
    for i in range(1, len(output)):
        assert output[i] >= output[i-1], f'Sequence not non-decreasing at position {i}: {output[i-1]} -> {output[i]}'

def test_first_value_is_one(run, x):
    output = list(map(int, run(x).strip().split()))
    assert output[0] == 1, f'First value must be 1, got {output[0]}'

def test_last_value_leaves_bound(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n == 1:
        leaves = 1
    else:
        parents = list(map(int, lines[1].split()))
        # count leaves
        children = [0]*n
        for p in parents:
            children[p-1] += 1
        leaves = sum(1 for c in children if c == 0)
    output = list(map(int, run(x).strip().split()))
    assert output[-1] <= leaves, f'Last value {output[-1]} exceeds number of leaves {leaves}'

def test_all_values_between_one_and_leaves(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n == 1:
        leaves = 1
    else:
        parents = list(map(int, lines[1].split()))
        children = [0]*n
        for p in parents:
            children[p-1] += 1
        leaves = sum(1 for c in children if c == 0)
    output = list(map(int, run(x).strip().split()))
    for i, val in enumerate(output):
        assert 1 <= val <= leaves, f'Value {val} at position {i} outside [1, {leaves}]'

def test_consistency_with_leaf_counts(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    # compute leaf counts per subtree
    parents = [0]*n
    if n > 1:
        p_list = list(map(int, lines[1].split()))
        for i, p in enumerate(p_list, start=2):
            parents[i-1] = p-1  # zero-index
    children = [[] for _ in range(n)]
    for i in range(1, n):
        children[parents[i]].append(i)
    leaf_count = [0]*n
    def dfs(v):
        if not children[v]:
            leaf_count[v] = 1
        else:
            total = 0
            for u in children[v]:
                dfs(u)
                total += leaf_count[u]
            leaf_count[v] = total
    dfs(0)
    expected = sorted(leaf_count)
    output = list(map(int, run(x).strip().split()))
    assert output == expected, f'Output does not match sorted leaf counts. Expected {expected}, got {output}'

def test_sum_of_output_values_bound(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    leaves = 1 if n==1 else sum(1 for _ in range(n) if True)  # need actual leaves count
    if n > 1:
        parents = list(map(int, lines[1].split()))
        children = [0]*n
        for p in parents:
            children[p-1] += 1
        leaves = sum(1 for c in children if c == 0)
    output = list(map(int, run(x).strip().split()))
    # The sum of output values is at least n (since each >=1) and at most n*leaves (crude bound)
    total = sum(output)
    assert n <= total <= n * leaves, f'Sum {total} out of bounds [n={n}, n*leaves={n*leaves}]'

def test_monotonic_increase_by_at_most_one(run, x):
    output = list(map(int, run(x).strip().split()))
    for i in range(1, len(output)):
        diff = output[i] - output[i-1]
        assert 0 <= diff <= 1, f'Jump by {diff} at position {i} from {output[i-1]} to {output[i]}'

def test_last_value_equals_leaves_for_star(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n > 1 and lines[1].strip() != '':
        parents = list(map(int, lines[1].split()))
        # check if it's a star: all parents are 1
        if all(p == 1 for p in parents):
            leaves = n-1
            output = list(map(int, run(x).strip().split()))
            assert output[-1] == leaves, f'For star tree, last value should be {leaves}, got {output[-1]}'

def test_consistency_with_examples(run, x):
    # If the input matches one of the provided examples, check the output matches.
    examples = {
        "3\n1 1\n": "1 1 2",
        "5\n1 1 3 3\n": "1 1 1 2 3",
        "1\n\n": "1"
    }
    normalized = x.strip() + '\n' if not x.endswith('\n') else x.strip()
    for inp, out in examples.items():
        if inp.strip() == normalized.strip():
            expected = out.strip()
            got = run(x).strip()
            assert got == expected, f'Example mismatch: expected {expected!r}, got {got!r}'

