def test_output_format(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    assert 1 <= len(lines) <= 2, 'output must have 1 or 2 lines'
    if len(lines) == 1:
        # count line only, implies zero good cars, second line omitted
        cnt = int(lines[0].strip())
        assert cnt == 0, 'if only one line, count must be 0'
    else:
        cnt_line, idx_line = lines[0].strip(), lines[1].strip()
        cnt = int(cnt_line)
        if cnt == 0:
            assert idx_line == '', 'second line must be empty for zero good cars'
        else:
            indices = list(map(int, idx_line.split()))
            assert len(indices) == cnt, 'number of indices must match count'
            assert indices == sorted(indices), 'indices must be sorted increasing'
            assert all(1 <= i <= int(x.split('\n')[0]) for i in indices), 'indices out of range'
            assert len(set(indices)) == cnt, 'indices must be distinct'

def test_good_cars_no_turnover(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    n = int(x.split('\n')[0])
    a = [list(map(int, line.split())) for line in x.strip().split('\n')[1:1+n]]
    if len(lines) == 1:
        good = []
    else:
        cnt = int(lines[0].strip())
        if cnt == 0:
            good = []
        else:
            good = list(map(int, lines[1].strip().split()))
    # verify each good car has no 1 or 3 in its row (except diagonal)
    for idx in good:
        i = idx - 1
        for j in range(n):
            if i == j:
                continue
            assert a[i][j] != 1 and a[i][j] != 3, f'car {idx} turned over in collision with {j+1}'

def test_bad_cars_turned_over(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    n = int(x.split('\n')[0])
    a = [list(map(int, line.split())) for line in x.strip().split('\n')[1:1+n]]
    if len(lines) == 1:
        good = []
    else:
        cnt = int(lines[0].strip())
        if cnt == 0:
            good = []
        else:
            good = list(map(int, lines[1].strip().split()))
    good_set = set(good)
    all_cars = set(range(1, n+1))
    for idx in all_cars - good_set:
        i = idx - 1
        found = False
        for j in range(n):
            if i == j:
                continue
            if a[i][j] == 1 or a[i][j] == 3:
                found = True
                break
        assert found, f'car {idx} not in good list but never turned over'

def test_count_range(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    n = int(x.split('\n')[0])
    if len(lines) == 1:
        cnt = int(lines[0].strip())
    else:
        cnt = int(lines[0].strip())
    assert 0 <= cnt <= n, 'count of good cars must be between 0 and n'

def test_all_zero_or_two_rows(run, x):
    # if a row contains only 0 or 2 (except diagonal), then that car never turned over
    n = int(x.split('\n')[0])
    a = [list(map(int, line.split())) for line in x.strip().split('\n')[1:1+n]]
    # compute which cars are good by definition
    def is_good(i):
        for j in range(n):
            if i == j:
                continue
            if a[i][j] == 1 or a[i][j] == 3:
                return False
        return True
    expected_good = [i+1 for i in range(n) if is_good(i)]
    out = run(x)
    lines = out.strip().split('\n')
    if len(lines) == 1:
        actual_good = []
    else:
        cnt = int(lines[0].strip())
        if cnt == 0:
            actual_good = []
        else:
            actual_good = list(map(int, lines[1].strip().split()))
    # This test only triggers if the row has no 1 or 3 at all.
    # But we can't assume the output matches expected_good because that would be re-solving.
    # Instead, we can check a weaker property: if all rows have no 1 or 3, then all cars are good.
    all_no_turnover = all(is_good(i) for i in range(n))
    if all_no_turnover:
        assert set(actual_good) == set(range(1, n+1)), 'all cars should be good when none turned over'

def test_any_one_or_three_not_good(run, x):
    n = int(x.split('\n')[0])
    a = [list(map(int, line.split())) for line in x.strip().split('\n')[1:1+n]]
    out = run(x)
    lines = out.strip().split('\n')
    if len(lines) == 1:
        good = []
    else:
        cnt = int(lines[0].strip())
        if cnt == 0:
            good = []
        else:
            good = list(map(int, lines[1].strip().split()))
    good_set = set(good)
    for i in range(n):
        if any(a[i][j] == 1 or a[i][j] == 3 for j in range(n) if i != j):
            assert (i+1) not in good_set, f'car {i+1} turned over but listed as good'

def test_second_line_matches_count(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    if len(lines) == 1:
        cnt = int(lines[0].strip())
        assert cnt == 0, 'single line implies zero good cars'
    else:
        cnt = int(lines[0].strip())
        second = lines[1].strip()
        if cnt == 0:
            assert second == '', 'second line must be empty for zero good cars'
        else:
            indices = list(map(int, second.split()))
            assert len(indices) == cnt, 'second line length must match count'

def test_indices_in_range(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    n = int(x.split('\n')[0])
    if len(lines) == 2:
        cnt = int(lines[0].strip())
        if cnt > 0:
            indices = list(map(int, lines[1].strip().split()))
            for idx in indices:
                assert 1 <= idx <= n, f'index {idx} out of range 1..{n}'

def test_metamorphic_swap(run, x):
    # swap car 1 and car 2 in the input (rows and columns)
    # the set of good cars should swap accordingly
    n = int(x.split('\n')[0])
    if n < 2:
        return  # nothing to swap
    lines_in = x.strip().split('\n')
    a = [list(map(int, line.split())) for line in lines_in[1:1+n]]
    # create swapped matrix
    # swap rows 0 and 1
    b = [row[:] for row in a]
    b[0], b[1] = b[1], b[0]
    # swap columns 0 and 1 in each row
    for row in b:
        row[0], row[1] = row[1], row[0]
    # build new input
    new_input = f'{n}\n' + '\n'.join(' '.join(map(str, row)) for row in b)
    out1 = run(x)
    out2 = run(new_input)
    lines1 = out1.strip().split('\n')
    lines2 = out2.strip().split('\n')
    if len(lines1) == 1:
        good1 = []
    else:
        cnt1 = int(lines1[0].strip())
        if cnt1 == 0:
            good1 = []
        else:
            good1 = list(map(int, lines1[1].strip().split()))
    if len(lines2) == 1:
        good2 = []
    else:
        cnt2 = int(lines2[0].strip())
        if cnt2 == 0:
            good2 = []
        else:
            good2 = list(map(int, lines2[1].strip().split()))
    # map indices: 1<->2, others unchanged
    def swap_idx(idx):
        if idx == 1:
            return 2
        elif idx == 2:
            return 1
        else:
            return idx
    good1_swapped = sorted(swap_idx(i) for i in good1)
    assert sorted(good2) == good1_swapped, 'swapping cars 1 and 2 should swap indices in output'

def test_certificate_verify(run, x):
    # verify that every claimed good car indeed has no 1 or 3 in its row
    # and that every car not claimed has at least one 1 or 3.
    n = int(x.split('\n')[0])
    a = [list(map(int, line.split())) for line in x.strip().split('\n')[1:1+n]]
    out = run(x)
    lines = out.strip().split('\n')
    if len(lines) == 1:
        good = []
    else:
        cnt = int(lines[0].strip())
        if cnt == 0:
            good = []
        else:
            good = list(map(int, lines[1].strip().split()))
    good_set = set(good)
    # check each good car
    for idx in good_set:
        i = idx - 1
        for j in range(n):
            if i == j:
                continue
            if a[i][j] == 1 or a[i][j] == 3:
                assert False, f'car {idx} listed as good but turned over with {j+1}'
    # check each non-good car
    for idx in set(range(1, n+1)) - good_set:
        i = idx - 1
        found = False
        for j in range(n):
            if i == j:
                continue
            if a[i][j] == 1 or a[i][j] == 3:
                found = True
                break
        assert found, f'car {idx} not listed as good but never turned over'

