def test_metamorphic_swap(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    w = [list(map(int, line.split())) for line in lines[1:1+n]]
    # swap rows and columns 0 and 1 if n>=2
    if n < 2:
        return
    swapped_w = [[0]*n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            ii = i
            jj = j
            if i == 0:
                ii = 1
            elif i == 1:
                ii = 0
            if j == 0:
                jj = 1
            elif j == 1:
                jj = 0
            swapped_w[ii][jj] = w[i][j]
    swapped_input = f'{n}\n' + '\n'.join(' '.join(str(v) for v in row) for row in swapped_w)
    out1 = run(x).strip().split('\n')
    out2 = run(swapped_input).strip().split('\n')
    a1 = [list(map(float, line.split())) for line in out1[:n]]
    b1 = [list(map(float, line.split())) for line in out1[n:2*n]]
    a2 = [list(map(float, line.split())) for line in out2[:n]]
    b2 = [list(map(float, line.split())) for line in out2[n:2*n]]
    for i in range(n):
        for j in range(n):
            ii = i
            jj = j
            if i == 0:
                ii = 1
            elif i == 1:
                ii = 0
            if j == 0:
                jj = 1
            elif j == 1:
                jj = 0
            if abs(a1[i][j] - a2[ii][jj]) > 1e-4:
                assert False, f'A not invariant under swap'
            if abs(b1[i][j] - (-b2[ii][jj] if i!=j else 0)) > 1e-4:
                assert False, f'B not antisymmetrically invariant under swap'

