def test_single_suffix_masu_yields_japanese(run, x):
    if x.strip().endswith('masu\n') and len(x.strip()) == 5:
        assert run(x).strip() == 'JAPANESE'


def test_single_suffix_mnida_yields_korean(run, x):
    if x.strip().endswith('mnida\n') and len(x.strip()) == 6:
        assert run(x).strip() == 'KOREAN'


def test_metamorphic_same_language_suffix_swap(run, x):
    # For Japanese, swapping 'desu' with 'masu' should not change the answer.
    # Construct a new valid sentence by replacing the suffix if it's one of those.
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    t = int(lines[0])
    if t != 1:
        return
    s = lines[1]
    if s.endswith('desu'):
        s2 = s[:-4] + 'masu'
        out1 = run(x).strip()
        out2 = run(f'1\n{s2}\n').strip()
        assert out1 == out2, f'Swapping desu/masu changed language: {out1} vs {out2}'
    elif s.endswith('masu'):
        s2 = s[:-4] + 'desu'
        out1 = run(x).strip()
        out2 = run(f'1\n{s2}\n').strip()
        assert out1 == out2, f'Swapping masu/desu changed language: {out1} vs {out2}'


