def test_metamorphic_add_prefix(run, x):
    # Adding a prefix before the suffix should not change the language.
    # Because the language depends only on the suffix, not the preceding characters.
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    t = int(lines[0])
    if t != 1:
        return
    s = lines[1]
    # Insert a harmless prefix (a single letter followed by underscore)
    # ensuring no consecutive underscores and no trailing/leading underscores.
    # Since the original s has no leading underscore, we can prepend 'a_'
    # only if s does not start with underscore (which it doesn't by spec).
    s2 = 'a_' + s
    out1 = run(x).strip()
    out2 = run(f'1\n{s2}\n').strip()
    assert out1 == out2, f'Adding prefix changed language: {out1} vs {out2}'

