def test_output_matches_last_char(run, x):
    # From spec: suffixes end with 'o' (po), 'u' (desu, masu), 'a' (mnida).
    t = int(x.strip().split('\n')[0])
    sentences = x.strip().split('\n')[1:1+t]
    outputs = run(x).strip().split('\n')
    for s, out in zip(sentences, outputs):
        last_char = s[-1]
        if out == 'FILIPINO':
            assert last_char == 'o', f'FILIPINO but last char {last_char} not o'
        elif out == 'JAPANESE':
            assert last_char == 'u', f'JAPANESE but last char {last_char} not u'
        elif out == 'KOREAN':
            assert last_char == 'a', f'KOREAN but last char {last_char} not a'

def test_filipino_ends_with_po(run, x):
    t = int(x.strip().split('\n')[0])
    sentences = x.strip().split('\n')[1:1+t]
    outputs = run(x).strip().split('\n')
    for s, out in zip(sentences, outputs):
        if out == 'FILIPINO':
            assert s.endswith('po'), f'FILIPINO but sentence does not end with po: {s}'

def test_japanese_ends_with_desu_or_masu(run, x):
    t = int(x.strip().split('\n')[0])
    sentences = x.strip().split('\n')[1:1+t]
    outputs = run(x).strip().split('\n')
    for s, out in zip(sentences, outputs):
        if out == 'JAPANESE':
            assert s.endswith('desu') or s.endswith('masu'), f'JAPANESE but sentence does not end with desu/masu: {s}'

def test_korean_ends_with_mnida(run, x):
    t = int(x.strip().split('\n')[0])
    sentences = x.strip().split('\n')[1:1+t]
    outputs = run(x).strip().split('\n')
    for s, out in zip(sentences, outputs):
        if out == 'KOREAN':
            assert s.endswith('mnida'), f'KOREAN but sentence does not end with mnida: {s}'

def test_certificate_all_cases(run, x):
    # Combined certificate: output language must match the suffix.
    t = int(x.strip().split('\n')[0])
    sentences = x.strip().split('\n')[1:1+t]
    outputs = run(x).strip().split('\n')
    for s, out in zip(sentences, outputs):
        if s.endswith('po'):
            assert out == 'FILIPINO', f'Sentence ends with po but output is {out}'
        elif s.endswith('desu') or s.endswith('masu'):
            assert out == 'JAPANESE', f'Sentence ends with desu/masu but output is {out}'
        elif s.endswith('mnida'):
            assert out == 'KOREAN', f'Sentence ends with mnida but output is {out}'
        else:
            raise AssertionError(f'Invalid suffix: {s}')

def test_metamorphic_duplicate(run, x):
    # Duplicate each test case: the output for each duplicate should be the same.
    lines = x.strip().split('\n')
    t = int(lines[0])
    if t == 0:
        return
    sentences = lines[1:1+t]
    # Build input with each sentence duplicated
    new_t = 2 * t
    new_input = f'{new_t}\n' + '\n'.join(sentences + sentences)
    outputs = run(new_input).strip().split('\n')
    # Each pair should be identical
    for i in range(t):
        assert outputs[i] == outputs[i + t], f'Duplicate mismatch: {outputs[i]} vs {outputs[i+t]}'

def test_metamorphic_reorder(run, x):
    # Reordering test cases does not change the answer per case.
    lines = x.strip().split('\n')
    t = int(lines[0])
    if t <= 1:
        return
    sentences = lines[1:1+t]
    # Run original
    orig_outputs = run(x).strip().split('\n')
    # Build reversed order
    rev_input = f'{t}\n' + '\n'.join(reversed(sentences))
    rev_outputs = run(rev_input).strip().split('\n')
    # The set of outputs should be the same (order reversed)
    for o, r in zip(reversed(orig_outputs), rev_outputs):
        assert o == r, f'Reordering changed output: {o} vs {r}'

def test_no_extra_output(run, x):
    # Output must have exactly t lines.
    t = int(x.strip().split('\n')[0])
    outputs = run(x).strip().split('\n')
    if outputs == ['']:
        assert t == 0, 'Empty output but t>0'
    else:
        assert len(outputs) == t, f'Expected {t} lines, got {len(outputs)}'

def test_case_insensitivity(run, x):
    # The input uses only lowercase and underscores, but the output must be uppercase.
    outputs = run(x).strip().split('\n')
    for out in outputs:
        assert out.isupper(), f'Output not uppercase: {out}'

