def test_output_shape(run, x):
    output = run(x).strip()
    assert output in ("Mishka", "Chris", "Friendship is magic!^^"), f"Invalid output: {output}"

def test_swap_players(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    swapped_lines = [lines[0]]
    for i in range(1, n+1):
        a, b = lines[i].split()
        swapped_lines.append(f"{b} {a}")
    swapped_x = '\n'.join(swapped_lines)
    out1 = run(x).strip()
    out2 = run(swapped_x).strip()
    if out1 == "Mishka":
        assert out2 == "Chris"
    elif out1 == "Chris":
        assert out2 == "Mishka"
    else:
        assert out2 == "Friendship is magic!^^"

def test_add_tie_round(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    new_n = n + 1
    new_lines = [str(new_n)] + lines[1:] + ["3 3"]
    new_x = '\n'.join(new_lines)
    out1 = run(x).strip()
    out2 = run(new_x).strip()
    assert out1 == out2, f"Adding a tie round changed winner: {out1} -> {out2}"

