def test_a_in_range(run, x):
    n, m = map(int, x.strip().split())
    a = int(run(x).strip())
    assert 1 <= a <= n

def test_win_count_positive(run, x):
    n, m = map(int, x.strip().split())
    if n == 1:
        return  # probability 0
    a = int(run(x).strip())
    # compute win count
    if a > m:
        import math
        win = n - math.ceil((a + m + 1) / 2) + 1
    elif a < m:
        win = (a + m - 1) // 2
    else:
        win = 0
    assert win > 0

def test_better_than_m_minus_1(run, x):
    n, m = map(int, x.strip().split())
    a = int(run(x).strip())
    if m - 1 >= 1:
        # compute win count for a and for m-1
        def win_count(a_val, m_val, n_val):
            if a_val > m_val:
                import math
                return n_val - math.ceil((a_val + m_val + 1) / 2) + 1
            elif a_val < m_val:
                return (a_val + m_val - 1) // 2
            else:
                return 0
        win_a = win_count(a, m, n)
        win_other = win_count(m - 1, m, n)
        assert win_a >= win_other

def test_better_than_m_plus_1(run, x):
    n, m = map(int, x.strip().split())
    a = int(run(x).strip())
    if m + 1 <= n:
        def win_count(a_val, m_val, n_val):
            if a_val > m_val:
                import math
                return n_val - math.ceil((a_val + m_val + 1) / 2) + 1
            elif a_val < m_val:
                return (a_val + m_val - 1) // 2
            else:
                return 0
        win_a = win_count(a, m, n)
        win_other = win_count(m + 1, m, n)
        assert win_a >= win_other

def test_symmetry_mirror(run, x):
    n, m = map(int, x.strip().split())
    a = int(run(x).strip())
    # mirrored input: n' = n, m' = n - m + 1
    m2 = n - m + 1
    input2 = f"{n} {m2}\n"
    a2 = int(run(input2).strip())
    # expected mirrored a: n - a + 1
    assert a2 == n - a + 1

def test_m1_case(run, x):
    n, m = map(int, x.strip().split())
    if m == 1 and n > 1:
        a = int(run(x).strip())
        assert a == 2

def test_mn_case(run, x):
    n, m = map(int, x.strip().split())
    if m == n and n > 1:
        a = int(run(x).strip())
        assert a == n - 1

def test_n1_case(run, x):
    n, m = map(int, x.strip().split())
    if n == 1:
        a = int(run(x).strip())
        assert a == 1

def test_a_not_equal_m(run, x):
    n, m = map(int, x.strip().split())
    if n > 1:
        a = int(run(x).strip())
        assert a != m

def test_win_count_maximal_adjacent(run, x):
    n, m = map(int, x.strip().split())
    a = int(run(x).strip())
    # compute win count for a
    def win_count(a_val, m_val, n_val):
        if a_val > m_val:
            import math
            return n_val - math.ceil((a_val + m_val + 1) / 2) + 1
        elif a_val < m_val:
            return (a_val + m_val - 1) // 2
        else:
            return 0
    win_a = win_count(a, m, n)
    # check both adjacent numbers
    candidates = []
    if m - 1 >= 1:
        candidates.append(m - 1)
    if m + 1 <= n:
        candidates.append(m + 1)
    for cand in candidates:
        if cand != a:
            w = win_count(cand, m, n)
            # a must be at least as good as any adjacent
            assert win_a >= w
    # also check that a is either m-1 or m+1 (optimal is always adjacent)
    # but that's a property of correct solution, not necessarily required? Actually, the problem says if multiple a give same probability, choose smallest. So there could be non-adjacent a with same probability? Possibly when n is small? Let's not assert that.

