    # Create a variant where we replace 'r' with another consonant, e.g., 'l',
    # and keep categories same. The answer must stay Yes.
    s, t = x.strip().split('\n')
    if len(s) != len(t):
        return
    vowels = set('aeiou')
    # Build modified strings where each 'r' becomes 'l' (both consonants)
    s2 = ''.join('l' if ch == 'r' else ch for ch in s)
