    {
      "name": "test_single_row",
      "source": "def test_single_row(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if n == 1 and all(c == 'X' for row in lines[1:] for c in row if c != '.'):
        # Actually check if the row is all X's
        row = lines[1]
        if all(c == 'X' for c in row):
            assert run(x).strip() == 'YES', 'A single full row of X's must form a rectangle with two copies'"
    },
    {
      "name": "test_single_column",
      "source": "def test_single_column(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if m == 1:
        col = [line[0] for line in lines[1:]]
        if all(c == 'X' for c in col):
            assert run(x).strip() == 'YES', 'A single full column of X's must form a rectangle with two copies'"
    },
    {
      "name": "test_duplicate_vertical",
      "source": "def test_duplicate_vertical(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    # Check if the piece is a rectangle (all rows same X pattern)
    rows = lines[1:]
    first_row = rows[0]
    if all(row == first_row for row in rows):
        # Piece is a rectangle
        # Build a new input with double the rows (stack vertically)
        new_n = n * 2
        new_input = f'{new_n} {m}\n' + '\n'.join([first_row] * new_n)
        # The answer should still be YES because two copies of a rectangle can be placed side-by-side
        assert run(new_input).strip() == 'YES', 'Duplicating a rectangular piece vertically should still allow forming a rectangle'"
    },
    {
      "name": "test_full_grid",
      "source": "def test_full_grid(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    rows = lines[1:]
    if all(all(c == 'X' for c in row) for row in rows):
        assert run(x).strip() == 'YES', 'A full grid of X's must form a rectangle with two copies'"
    },
    {
      "name": "test_no_X_on_boundary_rows",
      "source": "def test_no_X_on_boundary_rows(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    rows = lines[1:]
    if n >= 3:
        first_row = rows[0]
        last_row = rows[-1]
        if 'X' not in first_row and 'X' not in last_row:
            # The piece is contained in middle rows
            # The answer must be either YES or NO, but we can check consistency: 
            # If the piece is symmetric, it might be YES. We just ensure output is valid.
            output = run(x).strip()
            assert output == 'YES' or output == 'NO', 'Output must be YES or NO'"
    },
    {
      "name": "test_single_X",
      "source": "def test_single_X(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    rows = lines[1:]
    total_X = sum(row.count('X') for row in rows)
    if total_X == 1:
        assert run(x).strip() == 'YES', 'A single X can always be placed with another to form a 1x2 rectangle'"
    },
    {
      "name": "test_2x2_block",
      "source": "def test_2x2_block(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if n == 2 and m == 2:
        rows = lines[1:]
        if rows[0] == 'XX' and rows[1] == 'XX':
            assert run(x).strip() == 'YES', 'A 2x2 block must form a rectangle with two copies'"
    },
    {
      "name": "test_transpose_invariant",
      "source": "def test_transpose_invariant(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    rows = lines[1:]
    # Transpose the grid
    transposed = [''.join(rows[i][j] for i in range(n)) for j in range(m)]
    new_input = f'{m} {n}\n' + '\n'.join(transposed)
    # The answer should be the same as for the original
    original_out = run(x).strip()
    transposed_out = run(new_input).strip()
    assert original_out == transposed_out, 'Transposing the piece should not change the answer'"
    },
    {
      "name": "test_hollow_rectangle",
      "source": "def test_hollow_rectangle(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    rows = lines[1:]
    # Check if it's a hollow rectangle (frame): first and last row all X, middle rows have X at ends only
    if n >= 3 and m >= 3:
        first_row = rows[0]
        last_row = rows[-1]
        if all(c == 'X' for c in first_row) and all(c == 'X' for c in last_row):
            middle_ok = all(row[0] == 'X' and row[-1] == 'X' and row[1:-1].count('X') == 0 for row in rows[1:-1])
            if middle_ok:
                # It's a hollow rectangle
                assert run(x).strip() == 'NO', 'Two hollow rectangles cannot form a solid rectangle without holes'"
    }
  ]
}

