def test_output_is_integer_or_minus_one(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    # otherwise must be a non‑negative integer
    assert out.isdigit() or (out[0] == '-' and out[1:].isdigit()), f'Output {repr(out)} is not an integer or -1'
    val = int(out)
    assert val >= 0, f'Output {val} is negative but not -1'

def test_if_already_m_perfect_then_zero(run, x):
    import sys
    xv, yv, mv = map(int, x.strip().split())
    if xv >= mv or yv >= mv:
        out = run(x).strip()
        assert out == '0', f'Already m-perfect, should output 0, got {out}'

def test_if_both_nonpositive_and_m_positive_then_impossible(run, x):
    import sys
    xv, yv, mv = map(int, x.strip().split())
    if xv <= 0 and yv <= 0 and mv > 0:
        out = run(x).strip()
        assert out == '-1', f'Both non‑positive and m>0, should output -1, got {out}'

def test_operation_count_non_negative_or_minus_one(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    k = int(out)
    assert k >= 0, f'Operation count {k} is negative'

def test_symmetry_swapping_x_and_y(run, x):
    parts = x.strip().split()
    xv, yv, mv = map(int, parts)
    swapped = f'{yv} {xv} {mv}\n'
    out1 = run(x).strip()
    out2 = run(swapped).strip()
    assert out1 == out2, f'Swapping x,y changed output: {out1} vs {out2}'

def test_if_m_nonpositive_then_zero_steps_suffice(run, x):
    xv, yv, mv = map(int, x.strip().split())
    if mv <= 0:
        # at least one of x,y is already >= mv because mv ≤ 0
        out = run(x).strip()
        assert out == '0', f'm ≤ 0, already m-perfect, should output 0, got {out}'

def test_negative_positive_case_verification(run, x):
    xv, yv, mv = map(int, x.strip().split())
    if xv <= 0 < yv and yv < mv:
        out = run(x).strip()
        if out == '-1':
            # verify impossibility by brute force on small inputs
            if abs(xv) <= 10 and abs(yv) <= 10 and abs(mv) <= 30:
                def can_reach(a, b, m, steps_left=10):
                    if a >= m or b >= m:
                        return True
                    if steps_left == 0:
                        return False
                    return can_reach(a+b, b, m, steps_left-1) or can_reach(a, a+b, m, steps_left-1)
                if can_reach(xv, yv, mv, 15):
                    assert False, 'Solution says -1 but reachable (small input)'
        else:
            k = int(out)
            # simulate k steps, always replacing the smaller (or negative) with sum
            a, b = xv, yv
            for _ in range(k):
                if a <= b:
                    a = a + b
                else:
                    b = a + b
            assert a >= mv or b >= mv, f'After {k} steps ({a},{b}) not m-perfect for m={mv}'

def test_lower_bound_steps_via_fibonacci(run, x):
    xv, yv, mv = map(int, x.strip().split())
    if xv > 0 and yv > 0 and mv > max(xv, yv):
        # minimal steps to reach m starting from x,y positive is at least
        # ceil(log_phi((m - max(x,y))/min(x,y) + 1)) something.
        # Simpler: if we always add the smaller to the larger (optimal),
        # after k steps the larger is F_{k}*min(x,y)+F_{k+1}*max(x,y)  (approx)
        # We require that >= m.
        # Instead of computing exact bound, we just simulate greedy for up to 100 steps
        # and ensure reported k is not larger than needed.
        a, b = min(xv, yv), max(xv, yv)
        needed = 0
        while b < mv and needed < 100:
            a, b = b, a + b
            needed += 1
        if b >= mv:
            out = run(x).strip()
            if out != '-1':
                k = int(out)
                assert k <= needed, f'Reported {k} steps but greedy achieves in {needed}'

def test_if_impossible_then_no_finite_steps_reach(run, x):
    xv, yv, mv = map(int, x.strip().split())
    out = run(x).strip()
    if out == '-1':
        # check that indeed it's impossible for small inputs
        if abs(xv) <= 10 and abs(yv) <= 10 and abs(mv) <= 30:
            def can_reach(a, b, m, steps_left=15):
                if a >= m or b >= m:
                    return True
                if steps_left == 0:
                    return False
                return can_reach(a+b, b, m, steps_left-1) or can_reach(a, a+b, m, steps_left-1)
            if can_reach(xv, yv, mv, 15):
                assert False, 'Solution says -1 but reachable (small input)'

def test_upper_bound_steps_by_exponential_growth(run, x):
    xv, yv, mv = map(int, x.strip().split())
    if xv > 0 and yv > 0 and mv > max(xv, yv):
        out = run(x).strip()
        if out != '-1':
            k = int(out)
            # with both positive, after k steps the larger is at least F_{k+2} * min(x,y)
            # where F_0=0, F_1=1. So F_{k+2} * min(x,y) <= m  => k cannot be too small.
            # We'll just check that k is not ridiculously large (>200) for moderate m.
            if mv <= 10**9:
                assert k <= 200, f'k={k} too large for m={mv}'

