def test_output_single_line(run, x):
    out = run(x).strip()
    lines = out.split('\n')
    assert len(lines) == 1, 'Output must be exactly one line'

def test_swap_whole_string(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    s = lines[1]
    swapped = s[::-1]
    new_input = f'{n}\n{swapped}\n'
    out1 = run(x).strip()
    out2 = run(new_input).strip()
    assert out1 == out2, 'Reversing whole string should not change answer (move operation is symmetric)'

def test_add_balanced_prefix(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    s = lines[1]
    new_s = '()' + s
    new_n = n + 2
    new_input = f'{new_n}\n{new_s}\n'
    out_orig = run(x).strip()
    out_new = run(new_input).strip()
    assert out_orig == out_new, 'Adding balanced prefix should not change answer'

