    out = run(x).strip()
    if out != 'Yes':
        return
    lines = x.strip().split('\n')
    n = int(lines[0])
    s = lines[1]
    def is_correct(t):
        bal = 0
        for ch in t:
            if ch == '(':
                bal += 1
            else:
                bal -= 1
            if bal < 0:
                return False
        return bal == 0
    found = False
    for i in range(n):
        ch = s[i]
        for j in range(n+1):
            if j == i:
                continue
            new_s = list(s)
            new_s.pop(i)
            new_s.insert(j, ch)
            if is_correct(new_s):
                found = True
                break
        if found:
            break
    assert found, 'Answer is Yes but no single move yields a correct sequence'

