def test_feasible_matching_exists(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    atk = []
    defe = []
    for i in range(1, 1+n):
        pos, val = lines[i].split()
        if pos == 'ATK':
            atk.append(int(val))
        else:
            defe.append(int(val))
    ciel = [int(lines[i]) for i in range(1+n, 1+n+m)]
    out = int(run(x).strip())
    if out == 0:
        return  # zero is always possible
    # we need to check that out can be achieved by some matching
    # brute force over subsets of ciel (m <= 100, but input list has m <= 4)
    # We'll generate all matchings to ATK cards and verify damage.
    from itertools import permutations
    best = 0
    for use_cnt in range(min(m, len(atk))+1):
        for ciel_sub in permutations(ciel, use_cnt):
            for atk_sub in permutations(atk, use_cnt):
                if all(c >= a for c, a in zip(ciel_sub, atk_sub)):
                    dmg = sum(c - a for c, a in zip(ciel_sub, atk_sub))
                    # remaining ciel cards can be used directly if no Jiro cards left
                    # but we also need to defeat all DEF cards first with remaining ciel
                    remaining_ciel = [c for c in ciel if c not in ciel_sub]
                    # match DEF cards
                    remaining_defe = defe[:]
                    for d in sorted(remaining_defe):
                        found = False
                        for c in remaining_ciel:
                            if c > d:
                                remaining_ciel.remove(c)
                                found = True
                                break
                        if not found:
                            break
                    else:
                        # all DEF defeated, can use remaining ciel directly
                        dmg += sum(remaining_ciel)
                        if dmg > best:
                            best = dmg
    assert out <= best  # answer cannot exceed best feasible

