def test_brute_force_small_all_i(run, x):
    import itertools
    MOD = 998244353
    K, N = map(int, x.split())
    if K > 4 or N > 4:
        return  # skip large inputs
    # brute-force all multisets of size N from {1..K}
    # generate all combinations with repetitions using itertools.combinations_with_replacement
    total_by_i = [0]*(2*K+1)  # index i from 0 to 2K, we'll use i from 2 to 2K
    for combo in itertools.combinations_with_replacement(range(1, K+1), N):
        # combo is sorted non-decreasing, dice indistinguishable
        ok = [True]*(2*K+1)  # ok[i] = True if no two different dice sum to i
        # we need to check all unordered pairs of indices (different positions)
        # but since dice are indistinguishable, we can consider counts of each value
        # For each pair of distinct values a<b, if a+b <= 2K, then any multiset containing at least one a and one b violates i=a+b.
        # For a=b, need at least two dice of value a to violate i=2a.
        # So we can compute counts.
        from collections import Counter
        cnt = Counter(combo)
        for a in range(1, K+1):
            for b in range(a, K+1):
                s = a + b
                if s > 2*K:
                    continue
                if a == b:
                    if cnt[a] >= 2:
                        ok[s] = False
                else:
                    if cnt[a] >= 1 and cnt[b] >= 1:
                        ok[s] = False
        for i in range(2, 2*K+1):
            if ok[i]:
                total_by_i[i] += 1
    output = run(x).strip()
    out_vals = [int(v) for v in output.split('\n')]
    for idx, i in enumerate(range(2, 2*K+1)):
        expected = total_by_i[i] % MOD
        assert out_vals[idx] == expected, f'For i={i}, expected {expected}, got {out_vals[idx]}'

def test_brute_force_small_i2(run, x):
    import itertools
    MOD = 998244353
    K, N = map(int, x.split())
    if K > 5 or N > 5:
        return
    # compute count for i=2 only
    total = 0
    for combo in itertools.combinations_with_replacement(range(1, K+1), N):
        cnt = {}
        for v in combo:
            cnt[v] = cnt.get(v, 0) + 1
        # condition violated if there are at least two dice showing 1 (since 1+1=2)
        if cnt.get(1, 0) >= 2:
            continue
        total += 1
    expected = total % MOD
    output = run(x).strip()
    out_vals = [int(v) for v in output.split('\n')]
    # i=2 corresponds to first output line
    assert out_vals[0] == expected, f'For i=2, expected {expected}, got {out_vals[0]}'

