def test_symmetry_odd_even(run, x):
    # Additional symmetry test focusing on the fact that the mapping a -> K+1-a also implies that the count for i should equal count for 2K+2-i.
    # This is essentially the same as test_symmetry, but we implement it differently as a cross-check.
    K = int(x.split()[0])
    output = run(x).strip()
    vals = [int(v) for v in output.split('\n')]
    for t in range(len(vals)):
        i = t + 2
        j = 2*K + 2 - i
        if 2 <= j <= 2*K:
            u = j - 2
            assert vals[t] == vals[u], f'Symmetry broken: i={i} vs i={j}: {vals[t]} != {vals[u]}'

