tests_src:
def test_output_is_yes_or_no(run, x):
    output = run(x).strip()
    assert output in ["Yes", "No"], f"Output must be 'Yes' or 'No', got '{output}'"

def test_output_ends_with_newline(run, x):
    output = run(x)
    assert output.endswith('\n'), "Output must end with newline"

def test_if_yes_then_factorable(run, x):
    output = run(x).strip()
    if output == "Yes":
        N = int(x.strip())
        # Check if N can be written as a*b with a,b in 1..9
        factorable = any(1 <= a <= 9 and 1 <= b <= 9 and a * b == N
                         for a in range(1, 10) for b in range(1, 10))
        assert factorable, f"N={N} is not factorable in 1..9 but output is Yes"

def test_if_no_then_not_factorable(run, x):
    output = run(x).strip()
    if output == "No":
        N = int(x.strip())
        factorable = any(1 <= a <= 9 and 1 <= b <= 9 and a * b == N
                         for a in range(1, 10) for b in range(1, 10))
        assert not factorable, f"N={N} is factorable in 1..9 but output is No"

def test_output_length_small(run, x):
    output = run(x).strip()
    assert len(output) in (2, 3), f"Output length must be 2 or 3, got {len(output)} (output: '{output}')"

def test_yes_on_1(run, x):
    # Since 1 is in the inputs, and 1 = 1*1, output must be Yes
    if x.strip() == "1":
        output = run(x).strip()
        assert output == "Yes", f"For N=1, output must be Yes, got {output}"

def test_no_on_prime_above_9(run, x):
    # Among given inputs, 2,3,5,7 are primes <=9 but factorable as 1*self, so they are Yes.
    # Primes >9 and <=100 are not factorable because one factor would be >9.
    # Among given inputs, 11,13,17,... are not listed, but we check if N is prime >9.
    N = int(x.strip())
    if N > 9:
        # Quick primality test for N <= 100
        is_prime = all(N % d != 0 for d in range(2, int(N**0.5)+1))
        if is_prime:
            output = run(x).strip()
            assert output == "No", f"For prime N={N} >9, output must be No, got {output}"

def test_yes_on_perfect_square_up_to_81(run, x):
    N = int(x.strip())
    if 1 <= N <= 81 and int(N**0.5)**2 == N:
        # Square root is integer between 1 and 9
        a = int(N**0.5)
        if 1 <= a <= 9:
            output = run(x).strip()
            assert output == "Yes", f"For perfect square N={N} (={a}*{a}), output must be Yes, got {output}"

def test_no_on_number_above_81_not_factorable(run, x):
    N = int(x.strip())
    if N > 81:
        # The maximum product of two numbers in 1..9 is 81, so any N>81 cannot be factorable.
        output = run(x).strip()
        assert output == "No", f"For N={N} >81, output must be No, got {output}"

def test_metamorphic_product_of_factors(run, x):
    # If we take a factor a in 1..9 and b in 1..9, their product N must yield Yes.
    # We can generate a few small products and check.
    # This is a metamorphic relation because we modify the input (choose a,b) and check consistency.
    # Since we don't know correct answer for original x, we only test on generated inputs.
    # We'll test a few fixed products: 1*1=1, 9*9=81, 2*3=6, etc.
    # We'll run the code on those generated inputs and verify they output Yes.
    # This doesn't depend on original x, but it's a property of the program on valid inputs.
    # It's allowed because we call run on new valid inputs.
    test_cases = ["1\n", "4\n", "6\n", "81\n", "72\n"]
    for tc in test_cases:
        out = run(tc).strip()
        assert out == "Yes", f"For input {tc.strip()}, expected Yes, got {out}"

