def test_output_is_yes_or_no(run, x):
    output = run(x).strip()
    assert output in ("Yes", "No"), f"Output must be 'Yes' or 'No', got '{output}'"

def test_yes_certificate(run, x):
    N = int(x.strip())
    output = run(x).strip()
    if output == "Yes":
        # verify there exists a,b in [1,9] with a*b == N
        found = False
        for a in range(1, 10):
            if N % a == 0:
                b = N // a
                if 1 <= b <= 9:
                    found = True
                    break
        assert found, f"Output is 'Yes' but no product of 1..9 equals {N}"

def test_no_certificate(run, x):
    N = int(x.strip())
    output = run(x).strip()
    if output == "No":
        # verify no a,b in [1,9] with a*b == N
        for a in range(1, 10):
            if N % a == 0:
                b = N // a
                if 1 <= b <= 9:
                    assert False, f"Output is 'No' but {a}*{b} = {N}"

def test_yes_certificate_reverse_loop(run, x):
    N = int(x.strip())
    output = run(x).strip()
    if output == "Yes":
        found = False
        for a in range(9, 0, -1):
            if N % a == 0:
                b = N // a
                if 1 <= b <= 9:
                    found = True
                    break
        assert found, f"Output is 'Yes' but no product found (reverse loop)"

def test_product_range_bound(run, x):
    N = int(x.strip())
    output = run(x).strip()
    if output == "Yes":
        # N must be between 1 and 81 inclusive
        assert 1 <= N <= 81, f"Output is 'Yes' but {N} > 81 cannot be product of 1..9"

def test_no_for_out_of_range(run, x):
    N = int(x.strip())
    if N > 81:
        output = run(x).strip()
        assert output == "No", f"For N={N} > 81, output must be 'No', got '{output}'"

def test_commutative(run, x):
    # If a*b works, b*a works too. Not directly checkable without answer.
