tests_src:
def test_non_negative_integer(run, x):
    out = run(x).strip()
    val = int(out)
    assert val >= 0 and out == str(val)

def test_upper_bound_N_cubed(run, x):
    N, K = map(int, x.strip().split())
    ans = int(run(x).strip())
    assert ans <= N**3

def test_monotonic_N_decrease(run, x):
    N, K = map(int, x.strip().split())
    if N == 1:
        return
    smaller = f"{N-1} {K}\n"
    ans_big = int(run(x).strip())
    ans_small = int(run(smaller).strip())
    assert ans_big >= ans_small

def test_K1_all_triples(run, x):
    N, K = map(int, x.strip().split())
    if K == 1:
        ans = int(run(x).strip())
        assert ans == N**3

def test_small_brute(run, x):
    N, K = map(int, x.strip().split())
    if N > 7 or K > 20:  # keep brute‑force cheap
        return
    ans = int(run(x).strip())
    cnt = 0
    for a in range(1, N+1):
        for b in range(1, N+1):
            for c in range(1, N+1):
                if (a+b)%K == 0 and (b+c)%K == 0 and (c+a)%K == 0:
                    cnt += 1
    assert ans == cnt

def test_mod_symmetry(run, x):
    N, K = map(int, x.strip().split())
    if N > K or K > 20:  # we need to enumerate residues, keep small
        return
    ans = int(run(x).strip())
    # count by residue classes
    from collections import defaultdict
    freq = defaultdict(int)
    for i in range(1, N+1):
        freq[i%K] += 1
    cnt = 0
    for r1 in freq:
        for r2 in freq:
            for r3 in freq:
                if (r1+r2)%K == 0 and (r2+r3)%K == 0 and (r3+r1)%K == 0:
                    cnt += freq[r1] * freq[r2] * freq[r3]
    assert ans == cnt

def test_N1_special(run, x):
    N, K = map(int, x.strip().split())
    if N != 1:
        return
    ans = int(run(x).strip())
    # only triple (1,1,1)
    if (1+1) % K == 0:  # K divides 2
        assert ans == 1
    else:
        assert ans == 0

def test_K_greater_than_N_brute(run, x):
    N, K = map(int, x.strip().split())
    if K <= N or K > 20:  # only when K>N and small enough to brute
        return
    ans = int(run(x).strip())
    cnt = 0
    for a in range(1, N+1):
        for b in range(1, N+1):
            for c in range(1, N+1):
                if (a+b)%K == 0 and (b+c)%K == 0 and (c+a)%K == 0:
                    cnt += 1
    assert ans == cnt

def test_metamorphic_double_K(run, x):
    N, K = map(int, x.strip().split())
    if K*2 > 200000:   # keep within constraints
        return
    bigger = f"{N} {K*2}\n"
    ans_orig = int(run(x).strip())
    ans_big = int(run(bigger).strip())
    # condition with 2K is stricter, so count cannot increase
    assert ans_orig >= ans_big

def test_answer_divisible_by_K_cubes(run, x):
    # Not a property, skip.
    # Instead, add a simple lower bound: for K even, at least max(cnt0, cnt2)^3
    N, K = map(int, x.strip().split())
    if K % 2 != 0:
        return
    ans = int(run(x).strip())
    cnt0 = sum(1 for i in range(1, N+1) if i % K == 0)
    cnt_half = sum(1 for i in range(1, N+1) if i % K == K//2)
    assert ans >= max(cnt0**3, cnt_half**3)

