tests_src:
def test_output_is_positive_integer(run, x):
    out = run(x).strip()
    assert out.isdigit() and int(out) >= 1

def test_output_at_most_digits_of_N(run, x):
    N = int(x.strip())
    out = int(run(x).strip())
    # Since A and B are positive integers and A*B=N, at least one of A,B is <= sqrt(N), but the maximum possible F is when A=1,B=N, so F = len(str(N)).
    assert out <= len(str(N))

def test_output_achievable_by_some_divisor_pair(run, x):
    N = int(x.strip())
    out = int(run(x).strip())
    # Check there exists a divisor a such that max(len(str(a)), len(str(N//a))) == out
    import math
    found = False
    for a in range(1, int(math.isqrt(N)) + 1):
        if N % a == 0:
            b = N // a
            if max(len(str(a)), len(str(b))) == out:
                found = True
                break
    assert found, f"No divisor pair yields F={out} for N={N}"

def test_output_is_minimum_possible(run, x):
    N = int(x.strip())
    out = int(run(x).strip())
    import math
    # The output must be <= F for every divisor pair
    for a in range(1, int(math.isqrt(N)) + 1):
        if N % a == 0:
            b = N // a
            if max(len(str(a)), len(str(b))) < out:
                assert False, f"Found pair ({a},{b}) with F smaller than output {out}"

def test_sample_case(run, x):
    if x == "10000\n":
        assert run(x).strip() == "3"

def test_N_equal_1(run, x):
    if x == "1\n":
        assert run(x).strip() == "1"

def test_even_N_with_even_best_divisor(run, x):
    # N=2: divisors (1,2) and (2,1). F(1,2)=1, F(2,1)=1. The solution might skip (2,1) because even? Still F=1.
    # N=8: divisors (1,8) F=1, (2,4) F=1, (4,2) F=1, (8,1) F=1. All yield F=1.
    # But if the code skips even divisors when N even, it might miss (2,4) and output 2 from (1,8).
    # So we test that output for N=8 is 1.
    if x == "8\n":
        assert run(x).strip() == "1"
    if x == "2\n":
        assert run(x).strip() == "1"

def test_output_symmetric(run, x):
    # F(A,B) = F(B,A), so the minimum over all pairs is symmetric.
    # No explicit metamorphic relation, but we can verify that the output is consistent with swapping.
    # Actually, this is already covered by the divisor enumeration.
    pass

def test_relate_divisors(run, x):
    # Metamorphic: If we multiply N by a square k^2, the minimal F for N*k^2 cannot be less than for N.
    # Not straightforward to apply without knowing correct answer for both.
    # Instead, we can test that for any divisor d of N, the output for N is <= max(len(str(d)), len(str(N//d))).
    # This is already covered by test_output_is_minimum_possible.
    pass

def test_output_integer(run, x):
    out = run(x).strip()
    # Ensure it's a valid integer (no extra whitespace, newline).
    int(out)  # will raise if not integer
    assert out == out.strip()

