def test_integer_output(run, x):
    out = run(x).strip()
    # Must be a valid integer
    int(out)

def test_non_negative(run, x):
    out = int(run(x).strip())
    assert out >= 0

def test_monotonicity(run, x):
    N = int(x.strip())
    out = int(run(x).strip())
    if N > 1:
        prev_out = int(run(str(N-1)).strip())
        assert out >= prev_out

def test_bound_by_odd_numbers(run, x):
    N = int(x.strip())
    out = int(run(x).strip())
    # Total odd numbers up to N
    odd_count = (N + 1) // 2
    assert out <= odd_count

def test_exact_zero_for_small_N(run, x):
    N = int(x.strip())
    out = int(run(x).strip())
    if N < 105:
        assert out == 0

def test_exact_five_for_N_200(run, x):
    N = int(x.strip())
    out = int(run(x).strip())
    if N == 200:
        assert out == 5

def test_divisor_count_certificate(run, x):
    N = int(x.strip())
    out = int(run(x).strip())
    # Brute-force verification for N ≤ 200
    count = 0
    for k in range(1, N+1, 2):
        d = 0
        for i in range(1, int(k**0.5)+1):
            if k % i == 0:
                d += 1
                if i != k // i:
                    d += 1
        if d == 8:
            count += 1
    assert out == count

def test_answer_less_than_or_equal_N(run, x):
    N = int(x.strip())
    out = int(run(x).strip())
    # The count cannot exceed N (trivial bound)
    assert out <= N

def test_output_parity(run, x):
    out = int(run(x).strip())
    # The count is a non‑negative integer, no parity restriction needed.
    # This test is vacuous but safe.
    assert out % 1 == 0

def test_consistency_with_max_odd_eight_divisor(run, x):
    N = int(x.strip())
    out = int(run(x).strip())
    # Find the largest odd number ≤ N with exactly 8 divisors
    best = 0
    for k in range(1, N+1, 2):
        d = 0
        for i in range(1, int(k**0.5)+1):
            if k % i == 0:
                d += 1
                if i != k // i:
                    d += 1
        if d == 8:
            best = k
    if best > 0:
        # The count for N must equal the count for best
        out_best = int(run(str(best)).strip())
        assert out == out_best

