def test_is_alphabetic(run, x):
    ans = run(x).strip()
    assert ans.isalpha(), f'Output must be alphabetic, got {ans}'

def test_case_flip_relation(run, x):
    orig = x.strip()
    # only one character
    if orig.isupper():
        flipped = orig.lower()
        expected_orig = 'A'
        expected_flipped = 'a'
    else:
        flipped = orig.upper()
        expected_orig = 'a'
        expected_flipped = 'A'
    # run on original
    out_orig = run(x).strip()
    # run on flipped input
    out_flipped = run(flipped + '\n').strip()
    # relation: output for uppercase is 'A', for lowercase is 'a'
    if orig.isupper():
        assert out_orig == 'A', f'Uppercase input should output A, got {out_orig}'
        assert out_flipped == 'a', f'Lowercase input should output a, got {out_flipped}'
    else:
        assert out_orig == 'a', f'Lowercase input should output a, got {out_orig}'
        assert out_flipped == 'A', f'Uppercase input should output A, got {out_flipped}'

def test_certificate_uppercase_A(run, x):
    orig = x.strip()
    ans = run(x).strip()
    if 'A' <= orig <= 'Z':
        assert ans == 'A', f'Uppercase input {orig} must output A, got {ans}'
    else:
        assert ans == 'a', f'Lowercase input {orig} must output a, got {ans}'

def test_output_matches_case_by_ord(run, x):
    orig = x.strip()
    o = ord(orig)
    ans = run(x).strip()
    if 65 <= o <= 90:
        assert ans == 'A', f'Uppercase by ord must output A, got {ans}'
    elif 97 <= o <= 122:
        assert ans == 'a', f'Lowercase by ord must output a, got {ans}'

def test_identity_on_A(run, x):
    # If input is 'A', output must be 'A'
    if x.strip() == 'A':
        ans = run(x).strip()
        assert ans == 'A', f"Input A must output A, got {ans}"

def test_identity_on_a(run, x):
    # If input is 'a', output must be 'a'
    if x.strip() == 'a':
        ans = run(x).strip()
        assert ans == 'a', f"Input a must output a, got {ans}"

def test_no_extra_output(run, x):
    ans = run(x)
    # output should be exactly 'A' or 'a' plus newline
    assert ans in ('A\n', 'a\n'), f'Output must be exactly A or a with newline, got {repr(ans)}'

