    assert out in ('ABC', 'ABD'), f'Output {out} not ABC or ABD'

def test_ABC_implies_N_lt_1000(run, x):
    out = run(x).strip()
    n = int(x.strip())
    if out == 'ABC':
        assert n < 1000, f'ABC output for N={n} >=1000'

def test_ABD_implies_N_ge_1000(run, x):
    out = run(x).strip()
    n = int(x.strip())
    if out == 'ABD':
        assert n >= 1000, f'ABD output for N={n} <1000'

def test_same_range_same_output(run, x):
    n = int(x.strip())
    if 1 <= n <= 1997:
        out1 = run(x).strip()
