def test_output_is_heisei_or_tbd(run, x):
    out = run(x)
    assert out in ("Heisei\n", "TBD\n")

def test_april_30_heisei(run, x):
    if x == "2019/04/30\n":
        assert run(x) == "Heisei\n"

def test_may_1_tbd(run, x):
    if x == "2019/05/01\n":
        assert run(x) == "TBD\n"

def test_month_lt_4_heisei(run, x):
    y, m, d = map(int, x.strip().split('/'))
    if m <= 3:
        assert run(x) == "Heisei\n"

def test_month_gt_4_tbd(run, x):
    y, m, d = map(int, x.strip().split('/'))
    if m >= 5:
        assert run(x) == "TBD\n"

def test_april_heisei(run, x):
    y, m, d = map(int, x.strip().split('/'))
    if m == 4:
        assert run(x) == "Heisei\n"

def test_monotonic(run, x):
    # compare with a later date from the same input list? Not possible.
    # Instead, create a later date by adding one day if possible.
    # We must ensure the modified date is still valid in 2019.
    y, m, d = map(int, x.strip().split('/'))
    # Determine next day
    import datetime
    try:
        dt = datetime.date(y, m, d)
        dt_next = dt + datetime.timedelta(days=1)
        if dt_next.year == 2019:  # still valid
            next_str = f"{dt_next.year:04d}/{dt_next.month:02d}/{dt_next.day:02d}"
            out1 = run(x).strip()
            out2 = run(next_str + '\n').strip()
            # If out1 is TBD, out2 must be TBD
            if out1 == "TBD":
                assert out2 == "TBD"
    except ValueError:
        pass  # invalid date, should not happen

def test_day_independence_non_april(run, x):
    y, m, d = map(int, x.strip().split('/'))
    if m != 4:
        # create another valid day in same month (use first day)
        other = f"{y:04d}/{m:02d}/01"
        out1 = run(x).strip()
        out2 = run(other + '\n').strip()
        assert out1 == out2

def test_output_length(run, x):
    out = run(x)
    assert len(out) in (7, 4)  # Heisei\n (7) or TBD\n (4)

def test_no_trailing_whitespace(run, x):
    out = run(x)
    assert out.endswith('\n') and out.strip() == out.rstrip()

