def test_metamorphic_swap(run, x):
    lines = x.strip().split('\n')
    if len(lines) == 3 and lines[0] == '2':
        swapped = '\n'.join([lines[0], lines[2], lines[1]]) + '\n'
        out1 = run(x).strip()
