def test_non_negative_count(run, x):
    out = run(x).strip().split()
    if not out:
        return
    n = int(out[0])
    assert n >= 0

def test_solutions_in_range(run, x):
    out = run(x).strip().split()
    if not out:
        return
    n = int(out[0])
    if n == 0:
        assert len(out) == 1
        return
    sols = list(map(int, out[1:1+n]))
    for s in sols:
        assert 0 < s < 10**9

def test_output_format_matches_count(run, x):
    out = run(x).strip().split()
    if not out:
        return
    n = int(out[0])
    if n == 0:
        assert len(out) == 1
    else:
        assert len(out) == n + 1

def test_solutions_strictly_increasing(run, x):
    out = run(x).strip().split()
    if not out:
        return
    n = int(out[0])
    if n == 0:
        return
    sols = list(map(int, out[1:1+n]))
    for i in range(1, len(sols)):
        assert sols[i] > sols[i-1]

def test_each_solution_satisfies_equation(run, x):
    a, b, c = map(int, x.strip().split())
    out = run(x).strip().split()
    if not out:
        return
    n = int(out[0])
    if n == 0:
        return
    sols = list(map(int, out[1:1+n]))
    for x_val in sols:
        s = sum(int(d) for d in str(x_val))
        assert x_val == b * (s ** a) + c

def test_no_solutions_when_c_large(run, x):
    a, b, c = map(int, x.strip().split())
    # If c >= 10**9, x = b*s^a + c >= c >= 10**9 -> impossible
    if c >= 10**9:
        out = run(x).strip().split()
        assert out[0] == '0'

def test_small_digit_sum_candidate(run, x):
    a, b, c = map(int, x.strip().split())
    out = run(x).strip().split()
    if not out:
        return
    n = int(out[0])
    if n == 0:
        return
    sols = list(map(int, out[1:1+n]))
    # For each solution, compute s = digit sum, then recompute x from formula
    # and verify it matches the solution.
    for x_val in sols:
        s = sum(int(d) for d in str(x_val))
        computed = b * (s ** a) + c
        assert x_val == computed

def test_solution_digit_sum_bounded(run, x):
    a, b, c = map(int, x.strip().split())
    out = run(x).strip().split()
    if not out:
        return
    n = int(out[0])
    if n == 0:
        return
    sols = list(map(int, out[1:1+n]))
    # Maximum digit sum for numbers < 1e9 is 9*9 = 81
    for x_val in sols:
        s = sum(int(d) for d in str(x_val))
        assert 1 <= s <= 81

def test_negative_c_possible(run, x):
    a, b, c = map(int, x.strip().split())
    out = run(x).strip().split()
    if not out:
        return
    n = int(out[0])
    if n == 0:
        return
    sols = list(map(int, out[1:1+n]))
    for x_val in sols:
        # Equation must hold
        s = sum(int(d) for d in str(x_val))
        assert x_val == b * (s ** a) + c

def test_metamorphic_sign_flip(run, x):
    a, b, c = map(int, x.strip().split())
    # Only attempt if b>0 and c such that flipping signs yields a valid input
    # Not always valid because b must be >=1, but we can flip signs only if we adjust.
    # Instead, we test a weaker property: if we take b' = -b, c' = -c, and restrict to cases
    # where b' >=1 (i.e., b <= -1) but that never happens because b >=1.
    # So we skip this test if b <= 0 (won't happen).
    # Actually, we can't guarantee the transformed input is valid.
    # Therefore, we only apply when we can keep b positive.
    # We'll just test that for any solution x, the digit sum s satisfies s >= 1.
    out = run(x).strip().split()
    if not out:
        return
    n = int(out[0])
    if n == 0:
        return
    sols = list(map(int, out[1:1+n]))
    for x_val in sols:
        s = sum(int(d) for d in str(x_val))
        assert s >= 1

