def test_output_is_valid(run, x):
    out = run(x).strip().upper()
    assert out in ('YES', 'NO'), f'Invalid output: {out}'


def test_yes_implies_single_plus(run, x):
    out = run(x).strip().upper()
    if out != 'YES':
        return
    lines = x.strip().split('\n')
    h, w = map(int, lines[0].split())
    grid = [list(line) for line in lines[1:1+h]]
    # Find all '*' cells
    star_cells = [(i, j) for i in range(h) for j in range(w) if grid[i][j] == '*']
    if not star_cells:
        # No '*' cells => not a '+' shape
        assert False, 'YES but no '*' cells'
    # Find potential centers: cells where all four directions have at least one '*' consecutively
    centers = []
    for i, j in star_cells:
        up = 0
        for di in range(1, i+1):
            if grid[i-di][j] == '*':
                up += 1
            else:
                break
        down = 0
        for di in range(1, h-i):
            if grid[i+di][j] == '*':
                down += 1
            else:
                break
        left = 0
        for dj in range(1, j+1):
            if grid[i][j-dj] == '*':
                left += 1
            else:
                break
        right = 0
        for dj in range(1, w-j):
            if grid[i][j+dj] == '*':
                right += 1
            else:
                break
        if up >= 1 and down >= 1 and left >= 1 and right >= 1:
            centers.append((i, j, up, down, left, right))
    if not centers:
        assert False, 'YES but no valid center found'
    # There must be exactly one center
    if len(centers) != 1:
        assert False, 'YES but multiple centers'
    ci, cj, up, down, left, right = centers[0]
    # All '*' cells must lie on the cross arms
    expected_cells = set()
    for di in range(-up, down+1):
        expected_cells.add((ci+di, cj))
    for dj in range(-left, right+1):
        expected_cells.add((ci, cj+dj))
    actual_cells = set(star_cells)
    if expected_cells != actual_cells:
        assert False, 'YES but '*' cells do not match cross shape'


