def test_plus_shape_is_connected(run, x):
    out = run(x).strip().upper()
    lines = x.strip().split('\n')
    h, w = map(int, lines[0].split())
    grid = [list(line) for line in lines[1:1+h]]
    star_cells = [(i, j) for i in range(h) for j in range(w) if grid[i][j] == '*']
    if not star_cells:
        # No '*' cells => answer must be NO
        if out != 'NO':
            assert False, 'Empty grid should be NO'
        return
    # Check connectivity of '*' cells
    from collections import deque
    visited = set()
    start = star_cells[0]
    q = deque([start])
    visited.add(start)
    while q:
        i, j = q.popleft()
        for di, dj in [(1,0), (-1,0), (0,1), (0,-1)]:
            ni, nj = i+di, j+dj
            if 0 <= ni < h and 0 <= nj < w and grid[ni][nj] == '*' and (ni, nj) not in visited:
                visited.add((ni, nj))
                q.append((ni, nj))
    # If '*' cells are connected, then for a valid '+' they must all be in a cross
    if len(visited) == len(star_cells):
        # All '*' cells connected
        # If answer is YES, then shape must be a cross
        if out == 'YES':
            # Verify cross shape as in test_yes_implies_single_plus
            centers = []
            for i, j in star_cells:
                up = 0
                for di in range(1, i+1):
                    if grid[i-di][j] == '*':
                        up += 1
                    else:
                        break
                down = 0
                for di in range(1, h-i):
                    if grid[i+di][j] == '*':
                        down += 1
                    else:
                        break
                left = 0
                for dj in range(1, j+1):
                    if grid[i][j-dj] == '*':
                        left += 1
                    else:
                        break
                right = 0
                for dj in range(1, w-j):
                    if grid[i][j+dj] == '*':
                        right += 1
                    else:
                        break
                if up >= 1 and down >= 1 and left >= 1 and right >= 1:
                    centers.append((i, j, up, down, left, right))
            if not centers:
                assert False, 'YES but no valid center (connected)'
            if len(centers) != 1:
                assert False, 'YES but multiple centers (connected)'
            ci, cj, up, down, left, right = centers[0]
            expected_cells = set()
            for di in range(-up, down+1):
                expected_cells.add((ci+di, cj))
            for dj in range(-left, right+1):
                expected_cells.add((ci, cj+dj))
            if expected_cells != set(star_cells):
                assert False, 'YES but shape not a cross (connected)'
        # If answer is NO, then either no valid center or extra cells
        else:
            # Already checked in test_no_implies_no_single_plus, but we can double-check
            centers = []
            for i, j in star_cells:
                up = 0
                for di in range(1, i+1):
                    if grid[i-di][j] == '*':
                        up += 1
                    else:
                        break
                down = 0
                for di in range(1, h-i):
                    if grid[i+di][j] == '*':
                        down += 1
                    else:
                        break
                left = 0
                for dj in range(1, j+1):
                    if grid[i][j-dj] == '*':
                        left += 1
                    else:
                        break
                right = 0
                for dj in range(1, w-j):
                    if grid[i][j+dj] == '*':
                        right += 1
                    else:
                        break
                if up >= 1 and down >= 1 and left >= 1 and right >= 1:
                    centers.append((i, j, up, down, left, right))
            for ci, cj, up, down, left, right in centers:
                expected_cells = set()
                for di in range(-up, down+1):
                    expected_cells.add((ci+di, cj))
                for dj in range(-left, right+1):
                    expected_cells.add((ci, cj+dj))
                if expected_cells == set(star_cells):
                    assert False, 'NO but a valid '+' shape exists (connected)'
    else:
        # Disconnected '*' cells => must be NO
        if out != 'NO':
            assert False, 'Disconnected '*' cells should be NO'


