    arr = list(map(int, lines[2].split()))
    if len(set(arr)) == 1:
        ans = int(run(x).strip())
        assert ans == n

def test_reverse_invariant(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 3:
        return
    t = lines[0]
    n = lines[1]
    arr = lines[2].split()
    rev_input = f'{t}\n{n}\n{' '.join(arr[::-1])}\n'
    ans1 = int(run(x).strip())
    ans2 = int(run(rev_input).strip())
    assert ans1 == ans2

def test_n2_different_implies_one(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 3:
        return
    n = int(lines[1])
    if n != 2:
        return
    a = list(map(int, lines[2].split()))
    ans = int(run(x).strip())
    if a[0] != a[1]:
        assert ans == 1

def test_scaling_invariant(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 3:
        return
    t = lines[0]
    n = lines[1]
    arr = list(map(int, lines[2].split()))
    scaled = [str(x * 2) for x in arr]
    scaled_input = f'{t}\n{n}\n{' '.join(scaled)}\n'
    ans1 = int(run(x).strip())
    ans2 = int(run(scaled_input).strip())
    assert ans1 == ans2

def test_alternating_odd_length_must_be_one(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 3:
        return
    n = int(lines[1])
    if n % 2 == 0:
        return
    arr = list(map(int, lines[2].split()))
    if n < 3:
        return
    # Check alternating pattern: arr[i] == arr[i%2] for all i
    first = arr[0]
    second = arr[1]
    if first == second:
        return
    ok = True
    for i in range(n):
        if arr[i] != (first if i % 2 == 0 else second):
            ok = False
            break
    if ok:
        ans = int(run(x).strip())
        assert ans == 1

def test_answer_one_implies_not_all_equal(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 3:
        return
    arr = list(map(int, lines[2].split()))
    ans = int(run(x).strip())
    if ans == 1:
        assert len(set(arr)) > 1

def test_adjacent_unequal_implies_answer_lt_n(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 3:
        return
    n = int(lines[1])
    arr = list(map(int, lines[2].split()))
    ans = int(run(x).strip())
    # If there exists any adjacent unequal pair, at least one merge possible, so answer <= n-1
    has_unequal_adj = any(arr[i] != arr[i+1] for i in range(n-1))
    if has_unequal_adj:
        assert ans <= n-1

def test_n1_answer_one(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 3:
        return
    n = int(lines[1])
    if n == 1:
        ans = int(run(x).strip())
        assert ans == 1

def test_answer_two_odd_length_not_alternating(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 3:
        return
    n = int(lines[1])
    if n % 2 == 0:
        return
    arr = list(map(int, lines[2].split()))
    ans = int(run(x).strip())
    if ans == 2:
        # Check if array is alternating
        if n >= 3:
            first = arr[0]
            second = arr[1]
            if first != second:
                ok = True
                for i in range(n):
                    if arr[i] != (first if i % 2 == 0 else second):
                        ok = False
                        break
                assert not ok  # must not be alternating

def test_no_leading_zero(run, x):
    out = run(x).strip()
    assert out[0] != '0', f'Leading zero in output {out}'

def test_digits_in_range(run, x):
    out = run(x).strip()
    for ch in out:
        assert '0' <= ch <= '9', f'Invalid digit {ch}'

def test_not_greater_than_input(run, x):
    inp = x.strip()
    out = run(x).strip()
    # Since we can always keep original digits, the minimal number should be <= input
    # Compare as integers, but careful with leading zeros in input? input has no leading zero per spec.
    if len(out) == len(inp):
        assert int(out) <= int(inp), f'Output {out} greater than input {inp}'
    else:
        # lengths differ? should not happen (see length test), but if output shorter, it could be smaller
        pass

def test_certificate_inversion_possible(run, x):
    inp = x.strip()
    out = run(x).strip()
    # For each digit position in output (aligned from left), the digit must be either original digit or 9-original digit
    # Since lengths are same (checked elsewhere), iterate
    for i, (orig_char, out_char) in enumerate(zip(inp, out)):
        orig = int(orig_char)
        out_d = int(out_char)
        possible = {orig, 9 - orig}
        assert out_d in possible, f'Digit position {i}: {out_d} not in {possible}'

def test_bound_max_possible(run, x):
    inp = x.strip()
    out = run(x).strip()
    # Compute the number where each digit is max(orig, 9-orig) (since we could choose the larger if we wanted)
    max_digits = []
    for i, ch in enumerate(inp):
        d = int(ch)
        if i == 0 and d == 9:
            max_digits.append('9')  # first digit 9 cannot be inverted per spec? Actually spec doesn't forbid, but leading zero not allowed. 9->0 invalid, so max is 9.
        else:
            max_digits.append(str(max(d, 9-d)))
    max_num = int(''.join(max_digits))
    assert int(out) <= max_num, f'Output {out} exceeds max possible {max_num}'

def test_bound_min_possible_without_leading_zero(run, x):
    inp = x.strip()
    out = run(x).strip()
    # Compute lower bound: for each digit, choose min(d,9-d) except first digit at least 1
    lower_digits = []
    for i, ch in enumerate(inp):
        d = int(ch)
        cand = min(d, 9-d)
        if i == 0 and cand == 0:
            # must keep original or choose 9-d if that's non-zero
            if d == 0:
                cand = 0  # but input has no leading zero, so d>=1
            else:
                # choose the smaller non-zero candidate
                if d <= 9-d:
                    cand = d
                else:
                    cand = 9-d if 9-d !=0 else d
        lower_digits.append(str(cand))
    lower_num = int(''.join(lower_digits))
    assert int(out) >= lower_num, f'Output {out} less than lower bound {lower_num}'

def test_length_same(run, x):
    inp = x.strip()
    out = run(x).strip()
    assert len(out) == len(inp), f'Output length {len(out)} != input length {len(inp)}'

def test_metamorphic_all_nines(run, x):
    inp = x.strip()
    if all(ch == '9' for ch in inp):
        out = run(x).strip()
        assert out != '0', f'Output zero for all nines input'
        assert int(out) > 0, f'Output not positive'

def test_certificate_no_better_single_flip(run, x):
    inp = x.strip()
    out = run(x).strip()
    out_num = int(out)
    # For each digit position, consider flipping to the other candidate (original vs 9-orig)
    # If flipping yields a valid number (no leading zero) and is smaller, then output is not minimal.
    for i in range(len(inp)):
        d = int(inp[i])
        candidates = {d, 9-d}
        for cand in candidates:
            if i == 0 and cand == 0:
                continue
            # construct number with this digit changed to cand, others as in output
            # But output may have already chosen one candidate; we want to check the other.
            # Simpler: construct number by taking output digits and replace position i with cand.
            lst = list(out)
            lst[i] = str(cand)
            candidate_num = int(''.join(lst))
            if candidate_num < out_num:
                # However, candidate_num must be obtainable by some inversion pattern, not necessarily this one.
                # But if flipping a single digit yields a smaller valid number, then output is not minimal.
                # Because we could invert that digit differently and keep others same as output.
                # Since output's digits are either original or 9-orig, the other candidate is also reachable.
                # So this is a valid check.
                assert False, f'Better number {candidate_num} found by flipping digit {i}'

def test_brute_force_small(run, x):
    inp = x.strip()
    if int(inp) <= 10000:  # small enough to brute force subsets of digits (2^len <= 2^5=32 for len<=5)
        n = len(inp)
        best = None
        # iterate over all subsets of digits to invert
        for mask in range(1 << n):
            digits = []
            valid = True
            for i in range(n):
                d = int(inp[i])
                if mask & (1 << i):
                    d = 9 - d
                if i == 0 and d == 0:
                    valid = False
                    break
                digits.append(str(d))
            if not valid:
                continue
            num = int(''.join(digits))
            if best is None or num < best:
                best = num
        out = run(x).strip()
        assert int(out) == best, f'Output {out} != brute force optimal {best}'

