def test_output_valid(run, x):
    output = run(x).strip()
    assert output in ("Misha", "Vasya", "Tie")

def test_symmetry(run, x):
    a, b, c, d = map(int, x.strip().split())
    swapped = f"{b} {a} {d} {c}"
    out_original = run(x).strip()
    out_swapped = run(swapped).strip()
    if out_original == "Misha":
        assert out_swapped == "Vasya"
    elif out_original == "Vasya":
        assert out_swapped == "Misha"
    else:
        assert out_swapped == "Tie"

def test_tie_implies_equal_scores(run, x):
    output = run(x).strip()
    if output == "Tie":
        # Compute scores using the formula, ignoring backdoor
        a, b, c, d = map(int, x.strip().split())
        misha = max(3 * a / 10, a - a / 250 * c)
        vasya = max(3 * b / 10, b - b / 250 * d)
        # In a true tie, these must be equal
        assert abs(misha - vasya) < 1e-9

def test_monotonicity_a(run, x):
    a, b, c, d = map(int, x.strip().split())
    if a < 3500:
        increased = f"{a+250} {b} {c} {d}"
        out_original = run(x).strip()
        out_increased = run(increased).strip()
        # If original is Misha, increased cannot become Vasya (Misha's score can only increase or stay same)
        if out_original == "Misha":
            assert out_increased != "Vasya"
        # If original is Tie, increased cannot become Vasya (could become Misha or stay Tie)
        elif out_original == "Tie":
            assert out_increased != "Vasya"

def test_monotonicity_c(run, x):
    a, b, c, d = map(int, x.strip().split())
    if c > 0:
        decreased = f"{a} {b} {c-1} {d}"
        out_original = run(x).strip()
        out_decreased = run(decreased).strip()
        # If original is Vasya, decreasing c (making Misha better) cannot make it Misha
        if out_original == "Vasya":
            assert out_decreased != "Misha"
        # If original is Tie, decreasing c cannot make it Vasya
        elif out_original == "Tie":
