def test_swapping_CMY_does_not_change_class(run, x):
    # Build a version where all C/M/Y are replaced by one of them (say 'C')
    # This must not change color vs black&white classification
    lines = x.strip().split('\n')
    n_m = lines[0].split()
    if len(n_m) < 2:
        return
    n, m = map(int, n_m)
    new_lines = [lines[0]]
    for i in range(1, min(n+1, len(lines))):
        row = lines[i].split()
        new_row = []
