                new_row.append('C')
            else:
                new_row.append(pixel)
        new_lines.append(' '.join(new_row))
    new_input = '\n'.join(new_lines)
    out1 = run(x).strip()
    out2 = run(new_input).strip()
    # Both must be same classification
    assert (out1 == "#Color") == (out2 == "#Color")

