        new_header = f"{new_n} {m}"
        new_lines = [new_header] + lines[2:]
        new_input = '\n'.join(new_lines)
        out1 = run(x).strip()
        out2 = run(new_input).strip()
        assert (out1 == "#Color") == (out2 == "#Color")

def test_certificate_verify_pixels(run, x):
    out = run(x).strip()
    lines = x.strip().split('\n')
    n_m = lines[0].split()
    if len(n_m) < 2:
        return
    n, m = map(int, n_m)
    colored_present = False
    for i in range(1, min(n+1, len(lines))):
