def test_invariant_output_format(run, x):
    out = run(x).strip()
    assert out in ('YES', 'NO'), f'Output must be YES or NO, got {repr(out)}'

def test_metamorphic_append_heidi(run, x):
    out1 = run(x).strip()
    out2 = run(x + 'heidi').strip()
    if out1 == 'YES':
        assert out2 == 'YES', f'Appending heidi to a YES input must still yield YES'

def test_metamorphic_remove_all_letters(run, x):
    out = run(x).strip()
    # remove all letters except h, e, i, d
    filtered = ''.join(ch for ch in x.strip() if ch in 'heid')
    out_filtered = run(filtered + '\n').strip()
    if out == 'YES':
        assert out_filtered == 'YES', f'Removing irrelevant letters must preserve YES'

def test_certificate_YES_contains_h(run, x):
    out = run(x).strip()
    if out == 'YES':
        assert 'h' in x, f'If output is YES, string must contain h'

def test_certificate_YES_contains_i_after_h(run, x):
    out = run(x).strip()
    if out == 'YES':
        s = x.strip()
        h_pos = s.find('h')
        assert h_pos != -1
        # there must be an 'i' after this h (since heidi has i after h)
        assert 'i' in s[h_pos:], f'If output is YES, there must be an i after some h'

def test_certificate_NO_if_too_short(run, x):
    s = x.strip()
    if len(s) < 5:
        out = run(x).strip()
        assert out == 'NO', f'String length <5 cannot contain heidi as subsequence'

def test_metamorphic_prepend_heidi(run, x):
    out1 = run(x).strip()
    out2 = run('heidi' + x).strip()
    # prepending heidi forces YES
    assert out2 == 'YES', f'Prepending heidi must yield YES'

def test_certificate_NO_if_missing_letter(run, x):
    s = x.strip()
    # if any of h, e, i, d is missing, answer must be NO
    for ch in 'heidi':
        if ch not in s:
            out = run(x).strip()
            assert out == 'NO', f'Missing required letter {ch} must yield NO'

def test_metamorphic_duplicate_string(run, x):
    out1 = run(x).strip()
    out2 = run(x.strip() * 2 + '\n').strip()
    assert out1 == out2, f'Duplicating string must not change answer'

def test_certificate_YES_order_of_letters(run, x):
    out = run(x).strip()
    if out == 'YES':
        s = x.strip()
        # find indices for h, e, i, d, i in order (not necessarily distinct)
        import re
        # match pattern .*h.*e.*i.*d.*i
        if not re.search(r'.*h.*e.*i.*d.*i', s):
            assert False, f'If output is YES, string must contain h before e before i before d before i as subsequence'

