                assert False, f'Yes output but sequence loops without hitting 0 modulo m'
            seen.add(a)
        else:
            # after m steps, not reached 0
            assert False, f'Yes output but not reached 0 modulo m within m steps'

def test_no_certificate(run, x):
    out = run(x)
    if out == "No\n":
        a, m = map(int, x.strip().split())
        for _ in range(m):
            if a % m == 0:
                assert False, f'No output but reached 0 modulo m'
            a += a % m

