    assert out in ('YES', 'NO'), f'Output must be YES or NO, got {repr(out)}'"
    },
    {
      "name": "test_if_x_equals_t_then_yes",
      "source": "def test_if_x_equals_t_then_yes(run, x):
    t, s, x = map(int, x.strip().split())
    if x == t:
        assert run(x).strip() == 'YES', f'When x == t ({x} == {t}), answer must be YES'"
    },
    {
      "name": "test_if_x_minus_t_nonneg_divisible_by_s_then_yes",
      "source": "def test_if_x_minus_t_nonneg_divisible_by_s_then_yes(run, x):
    t, s, x = map(int, x.strip().split())
    if x >= t and (x - t) % s == 0:
        assert run(x).strip() == 'YES', f'When x >= t and (x-t)%s == 0 (x={x}, t={t}, s={s}), answer must be YES'"
    },
    {
      "name": "test_if_x_minus_t_minus1_nonneg_divisible_by_s_and_gt_t_then_yes",
      "source": "def test_if_x_minus_t_minus1_nonneg_divisible_by_s_and_gt_t_then_yes(run, x):
    t, s, x = map(int, x.strip().split())
    if x > t and (x - t - 1) % s == 0:
        assert run(x).strip() == 'YES', f'When x > t and (x-t-1)%s == 0 (x={x}, t={t}, s={s}), answer must be YES'"
    },
    {
      "name": "test_certificate_if_yes_then_condition",
      "source": "def test_certificate_if_yes_then_condition(run, x):
    t, s, x_val = map(int, x.strip().split())
    out = run(x).strip()
    if out == 'YES':
        # Must satisfy one of: x == t, or (x-t)%s==0 with x>=t, or (x-t-1)%s==0 with x>t
        cond = (x_val == t) or (x_val >= t and (x_val - t) % s == 0) or (x_val > t and (x_val - t - 1) % s == 0)
        assert cond, f'Answer YES but condition fails: t={t}, s={s}, x={x_val}'"
    },
    {
      "name": "test_metamorphic_shift",
      "source": "def test_metamorphic_shift(run, x):
    t, s, x_val = map(int, x.strip().split())
    # Shift all three by a constant k (choose k = s) within bounds
    k = s  # s >= 2, shifting by s keeps nonnegative and s unchanged
    t2 = t + k
    x2 = x_val + k
    # Ensure they are within allowed range (0..1e9) but spec allows up to 1e9, may exceed? We'll choose k=min(s, 10) to avoid overflow.
    # Actually we can just choose k = 1 to stay safe.
    k = 1
    t2 = t + k
    x2 = x_val + k
    if t2 <= 10**9 and x2 <= 10**9:
        inp2 = f'{t2} {s} {x2}\n'
        out1 = run(x).strip()
        out2 = run(inp2).strip()
        assert out1 == out2, f'Shifting t and x by {k} should not change answer: original {out1}, shifted {out2}'"
    },
    {
      "name": "test_metamorphic_scaling",
      "source": "def test_metamorphic_scaling(run, x):
    t, s, x_val = map(int, x.strip().split())
    # Scale all by factor 2, but ensure s >= 2 after scaling? Original s >= 2, scaling by 2 keeps s>=4.
    # Ensure scaled values <= 1e9, else skip.
    if t * 2 <= 10**9 and s * 2 <= 10**9 and x_val * 2 <= 10**9:
        inp2 = f'{t*2} {s*2} {x_val*2}\n'
        out1 = run(x).strip()
        out2 = run(inp2).strip()
        assert out1 == out2, f'Scaling by 2 should not change answer: original {out1}, scaled {out2}'"
    },
    {
      "name": "test_necessary_divisibility_for_yes",
      "source": "def test_necessary_divisibility_for_yes(run, x):
    t, s, x_val = map(int, x.strip().split())
    out = run(x).strip()
    if out == 'YES':
        # Then either (x_val - t) % s == 0 or (x_val - t - 1) % s == 0, but must also satisfy x>=t or x>t accordingly.
        # Actually the condition is: x_val == t OR (x_val >= t and (x_val - t) % s == 0) OR (x_val > t and (x_val - t - 1) % s == 0)
        # So we check the disjunction.
        cond = (x_val == t) or (x_val >= t and (x_val - t) % s == 0) or (x_val > t and (x_val - t - 1) % s == 0)
        assert cond, f'YES answer but no barking pattern matches: t={t}, s={s}, x={x_val}'"
    },
    {
      "name": "test_no_for_small_x_before_t",
      "source": "def test_no_for_small_x_before_t(run, x):
    t, s, x_val = map(int, x.strip().split())
    if x_val < t:
        assert run(x).strip() == 'NO', f'When x < t ({x_val} < {t}), answer must be NO'"
    },
    {
      "name": "test_answer_is_yes_or_no_only",
      "source": "def test_answer_is_yes_or_no_only(run, x):
    out = run(x).strip()
    assert out == 'YES' or out == 'NO', f'Output must be exactly YES or NO, got {repr(out)}'"
    }
  ]
}

{
  "rationale": "Each test verifies a property mandated by the specification: counts are non-negative integers modulo 1e9+7; empty cells can be filled with bombs or numbers consistent with adjacency rules; swapping adjacent known cells leaves the count unchanged (metamorphic); answer must be a single integer; the count cannot exceed 2^(number of '?') (bound). The metamorphic relation uses reversal symmetry because the problem is symmetric under mirroring the string (the sum over configurations is invariant). Certificate tests verify that a specific choice (replace all '?' with '0') either yields a valid configuration or contributes 0. The bound on answer based on '?' count is safe because each '?' has at most 2 possibilities (digit or bomb) but not all combinations are valid. The weakest test is the bound, as it’s loose and may miss many errors; it would be dropped first.",
  "tests": [
    {
      "name": "test_answer_is_non_negative",
      "source": "def test_answer_is_non_negative(run, x):
    ans = run(x).strip()
    assert ans.isdigit() or (ans[0] == '-' and ans[1:].isdigit())
    val = int(ans)
    assert 0 <= val < 1000000007"
    },
    {
      "name": "test_answer_mod_range",
      "source": "def test_answer_mod_range(run, x):
    ans = run(x).strip()
    assert ans.isdigit()
    val = int(ans)
    assert 0 <= val < 1000000007"
    },
    {
      "name": "test_metamorphic_reverse",
      "source": "def test_metamorphic_reverse(run, x):
    s = x.strip('"\n')
    rev = s[::-1]
    ans1 = run(s).strip()
    ans2 = run(rev).strip()
    assert ans1 == ans2"
    },
    {
      "name": "test_empty_cell_substitution_zero",
      "source": "def test_empty_cell_substitution_zero(run, x):
    # If we replace all '?' with '0', the resulting string must either be valid (count 1) or invalid (count 0).
    # This is a certificate: the answer mod 2 must match validity of that substitution.
    s = x.strip('"\n')
    t = s.replace('?', '0')
    # Check validity: each non-bomb cell must have correct adjacency count.
    n = len(t)
    valid = True
    for i in range(n):
        if t[i] == '*':
            continue
        cnt = 0
        if i > 0 and t[i-1] == '*':
            cnt += 1
        if i < n-1 and t[i+1] == '*':
            cnt += 1
        if int(t[i]) != cnt:
            valid = False
            break
    ans = int(run(x).strip())
    if valid:
        assert ans % 2 == 1
    # If invalid, no constraint (could be 0 or even >0 because other substitutions may be valid)."
    },
    {
      "name": "test_all_bombs_count",
      "source": "def test_all_bombs_count(run, x):
    # If the string contains no digits (only '*', '?'), then all '?' forced to '*' yields a valid config?
    # Not necessarily: digits must match adjacency. Instead, a simpler bound: answer <= 2^(number of '?').
    s = x.strip('"\n')
    qcnt = s.count('?')
    ans = int(run(x).strip())
    # Each '?' can be either bomb or number 0/1/2, but numbers have restrictions.
    # So 2^qcnt is a safe upper bound.
    assert ans <= pow(2, qcnt, 1000000007)"
    },
    {
      "name": "test_adjacent_known_invalid",
      "source": "def test_adjacent_known_invalid(run, x):
    # If two adjacent cells are known digits and they violate adjacency rules, answer must be 0.
    s = x.strip('"\n')
    n = len(s)
    impossible = False
    for i in range(n-1):
        a, b = s[i], s[i+1]
        if a.isdigit() and b.isdigit():
            # They cannot both be '2' because each would require two bombs adjacent.
            if a == '2' and b == '2':
                impossible = True
            # If one is '0' and the other is '2', impossible.
            if a == '0' and b == '2':
                impossible = True
            if a == '2' and b == '0':
                impossible = True
    if impossible:
        assert int(run(x).strip()) == 0"
    },
    {
      "name": "test_single_cell",
      "source": "def test_single_cell(run, x):
    s = x.strip('"\n')
    if len(s) == 1:
        ans = int(run(x).strip())
        if s == '?':
            assert ans == 2
        elif s == '0':
            assert ans == 1
        elif s == '1' or s == '2' or s == '*':
            assert ans == 0
        # else no constraint"
    },
    {
      "name": "test_answer_is_integer",
      "source": "def test_answer_is_integer(run, x):
    ans = run(x).strip()
    assert ans.isdigit()"
    },
    {
      "name": "test_metamorphic_swap_ends",
      "source": "def test_metamorphic_swap_ends(run, x):
    s = x.strip('"\n')
    if len(s) >= 2:
        # Swap first and last character, problem symmetric.
        t = s[-1] + s[1:-1] + s[0]
        ans1 = int(run(s).strip())
        ans2 = int(run(t).strip())
        assert ans1 == ans2"
    },
    {
      "name": "test_bound_by_3powq",
      "source": "def test_bound_by_3powq(run, x):
    # Each '?' could be '*', '0', '1', '2' in principle, so 4^q is a loose bound.
    # But digits have restrictions, so 3^q is still safe.
    s = x.strip('"\n')
    q = s.count('?')
    ans = int(run(x).strip())
    assert ans <= pow(3, q, 1000000007)"
    }
  ]
}

{
  "rationale": "Each test checks a property that must hold for any correct solution. The main ideas: (1) the output must be a positive integer (invariant). (2) It must be a lunlun number (certificate). (3) The K-th lunlun number is monotonic in K (metamorphic). (4) The first 9 numbers are 1..9 (invariant). (5) The answer for K=1 is 1 (specific bound). (6) For large K, the answer must be at least K (bound). (7) For K up to 100000, the answer should not exceed a safe upper bound derived from BFS (bound). (8) The answer should be consistent when K is doubled (metamorphic). (9) The lunlun property for adjacent digits (certificate). (10) The answer for K and K+1 should be increasing (metamorphic). The monotonicity test (test_monotonic) is the strongest but also the most likely to fail on a correct solution if not careful—so I'd drop it first if needed, but it's valid because the K-th smallest lunlun number is strictly increasing with K.",
  "tests": [
    {
      "name": "test_is_positive_integer",
      "source": "def test_is_positive_integer(run, x):
    out = run(x).strip()
    assert out.isdigit() and int(out) > 0"
    },
    {
      "name": "test_is_lunlun_number",
      "source": "def test_is_lunlun_number(run, x):
    out = run(x).strip()
    n = int(out)
