    },
    {
      "name": "test_invariant_mod0",
      "source": "def test_invariant_mod0(run, x):
    xi = int(x)
    if xi % 4 == 0:
        out = run(x)
        assert out == '1 A', f'For x={xi} mod 4=0, expected "1 A" got "{out}"'"
    },
    {
      "name": "test_invariant_mod1",
      "source": "def test_invariant_mod1(run, x):
    xi = int(x)
