        for j in range(m):
            if grid[i][j].isdigit() or grid[i][j] == '#':
                reachable[i][j] = True
                if grid[i][j].isdigit():
                    q.append((i,j))
    while q:
        i,j = q.popleft()
        for di,dj in [(-1,0),(1,0),(0,-1),(0,1)]:
            ni, nj = i+di, j+dj
            if 0 <= ni < n and 0 <= nj < m and not reachable[ni][nj] and grid[ni][nj] == '.':
                reachable[ni][nj] = True
                q.append((ni,nj))
    # After the game, those unreachable '.' must remain '.'
    # We can't see the final grid, but we can check that the total claimed cells does not exceed reachable empties + initial castles.
    out = run(x).strip().split()
    final_counts = list(map(int, out))
    total_claimed = sum(final_counts)
    initial_castles = sum(1 for row in grid for ch in row if ch.isdigit())
    reachable_empty = sum(1 for i in range(n) for j in range(m) if grid[i][j]=='.' and reachable[i][j])
    max_possible = initial_castles + reachable_empty
    assert total_claimed <= max_possible, f'Claimed {total_claimed} cells, but at most {max_possible} are reachable'

def test_partition_of_grid(run, x):
    lines = x.strip().split('\n')
    n, m, p = map(int, lines[0].split())
    grid = lines[2:]
    blocked = sum(row.count('#') for row in grid)
    out = run(x).strip().split()
    counts = list(map(int, out))
    total_player_cells = sum(counts)
    assert total_player_cells + blocked == n * m, f'Players occupy {total_player_cells}, blocked {blocked}, total cells {n*m} mismatch'

