def test_output_preserves_non_dots(run, x):
    # The output must keep all 'x' and 'o' unchanged.
    out = run(x)
    lines = out.split('\n')
    # Reconstruct board as in input parsing
    a_out = [[None]*9 for _ in range(9)]
