        for i in range(3):
            parts = lines[k*4 + i].split()
            for j in range(3):
                for l in range(3):
                    a_out[k*3 + i][j*3 + l] = parts[j][l]
    # Parse input board
    inp_lines = x.strip('\n').split('\n')
    a_in = [[None]*9 for _ in range(9)]
    for k in range(3):
        for i in range(3):
            parts = inp_lines[k*4 + i].split()
            for j in range(3):
                for l in range(3):
                    a_in[k*3 + i][j*3 + l] = parts[j][l]
    for i in range(9):
        for j in range(9):
            if a_in[i][j] in ('x','o'):
                assert a_out[i][j] == a_in[i][j], f'Occupied cell changed at ({i},{j})'
            if a_in[i][j] == '.':
                assert a_out[i][j] in ('.','!'), f'Empty cell became {a_out[i][j]}'


