def test_rotate_last_move_in_small_field(run, x):
    # If we rotate the last move coordinates within its small field (keeping board same),
    # the pattern of '!' in the target small field should rotate accordingly.
    # Because the rule only picks the small field based on (x%3, y%3).
    # We'll rotate 90 degrees clockwise: new_x = start_row + (old_y - start_col), new_y = start_col + 2 - (old_x - start_row).
    # But we must also rotate the board? Not needed: we keep board identical, only change last move coordinates.
    # However, the board's small field contents are unchanged, so the allowed moves in the target small field are the same set of empty cells.
    # Actually the set of empty cells in the target small field is unchanged, so the '!' positions should be identical, not rotated.
    # So this test is trivial. Instead, let's do a metamorphic relation: shift last move to another cell in same small field but same board.
    # If the target small field is the same (because (bx,by) unchanged), the output should be identical.
    # Let's pick a different cell in the same small field (same bx,by).
    # We'll modify coordinates to another cell within the same small field that is also occupied (to keep validity).
    # But we don't know which cells are occupied. Instead, we can simply add 1 to x (within same small field) and see if output changes.
    # However, adding 1 may go to next small field, changing bx. So we need to ensure we stay within same small field.
    # We'll try (x+1, y) if still within same small field, else (x-1, y).
    inp_lines = x.strip('\n').split('\n')
    # Parse last coordinates.
    last = inp_lines[-1]
    xc, yc = map(int, last.split())
    bx = (xc-1) % 3
    by = (yc-1) % 3
    # Try xc+1 if still same bx.
    if (xc) % 3 != 0:  # xc is 1‑based, so same small field if (xc-1)%3 stays same.
        new_x = xc + 1
        new_y = yc
    else:
        new_x = xc - 1
        new_y = yc
    # Ensure new coordinates are within 1..9.
    if not (1 <= new_x <= 9 and 1 <= new_y <= 9):
        return  # skip test if out of bounds (should not happen).
    # Build new input.
    new_inp_lines = inp_lines[:-1] + [f'{new_x} {new_y}']
    new_input = '\n'.join(new_inp_lines)
    out1 = run(x)
    out2 = run(new_input)
    # The outputs should be identical because the target small field is unchanged.
    # (Because (new_x-1)%3 == bx and (new_y-1)%3 == by).
    # Parse both to compare.
    def grid_from_out(s):
        g = [[None]*9 for _ in range(9)]
        ls = s.split('\n')
        for k in range(3):
            for i in range(3):
                parts = ls[k*4 + i].split()
                for j in range(3):
                    for l in range(3):
                        g[k*3 + i][j*3 + l] = parts[j][l]
        return g
    g1 = grid_from_out(out1)
    g2 = grid_from_out(out2)
    for i in range(9):
        for j in range(9):
            if g1[i][j] != g2[i][j]:
                raise AssertionError(f'Output changed when moving within same small field')


