tests_src:
def test_output_is_valid_symbol(run, x):
    out = run(x).strip()
    assert out in ('<', '>', '='), f'Output must be one of <, >, =, got {out!r}'

def test_output_length_one(run, x):
    out = run(x).strip()
    assert len(out) == 1, f'Output must be a single character, got {out!r}'

def test_swap_input_inverts_result(run, x):
    lines = x.split('\n')
    a, b = lines[0], lines[1]
    swapped = b + '\n' + a + '\n'
    out1 = run(x).strip()
    out2 = run(swapped).strip()
    if out1 == '<':
        assert out2 == '>', f'Swapping inputs should invert < to >, got {out2}'
    elif out1 == '>':
        assert out2 == '<', f'Swapping inputs should invert > to <, got {out2}'
    else:
        assert out2 == '=', f'Swapping equal inputs should keep =, got {out2}'

def test_equal_after_strip_zeros(run, x):
    out = run(x).strip()
    a, b = x.split('\n')[0], x.split('\n')[1]
    a_stripped = a.lstrip('0') or '0'
    b_stripped = b.lstrip('0') or '0'
    if a_stripped == b_stripped:
        assert out == '=', f'Numbers are equal after stripping leading zeros, expected =, got {out}'

def test_padding_both_with_zeros_preserves_result(run, x):
    a, b = x.split('\n')[0], x.split('\n')[1]
    padded = '0' + a + '\n' + '0' + b + '\n'
    out1 = run(x).strip()
    out2 = run(padded).strip()
    assert out1 == out2, f'Adding a leading zero to both should not change comparison, got {out1} vs {out2}'

def test_compare_lexicographically_after_equal_length(run, x):
    out = run(x).strip()
    a, b = x.split('\n')[0], x.split('\n')[1]
    n, m = len(a), len(b)
    if n > m:
        b_pad = '0' * (n - m) + b
        a_pad = a
    else:
        a_pad = '0' * (m - n) + a
        b_pad = b
    # Now compare strings
    if a_pad == b_pad:
        assert out == '=', f'Padded strings equal, expected =, got {out}'
    elif a_pad < b_pad:
        assert out == '<', f'Padded string a < b, expected <, got {out}'
    else:
        assert out == '>', f'Padded string a > b, expected >, got {out}'

def test_small_inputs_direct_int_check(run, x):
    # Only apply if both numbers have at most 100 digits (safe for int conversion)
    a, b = x.split('\n')[0], x.split('\n')[1]
    if len(a) <= 100 and len(b) <= 100:
        int_a = int(a)
        int_b = int(b)
        out = run(x).strip()
        if int_a < int_b:
            expected = '<'
        elif int_a > int_b:
            expected = '>'
        else:
            expected = '='
        assert out == expected, f'For small inputs, direct int comparison expects {expected}, got {out}'

def test_consistency_with_repeated_digits(run, x):
    a, b = x.split('\n')[0], x.split('\n')[1]
    # Create new numbers by appending the same digit to both
    new_a = a + '0'
    new_b = b + '0'
    new_input = new_a + '\n' + new_b + '\n'
    out1 = run(x).strip()
    out2 = run(new_input).strip()
    assert out1 == out2, f'Appending same digit to both should not change comparison, got {out1} vs {out2}'

def test_empty_strings_impossible_but_check_format(run, x):
    # Ensure input lines are non-empty (spec says non-negative integer, could be '0')
    lines = x.strip().split('\n')
    assert len(lines) >= 2, 'Input must have two lines'
    a, b = lines[0], lines[1]
    assert a != '' and b != '', 'Numbers cannot be empty strings'

def test_output_consistent_with_trimmed_leading_zeros(run, x):
    a, b = x.split('\n')[0], x.split('\n')[1]
    a_trim = a.lstrip('0') or '0'
    b_trim = b.lstrip('0') or '0'
    # If trimmed lengths differ, the longer one is larger unless they are equal strings
    if len(a_trim) != len(b_trim):
        out = run(x).strip()
        if len(a_trim) < len(b_trim):
            expected = '<'
        else:
            expected = '>'
        assert out == expected, f'Trimmed lengths differ: {len(a_trim)} vs {len(b_trim)}, expected {expected}, got {out}'
    # else lengths equal, lexicographic comparison after trimming is valid
