def test_output_format(run, x):
    out = run(x).strip()
    # Must be exactly one of the three allowed outputs
    if out == 'Poor Dima!':
        return
    if out == 'Poor Inna!':
        return
    # otherwise must be a non‑negative integer without extra spaces
    # (and not leading zeros unless it's '0')
    assert out.isdigit() or (out[0] == '-' and out[1:].isdigit()), f'Invalid output: {out}'
    val = int(out)
    assert val >= 0, f'Negative integer output: {val}'

def test_poor_dima_implies_no_start(run, x):
    out = run(x).strip()
    if out == 'Poor Dima!':
        # there is no D from which a full DIMA cycle can be started
        # i.e., no D with a reachable I, M, A, D cycle of length 4
        lines = x.strip().split('\n')
        n, m = map(int, lines[0].split())
        grid = lines[1:]
        # Build graph of allowed moves
        from collections import deque
        dirs = [(1,0),(-1,0),(0,1),(0,-1)]
        # For each D, BFS for a path D->I->M->A->D (one full cycle)
        for i in range(n):
            for j in range(m):
                if grid[i][j] == 'D':
                    # BFS states: (x,y,step) step 0:D,1:I,2:M,3:A,4:D(completed)
                    q = deque()
                    q.append((i,j,0))
                    visited = set()
                    visited.add((i,j,0))
                    while q:
                        cx,cy,step = q.popleft()
                        if step == 4:
                            # found a complete cycle starting at (i,j)
                            # contradicts Poor Dima!
                            # So the output is wrong.
                            assert False, f'Found a DIMA cycle starting at ({i},{j}) but output is Poor Dima!'
                        nxt_char = {'D':'I','I':'M','M':'A','A':'D'}[grid[cx][cy]]
                        for dx,dy in dirs:
                            nx,ny = cx+dx, cy+dy
                            if 0<=nx<n and 0<=ny<m and grid[nx][ny]==nxt_char:
                                nstep = step+1
                                if (nx,ny,nstep) not in visited:
                                    visited.add((nx,ny,nstep))
                                    q.append((nx,ny,nstep))
        # If we get here, no D can start a cycle, which is consistent with Poor Dima!
        # (this test only fires if we find a cycle when output says none)
        return
    # otherwise, nothing to check
    pass

def test_poor_inna_implies_cycle(run, x):
    out = run(x).strip()
    if out == 'Poor Inna!':
        # there must be a reachable cycle in the DIMA‑graph
        lines = x.strip().split('\n')
        n, m = map(int, lines[0].split())
        grid = lines[1:]
        # Build directed graph (u->v) where u and v are cells and letter transitions are correct
        from collections import defaultdict, deque
        g = defaultdict(list)
        nodes = [(i,j) for i in range(n) for j in range(m)]
        dirs = [(1,0),(-1,0),(0,1),(0,-1)]
        for (i,j) in nodes:
            cur = grid[i][j]
            nxt = {'D':'I','I':'M','M':'A','A':'D'}[cur]
            for dx,dy in dirs:
                ni,nj = i+dx, j+dy
                if 0<=ni<n and 0<=nj<m and grid[ni][nj]==nxt:
                    g[(i,j)].append((ni,nj))
        # Check for a cycle reachable from some D
        # We'll do DFS with recursion stack on each D start
        import sys
        sys.setrecursionlimit(10000)
        visited = {}
        recstack = {}
        def dfs(v):
            recstack[v] = True
            visited[v] = True
            for nb in g[v]:
                if nb not in visited:
                    if dfs(nb):
                        return True
                elif recstack.get(nb, False):
                    return True
            recstack[v] = False
            return False
        for i in range(n):
            for j in range(m):
                if grid[i][j] == 'D' and (i,j) not in visited:
                    if dfs((i,j)):
                        # found a cycle, good
                        return
        # If we get here, no cycle reachable from any D -> output should not be Poor Inna!
        assert False, 'No cycle found but output says Poor Inna!'
    pass

def test_numeric_answer_bounded_by_M_count(run, x):
    out = run(x).strip()
    if out == 'Poor Dima!' or out == 'Poor Inna!':
        return
    k = int(out)
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    grid = lines[1:]
    total_M = sum(row.count('M') for row in grid)
    # Each traversal of DIMA counts one 'M' visited, so max possible is total_M
    assert k <= total_M, f'Answer {k} exceeds total number of M cells ({total_M})'

def test_numeric_answer_non_negative(run, x):
    out = run(x).strip()
    if out == 'Poor Dima!' or out == 'Poor Inna!':
        return
    k = int(out)
    assert k >= 0, f'Negative answer {k}'

def test_cyclic_shift_invariant(run, x):
    # Rotating letters D->I, I->M, M->A, A->D everywhere should give same numeric answer
    # because the sequence is cyclic.
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    grid = lines[1:]
    shift_map = {'D':'I','I':'M','M':'A','A':'D'}
    shifted = []
    for row in grid:
        shifted.append(''.join(shift_map[ch] for ch in row))
    new_input = f'{n} {m}\n' + '\n'.join(shifted)
    out1 = run(x).strip()
    out2 = run(new_input).strip()
    # Both must be of same kind
    if out1 == 'Poor Dima!':
        assert out2 == 'Poor Dima!', f'Original Poor Dima! but shifted {out2}'
    elif out1 == 'Poor Inna!':
        assert out2 == 'Poor Inna!', f'Original Poor Inna! but shifted {out2}'
    else:
        # both must be integers and equal
        assert out2.isdigit() or (out2[0]=='-' and out2[1:].isdigit()), f'Shifted output not integer: {out2}'
        assert int(out1) == int(out2), f'Original {out1} != shifted {out2}'

def test_certificate_path_exists(run, x):
    out = run(x).strip()
    if out == 'Poor Dima!' or out == 'Poor Inna!':
        return
    k = int(out)
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    grid = lines[1:]
    # We need to verify there exists a walk that visits exactly k 'M's following D->I->M->A->D cycle
    # Equivalent to a walk of length 4k (each DIMA is 4 moves) starting at some D.
    # Since k may be large, we cannot enumerate all walks.
    # Instead, we can check that the maximum number of DIMA cycles computed via DP on the DIMA‑graph
    # is at least k. We'll implement a simple DP that ignores cycles (assumes DAG) for verification.
    # But if there is a cycle, the answer should be 'Poor Inna!' and we wouldn't be here.
    # So we can assume the reachable subgraph from any D is a DAG for the purpose of this check.
    # Build graph with transitions as before.
    from collections import deque, defaultdict
    dirs = [(1,0),(-1,0),(0,1),(0,-1)]
    g = defaultdict(list)
    indeg = defaultdict(int)
    cells = [(i,j) for i in range(n) for j in range(m)]
    for (i,j) in cells:
        cur = grid[i][j]
        nxt = {'D':'I','I':'M','M':'A','A':'D'}[cur]
        for dx,dy in dirs:
            ni,nj = i+dx, j+dy
            if 0<=ni<n and 0<=nj<m and grid[ni][nj]==nxt:
                g[(i,j)].append((ni,nj))
                indeg[(ni,nj)] += 1
    # DP on DAG: dp[cell] = max number of M's visited on paths starting at cell
    # But we need number of full DIMA cycles, which is number of M's visited.
    # We'll compute dp where passing through an M adds 1.
    # Since the graph might have cycles (but we are in the case where output is numeric, so no cycle reachable from any D),
    # we must first detect if there is a cycle reachable from any D.
    # If there is, the answer should have been Poor Inna!, so we can assert.
    # We'll do a DFS cycle detection from each D.
    import sys
    sys.setrecursionlimit(10000)
    visited = {}
    recstack = {}
    def has_cycle(v):
        recstack[v] = True
        visited[v] = True
        for nb in g[v]:
            if nb not in visited:
                if has_cycle(nb):
                    return True
            elif recstack.get(nb, False):
                return True
        recstack[v] = False
        return False
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'D' and (i,j) not in visited:
                if has_cycle((i,j)):
                    assert False, f'Cycle found but output is numeric {k}'
    # Now the reachable part is a DAG, we can topo sort and compute dp.
    # But we only need to verify that max dp over D's >= k.
    # We'll compute dp via recursion with memoization on the DAG.
    memo = {}
    def dfs(v):
        if v in memo:
            return memo[v]
        best = 0
        for nb in g[v]:
            best = max(best, dfs(nb))
        if grid[v[0]][v[1]] == 'M':
            best += 1
        memo[v] = best
        return best
    max_from_D = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'D':
                max_from_D = max(max_from_D, dfs((i,j)))
    assert max_from_D >= k, f'Certificate failed: DP max cycles = {max_from_D}, output claims {k}'

def test_no_D_implies_poor_dima(run, x):
    lines = x.strip().split('\n')
