    if not out or out == ['']:
        return
    sell_prices = []
    buy_prices = []
    for line in out:
        d, p_str, _ = line.split()
        p = int(p_str)
        if d == 'S':
            sell_prices.append(p)
        else:
            buy_prices.append(p)
    if sell_prices and buy_prices:
        # According to spec: price of any sell order is higher than price of any buy order.
        # So min sell > max buy.
        assert min(sell_prices) > max(buy_prices), f'Violated price separation: sells {sell_prices}, buys {buy_prices}'


def test_output_format(run, x):
    out = run(x).strip()
    if not out:
        return
    lines = out.split('\n')
    for line in lines:
        parts = line.split()
        assert len(parts) == 3, f'Line does not have exactly three parts: {line}'
        d, p_str, q_str = parts
        assert d in ('S', 'B'), f'Direction not S or B: {d}'
        p = int(p_str)
        q = int(q_str)
        assert 0 <= p <= 10**5, f'Price {p} out of range'
        assert 1 <= q <= 10**4, f'Volume {q} out of range'


def test_volume_non_negative(run, x):
    out = run(x).strip()
    if not out:
        return
    for line in out.split('\n'):
        _, _, q_str = line.split()
        q = int(q_str)
        assert q > 0, f'Volume {q} is not positive'


def test_total_lines(run, x):
    out = run(x).strip().split('\n')
    if out == ['']:
        out = []
    lines = x.strip().split('\n')
    first = lines[0].split()
    if len(first) < 2:
        return
    s = int(first[1])
    # At most 2s lines.
    assert len(out) <= 2 * s, f'Too many lines: {len(out)} > 2*{s}'


def test_metamorphic_add_duplicate(run, x):
    # Add an extra order that duplicates an existing one.
    # The output volumes for that price should increase by the added volume.
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    n_s, s_s = lines[0].split()
    n = int(n_s)
    s = int(s_s)
    # Find an existing order to duplicate.
    for i in range(1, len(lines)):
        d, p_str, q_str = lines[i].split()
        p = int(p_str)
        q = int(q_str)
        # Build new input with an extra duplicate.
        new_lines = [f'{n+1} {s}'] + lines[1:] + [f'{d} {p} {q}']
        new_input = '\n'.join(new_lines)
        out1 = run(x).strip()
        out2 = run(new_input).strip()
        if not out1 or not out2:
            continue
        # Parse outputs.
        def parse(out):
            res = {}
            for line in out.split('\n'):
                dd, pp_str, qq_str = line.split()
                res[(dd, int(pp_str))] = int(qq_str)
            return res
        d1 = parse(out1)
        d2 = parse(out2)
        # For the duplicated price, volume should increase by q.
        key = (d, p)
        if key in d1:
            assert d2.get(key, 0) == d1[key] + q, f'Volume mismatch for duplicate: {d2.get(key)} vs {d1[key]+q}'
        else:
            # If it wasn't in output before, it might appear now.
            # That's fine.
            pass
        break


def test_output_prices_in_input(run, x):
    # Every price in output must appear in input for that direction.
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    input_prices = {'S': set(), 'B': set()}
    for i in range(1, len(lines)):
        d, p_str, _ = lines[i].split()
        input_prices[d].add(int(p_str))
    out = run(x).strip()
    if not out:
        return
    for line in out.split('\n'):
        d, p_str, _ = line.split()
        p = int(p_str)
        assert p in input_prices[d], f'Price {p} for {d} not in input'


def test_volume_sum_matches_input(run, x):
    # For each output line, the volume must equal sum of all input volumes for that price & direction.
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    sums = {'S': {}, 'B': {}}
    for i in range(1, len(lines)):
        d, p_str, q_str = lines[i].split()
        p = int(p_str)
        q = int(q_str)
        sums[d][p] = sums[d].get(p, 0) + q
    out = run(x).strip()
    if not out:
        return
    for line in out.split('\n'):
        d, p_str, q_str = line.split()
        p = int(p_str)
        q = int(q_str)
        assert sums[d][p] == q, f'Volume mismatch: {d} {p} output {q} vs input sum {sums[d].get(p)}'

