def test_output_format(run, x):
    lines = run(x).strip().split('\n')
    # output may be empty if no orders at all, but spec expects <=2s lines
    for line in lines:
        if line.strip() == '':
            continue
        parts = line.split()
        assert len(parts) == 3, f'Line must have 3 parts: {line}'
        d, p_str, q_str = parts
        assert d in ('B', 'S'), f'Direction must be B or S: {d}'
        p = int(p_str)
        q = int(q_str)
        assert 0 <= p <= 100000, f'Price out of range: {p}'
        assert 1 <= q, f'Volume must be positive: {q}'  # aggregated volume >=1 because each order q_i >=1
        # no upper bound on volume from spec


