def test_metamorphic_duplicate_order(run, x):
    # duplicate the first order (if exists) -> volume should double for that price
    lines = x.strip().split('\n')
    header = lines[0]
    n, s = map(int, header.split())
    if n == 0:
        return  # no orders
    first_order = lines[1]
    new_header = f'{n+1} {s}'
    new_input = '\n'.join([new_header, first_order] + lines[1:])
    out1 = run(x).strip()
    out2 = run(new_input).strip()
    # parsing outputs
    def parse_out(out):
        res = {}
        for line in out.split('\n'):
            if line.strip() == '':
                continue
            d, p_str, q_str = line.split()
            key = (d, int(p_str))
            res[key] = int(q_str)
        return res
    d1 = parse_out(out1)
    d2 = parse_out(out2)
    # For every price in out1, volume in out2 should be same or doubled if that price matches duplicated order
    d, p_str, q_str = first_order.split()
    p_dup = int(p_str)
    q_dup = int(q_str)
    for key, vol1 in d1.items():
        dir_, price = key
        vol2 = d2.get(key, 0)
        if dir_ == d and price == p_dup:
            # duplicated order, volume should increase by q_dup
            assert vol2 == vol1 + q_dup, f'Volume for duplicated order {key} changed incorrectly: {vol1} -> {vol2}'
        else:
            assert vol2 == vol1, f'Volume for unrelated order {key} changed: {vol1} -> {vol2}'

