def test_total_pairs(run, x):
    out = run(x).strip().split()
    N = int(x.split()[0])
    total_pairs = N * (N - 1) // 2
    assert sum(map(int, out)) == total_pairs

def test_non_negative(run, x):
    out = run(x).strip().split()
    for val in out:
        assert int(val) >= 0

def test_symmetry_swap_XY(run, x):
    parts = x.strip().split()
    N, X, Y = map(int, parts)
    swapped = f'{N} {Y} {X}\n'
    out1 = run(x).strip().split()
    out2 = run(swapped).strip().split()
    assert out1 == out2

def test_distance_bounds(run, x):
    out = run(x).strip().split()
    N = int(x.split()[0])
    for k_str in out:
        k = int(k_str)
        assert 0 <= k <= N * (N - 1) // 2

def test_output_lines(run, x):
    out = run(x).strip().split()
    N = int(x.split()[0])
    assert len(out) == N - 1

def test_integer_outputs(run, x):
    out = run(x).strip().split()
    for val in out:
        int(val)

def test_large_k_zero(run, x):
    parts = x.strip().split()
    N, X, Y = map(int, parts)
    out = run(x).strip().split()
    for i, val_str in enumerate(out):
        k = i + 1
        if k > N - 1:
            break
        if k > N - 1:
            assert int(val_str) == 0

def test_add_dummy_edge_invariant(run, x):
