    if out:
        ids = list(map(int, out.split()))
        assert len(ids) == n
    else:
        assert False  # output should not be empty

def test_ids_match_input(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    seen_ids = set()
    for line in lines[1:]:
        a, b = map(int, line.split())
        if a != 0:
            seen_ids.add(a)
        if b != 0:
            seen_ids.add(b)
    out = run(x).strip()
    if not out:
        assert False
    out_ids = list(map(int, out.split()))
    assert set(out_ids) == seen_ids
    assert len(out_ids) == len(seen_ids)  # distinctness

def test_adjacency_exists(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    pairs = {}
    for line in lines[1:]:
        a, b = map(int, line.split())
        pairs[(a, b)] = True
    out = run(x).strip()
    if not out:
        assert False
    out_ids = list(map(int, out.split()))
    for i in range(len(out_ids)-1):
        front = out_ids[i]
        back = out_ids[i+1]
        assert (front, back) in pairs or (0, back) in pairs or (front, 0) in pairs  # because zero may replace missing neighbor
        # Actually, the specification says each student writes exactly one pair (a_i,b_i).
        # So the pair (front, back) must appear exactly as given for some student.
        # However, because the order of lines is arbitrary, we just check that the pair exists.
        assert (front, back) in pairs

def test_first_has_zero_front(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    front_zero = False
    for line in lines[1:]:
        a, b = map(int, line.split())
        if a == 0:
            front_zero = True
    out = run(x).strip()
    if not out:
        assert False
    first = int(out.split()[0])
    # There must be a line where a == 0 and b == first
    found = False
    for line in lines[1:]:
        a, b = map(int, line.split())
        if a == 0 and b == first:
            found = True
            break
    assert found

def test_last_has_zero_back(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    out = run(x).strip()
    if not out:
        assert False
    last = int(out.split()[-1])
    found = False
    for line in lines[1:]:
        a, b = map(int, line.split())
        if b == 0 and a == last:
            found = True
            break
    assert found

def test_forward_links_consistent(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    forward = {}
    for line in lines[1:]:
        a, b = map(int, line.split())
        if a != 0:
            forward[a] = b  # a says b is behind
    out = run(x).strip()
    if not out:
        assert False
    out_ids = list(map(int, out.split()))
    for i in range(len(out_ids)-1):
        cur = out_ids[i]
        nxt = out_ids[i+1]
        # If cur is in forward mapping, it must point to nxt (or 0 if nxt doesn't exist, but nxt exists).
        if cur in forward:
            assert forward[cur] == nxt
        else:
            # cur never appears as a front, so it must be last? Actually not necessary.
            pass

