    lines = x.strip().split('\n')
    n = int(lines[0])
    backward = {}
    for line in lines[1:]:
        a, b = map(int, line.split())
        if b != 0:
            backward[b] = a  # b says a is in front
    out = run(x).strip()
    if not out:
        assert False
    out_ids = list(map(int, out.split()))
    for i in range(1, len(out_ids)):
        cur = out_ids[i]
        prev = out_ids[i-1]
        if cur in backward:
            assert backward[cur] == prev
        else:
            # cur never appears as back, so it must be first? Not necessary.
            pass

def test_sum_ids_invariant(run, x):
    # Metamorphic: reversing the queue (by swapping each pair's a and b) should produce the reverse order.
    # But sum of IDs should be the same because it's the same set of IDs.
    # Actually the sum is trivially invariant because the set of IDs is fixed.
    # So we can just check that the sum of output IDs equals sum of all distinct IDs from input.
    lines = x.strip().split('\n')
    n = int(lines[0])
    ids = set()
    for line in lines[1:]:
        a, b = map(int, line.split())
        if a != 0:
            ids.add(a)
        if b != 0:
            ids.add(b)
    out = run(x).strip()
    if not out:
        assert False
    out_ids = list(map(int, out.split()))
    assert sum(out_ids) == sum(ids)

