        a, b = map(int, line.split())
        if a != 0:
            input_ids.add(a)
        if b != 0:
            input_ids.add(b)
    out = run(x).strip()
    if not out:
        assert False
    out_ids = list(map(int, out.split()))
    assert sorted(out_ids) == sorted(input_ids)

def test_endpoint_counts(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    zero_front_count = 0
    zero_back_count = 0
    for line in lines[1:]:
        a, b = map(int, line.split())
        if a == 0:
            zero_front_count += 1
        if b == 0:
            zero_back_count += 1
    # In a valid queue, exactly one student has a==0 (first) and exactly one has b==0 (last).
    assert zero_front_count == 1
    assert zero_back_count == 1
    # The output's first and last elements must correspond to those.
    out = run(x).strip()
    if not out:
        assert False
    out_ids = list(map(int, out.split()))
    first = out_ids[0]
    last = out_ids[-1]
    # Check that there is a line with (0, first) and a line with (last, 0).
    found_first = False
    found_last = False
    for line in lines[1:]:
        a, b = map(int, line.split())
        if a == 0 and b == first:
            found_first = True
        if b == 0 and a == last:
            found_last = True
    assert found_first and found_last

