def test_metamorphic_reversal(run, x):
    # Reverse the queue: for each neighbor record (a,b), create a new record (b,a).
    # This corresponds to reading the queue backwards. The output of the reversed
    # input should be the reverse of the original output.
    lines = x.strip().split('\n')
    n = int(lines[0])
    old_records = lines[1:]
    new_records = []
    for line in old_records:
        a, b = map(int, line.split())
        new_records.append(f'{b} {a}')
    new_input = f'{n}\n' + '\n'.join(new_records)
    out1 = run(x).strip().split()
    out2 = run(new_input).strip().split()
    if out1 == ['']:
        out1 = []
    if out2 == ['']:
        out2 = []
    # The specification does not explicitly require symmetry under reversal,
    # but because the queue order is uniquely determined and reversing the
    # neighbor records yields the reversed queue, the outputs must be reverses.
    # This holds for all valid inputs.
    assert out1 == out2[::-1], f'Reversal metamorphic relation failed'

