def test_rotation_property(run, x):
    out = run(x).strip()
    if out == "Impossible":
        return
    p, x_val = map(int, x.split())
    n = int(out)
    last_digit = n % 10
    rotated = last_digit * (10 ** (p - 1)) + n // 10
    assert n * x_val == rotated, f"{n} * {x_val} != {rotated}"


def test_length_p(run, x):
    out = run(x).strip()
    if out == "Impossible":
        return
    p, _ = map(int, x.split())
    assert len(out) == p, f"length {len(out)} != {p}"


def test_no_leading_zero(run, x):
    out = run(x).strip()
    if out == "Impossible":
        return
    assert out[0] != '0', "leading zero"


def test_positive(run, x):
    out = run(x).strip()
    if out == "Impossible":
        return
    n = int(out)
    assert n > 0, "number not positive"


def test_repdigit_for_x1(run, x):
    p, x_val = map(int, x.split())
    if x_val != 1:
        return
    out = run(x).strip()
    if out == "Impossible":
        # For x=1, there is always a solution: repdigit 1...1
        # So Impossible is wrong.
        assert False, "x=1 must have a solution"
    assert len(set(out)) == 1, f"not a repdigit for x=1: {out}"


def test_first_digit_range(run, x):
    out = run(x).strip()
    if out == "Impossible":
        return
    p, x_val = map(int, x.split())
    if x_val == 1:
        return  # already covered
    first = out[0]
    assert '1' <= first <= '9', f"first digit {first} not in 1..9"


def test_impossible_brute_force_small(run, x):
    p, x_val = map(int, x.split())
    if p > 6:
        return  # skip large p
    out = run(x).strip()
    if out != "Impossible":
        return
    # brute force search for a p-digit number satisfying condition
    lo = 10 ** (p - 1)
    hi = 10 ** p - 1
    for n in range(lo, hi + 1):
        last = n % 10
        if last == 0:
            continue  # because rotating would give leading zero
        rotated = last * (10 ** (p - 1)) + n // 10
        if n * x_val == rotated:
            assert False, f"solution exists: {n}"


def test_number_in_range(run, x):
    out = run(x).strip()
    if out == "Impossible":
        return
    p, _ = map(int, x.split())
    n = int(out)
    lo = 10 ** (p - 1)
    hi = 10 ** p - 1
    assert lo <= n <= hi, f"{n} not in [{lo}, {hi}]"


def test_last_times_x_mod10_equals_first(run, x):
    out = run(x).strip()
    if out == "Impossible":
        return
    p, x_val = map(int, x.split())
    n = int(out)
    last = n % 10
    first = n // (10 ** (p - 1))
    assert (last * x_val) % 10 == first, f"({last}*{x_val}) mod 10 != {first}"


def test_digits_all_decimal(run, x):
    out = run(x).strip()
    if out == "Impossible":
        return
    for ch in out:
        assert ch.isdigit(), f"non-digit character {ch}"

