    chat_part = [0]*m
    for j in range(m):
        for i in range(n):
            if mat[i][j]:
                chat_part[j] += 1
    # total notifications = sum over chats of (messages in chat) * (participants -1)
    total_notif = 0
    for j in range(m):
        total_notif += chat_msg[j] * (chat_part[j] - 1)
    out = run(x).strip()
    if out == '':
        return
    out_vals = list(map(int, out.split()))
    assert sum(out_vals) == total_notif

def test_3_certificate(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    mat = []
    for i in range(1, n+1):
        mat.append(list(map(int, lines[i].split())))
    events = []
    for i in range(n+1, n+1+k):
        if i >= len(lines):
            break
        x_i, y_i = map(int, lines[i].split())
        events.append((x_i-1, y_i-1))
    # compute messages per chat and sent per employee
    chat_msg = [0]*m
    sent = [0]*n
    for emp, ch in events:
        chat_msg[ch] += 1
        sent[emp] += 1
    out = run(x).strip()
    if out == '':
        return
    out_vals = list(map(int, out.split()))
    for i in range(n):
        expected = 0
        for j in range(m):
            if mat[i][j]:
                expected += chat_msg[j]
        expected -= sent[i]
        assert out_vals[i] == expected

def test_4_duplicate_message(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    # duplicate the first event (if any)
    if k == 0:
        return
    new_lines = lines[:]
    # append duplicate of first event
    new_lines.append(new_lines[n+1])
    # update k in first line
    first_parts = lines[0].split()
    first_parts[2] = str(k+1)
    new_lines[0] = ' '.join(first_parts)
    new_input = '\n'.join(new_lines)
    out1 = run(x).strip()
    out2 = run(new_input).strip()
    if out1 == '' or out2 == '':
        return
    vals1 = list(map(int, out1.split()))
    vals2 = list(map(int, out2.split()))
    # parse first event
    emp, ch = map(int, lines[n+1].split())
    emp -= 1
    # for each employee i, if i != emp and mat[i][ch-1]==1, vals2[i] = vals1[i] + 1
    # else vals2[i] = vals1[i]
    mat = []
    for i in range(1, n+1):
        mat.append(list(map(int, lines[i].split())))
    for i in range(n):
        if i == emp:
            assert vals2[i] == vals1[i]
        elif mat[i][ch-1]:
            assert vals2[i] == vals1[i] + 1
        else:
            assert vals2[i] == vals1[i]

def test_5_swap_employees(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    if n < 2:
        return
    # swap rows 1 and 2 (employees 1 and 2) in matrix and in events
    new_lines = lines[:]
    new_lines[1], new_lines[2] = new_lines[2], new_lines[1]
    # swap employee indices in events
    for idx in range(n+1, n+1+k):
        if idx >= len(new_lines):
            break
        parts = new_lines[idx].split()
        emp = int(parts[0])
        ch = int(parts[1])
        if emp == 1:
            emp = 2
        elif emp == 2:
            emp = 1
        new_lines[idx] = f'{emp} {ch}'
    new_input = '\n'.join(new_lines)
    out1 = run(x).strip()
    out2 = run(new_input).strip()
    if out1 == '' or out2 == '':
        return
    vals1 = list(map(int, out1.split()))
    vals2 = list(map(int, out2.split()))
    # outputs should be swapped at positions 0 and 1
    assert vals2[0] == vals1[1]
    assert vals2[1] == vals1[0]
    # all other outputs unchanged
    for i in range(2, n):
        assert vals2[i] == vals1[i]

def test_6_no_chats_zero(run, x):
    lines = x.strip().split('\n')
