def test_7_upper_bound(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    mat = []
    for i in range(1, n+1):
        mat.append(list(map(int, lines[i].split())))
    # compute max chat size
    chat_size = [0]*m
    for j in range(m):
        for i in range(n):
            if mat[i][j]:
                chat_size[j] += 1
    max_in_chat = max(chat_size) if m > 0 else 0
    # total messages per chat
    chat_msg = [0]*m
    for idx in range(n+1, n+1+k):
        if idx >= len(lines):
            break
        _, y = map(int, lines[idx].split())
        chat_msg[y-1] += 1
    out = run(x).strip()
    if out == '':
        return
    vals = list(map(int, out.split()))
    for i in range(n):
        # employee i can receive at most sum over their chats of (messages in chat)*(chat_size-1)
        max_possible = 0
        for j in range(m):
            if mat[i][j]:
                max_possible += chat_msg[j] * (chat_size[j] - 1)
        assert vals[i] <= max_possible

def test_8_single_chat(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    if m != 1:
        return
    # all messages are in the single chat
    # compute messages sent per employee
    sent = [0]*n
    for idx in range(n+1, n+1+k):
        if idx >= len(lines):
            break
        emp, _ = map(int, lines[idx].split())
        sent[emp-1] += 1
    total_msgs = sum(sent)
    out = run(x).strip()
    if out == '':
        return
    vals = list(map(int, out.split()))
    # each employee's notifications = total_msgs - sent[i]  (if they are in the chat)
    # but some employees may not be in the chat
    mat = []
    for i in range(1, n+1):
        mat.append(list(map(int, lines[i].split())))
    for i in range(n):
        if mat[i][0]:
            assert vals[i] == total_msgs - sent[i]
        else:
            assert vals[i] == 0

def test_9_add_one_message(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    if k == 0:
        return
    # pick an employee and a chat they belong to
    mat = []
    for i in range(1, n+1):
        mat.append(list(map(int, lines[i].split())))
    # find first employee with at least one chat
    emp = -1
    chat = -1
    for i in range(n):
        for j in range(m):
            if mat[i][j]:
                emp = i
                chat = j
                break
        if emp != -1:
            break
    if emp == -1:
        return  # no one in any chat
    # create new input with one extra message from emp to chat
    new_lines = lines[:]
    new_lines.append(f'{emp+1} {chat+1}')
    first_parts = lines[0].split()
    first_parts[2] = str(k+1)
    new_lines[0] = ' '.join(first_parts)
    new_input = '\n'.join(new_lines)
    out1 = run(x).strip()
    out2 = run(new_input).strip()
    if out1 == '' or out2 == '':
        return
    vals1 = list(map(int, out1.split()))
    vals2 = list(map(int, out2.split()))
    # for each employee i, if i != emp and mat[i][chat], vals2[i] = vals1[i] + 1
    for i in range(n):
        if i == emp:
            continue
        if mat[i][chat]:
            assert vals2[i] == vals1[i] + 1
        else:
            assert vals2[i] == vals1[i]

