def test_brute_force_small_n(run, x):
    n, k = map(int, x.strip().split())
    if n > 5:
        return  # skip for large n
    # brute force all colorings
    total = 0
    for mask in range(1 << (2*n)):
        # represent coloring as bits: first row bits 0..n-1, second row bits n..2n-1
        comp = 0
        visited = [False] * (2*n)
        # compute components using BFS/DFS
        for start in range(2*n):
            if not visited[start]:
                comp += 1
                stack = [start]
                visited[start] = True
                while stack:
                    v = stack.pop()
                    row = v // n
                    col = v % n
                    color = (mask >> v) & 1
                    # neighbours: up, down, left, right within grid and same color
                    for dr, dc in [(1,0),(-1,0),(0,1),(0,-1)]:
                        nr = row + dr
                        nc = col + dc
                        if 0 <= nr < 2 and 0 <= nc < n:
                            nv = nr * n + nc
                            if not visited[nv] and ((mask >> nv) & 1) == color:
                                visited[nv] = True
                                stack.append(nv)
        if comp == k:
            total += 1
    total %= 998244353
    out = int(run(x).strip())
    assert out == total

def test_non_negative(run, x):
    out = run(x).strip()
    ans = int(out)
    assert ans >= 0

def test_upper_bound(run, x):
    n, k = map(int, x.strip().split())
    out = int(run(x).strip())
    total_colorings = pow(2, 2*n, 998244353)
    assert out <= total_colorings

