def test_size_equals_divisor_count(run, x):
    n = int(x.strip())
    # count divisors
    cnt = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            cnt += 1
            if i * i != n:
                cnt += 1
        i += 1
    out = run(x).strip()
    vals = list(map(int, out.split()))
    if len(vals) != cnt:
        assert False


def test_each_divisor_fun_in_output(run, x):
    n = int(x.strip())
    # compute all divisors
    divisors = []
    i = 1
    while i * i <= n:
        if n % i == 0:
            divisors.append(i)
            if i * i != n:
                divisors.append(n // i)
        i += 1
    # compute fun for each divisor d
    expected_vals = []
    for d in divisors:
        L = n // d
        # sum = n/d * (n - d + 2) // 2
        v = L * (n - d + 2) // 2
        expected_vals.append(v)
    out = run(x).strip()
    output_vals = set(map(int, out.split()))
    for v in expected_vals:
        if v not in output_vals:
            assert False


def test_output_vals_are_distinct(run, x):
