def test_all_output_vals_correspond_to_divisor(run, x):
    n = int(x.strip())
    # compute all possible fun values from divisors
    divisors = []
    i = 1
    while i * i <= n:
        if n % i == 0:
            divisors.append(i)
            if i * i != n:
                divisors.append(n // i)
        i += 1
    expected_set = set()
    for d in divisors:
        L = n // d
        v = L * (n - d + 2) // 2
        expected_set.add(v)
    out = run(x).strip()
    output_vals = set(map(int, out.split()))
    # every output value must be in expected_set
    for v in output_vals:
        if v not in expected_set:
            assert False


def test_sum_of_outputs_bounded(run, x):
    n = int(x.strip())
    out = run(x).strip()
    vals = list(map(int, out.split()))
    total = sum(vals)
    # weak bound: total <= number_of_divisors * n*(n+1)//2
    # but simpler: each value <= n*(n+1)//2, and number of divisors <= 2*sqrt(n) <= 2*31623 ~63246
    max_total = (n * (n + 1) // 2) * (2 * int(n**0.5) + 5)
    if total > max_total:
        assert False
    # also total >= sum of 1..len(vals) (since each >=1)
    if total < len(vals) * (len(vals) + 1) // 2:
        assert False


