def test_output_format(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    if not lines:
        assert False, 'empty output'
    try:
        k = int(lines[0].strip())
    except ValueError:
        assert False, 'first line not integer'
    if len(lines) - 1 != k:
        assert False, 'count mismatch'
    for line in lines[1:]:
        parts = line.split()
        if len(parts) != 2:
            assert False, 'dependency line should have name and version'
        name, ver = parts
        if not name.isalpha() or not name.islower() or len(name) > 10:
            assert False, 'invalid name'
        if not ver.isdigit():
            assert False, 'version not integer'
        v = int(ver)
        if not 1 <= v <= 10**6:
            assert False, 'version out of range'
    # names should be unique
    names = [line.split()[0] for line in lines[1:]]
    if len(names) != len(set(names)):
        assert False, 'duplicate names in output'
    # lexicographic order
    sorted_names = sorted(names)
    if names != sorted_names:
        assert False, 'names not in lexicographic order'

