    assert 0 <= k < n, f'output size {k} should be less than n={n}'

def test_dependency_closure(run, x):
    # Build adjacency from input
    import sys
    from collections import deque
    lines = x.strip().split('\n')
    idx = 0
    n = int(lines[idx]); idx+=1
    projects = {}
    deps_of = {}
    # parse
    for _ in range(n):
        while lines[idx].strip() == '':
            idx+=1
        name, ver = lines[idx].split(); idx+=1
        key = (name, ver)
        projects[key] = True
        deps_of[key] = []
        num = int(lines[idx]); idx+=1
        for __ in range(num):
            dep_name, dep_ver = lines[idx].split(); idx+=1
            deps_of[key].append((dep_name, dep_ver))
        if _ != n-1:
            idx+=1  # blank line
    # root is first project
    root_key = list(projects.keys())[0]
    out = run(x)
    out_lines = out.strip().split('\n')
    if len(out_lines) <= 1:
        # no dependencies, closure trivial
        return
    k = int(out_lines[0])
    chosen = {}
    for line in out_lines[1:]:
        name, ver = line.split()
        chosen[name] = ver
    # BFS from root using only chosen versions for each name
    visited = set()
    q = deque([root_key])
    visited.add(root_key)
    while q:
        cur = q.popleft()
        for dep_name, dep_ver in deps_of[cur]:
            if dep_name in chosen and chosen[dep_name] == dep_ver:
                dep_key = (dep_name, dep_ver)
                if dep_key not in visited:
                    visited.add(dep_key)
                    q.append(dep_key)
    # Every chosen dependency must be reachable
    for name, ver in chosen.items():
        if (name, ver) not in visited:
            assert False, f'chosen {name} {ver} not reachable from root via chosen versions'

