    has_neg = False
    for i in range(1, n+1):
        _, y = map(int, lines[i].split())
        if y > 0:
            has_pos = True
        else:
            has_neg = True
    out = run(x).strip()
    if out == '-1':
        assert has_pos and has_neg, '-1 output but points have same y sign'

