import math
def test_radius_at_least_half_pair_distance(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    points = []
    for i in range(1, n+1):
        xp, yp = map(int, lines[i].split())
        points.append((xp, yp))
    out = run(x).strip()
    if out == '-1':
        return
    r = float(out)
    # lower bound: for any two points with same sign y, distance <= 2r
    for i in range(n):
        for j in range(i+1, n):
            if points[i][1]*points[j][1] > 0:  # same sign
                dx = points[i][0] - points[j][0]
