def test_output_length_equals_input_length(run, x):
    out = run(x)
    lines = x.strip().split('\n')
    text = lines[2]
    assert len(out) == len(text), f'Length mismatch: output {len(out)} vs input {len(text)}'

def test_non_letters_unchanged(run, x):
    out = run(x)
    lines = x.strip().split('\n')
    text = lines[2]
    for c1, c2 in zip(text, out):
        if not c1.isalpha():
            assert c1 == c2, f'Non-letter changed: {c1} -> {c2}'

def test_mapping_reversible(run, x):
    lines = x.strip().split('\n')
    layout1 = lines[0]
    layout2 = lines[1]
    text = lines[2]
    out = run(x)
    # Build mapping from layout1 to layout2 (lowercase)
    map12 = {layout1[i]: layout2[i] for i in range(26)}
    # Build mapping from layout2 to layout1 (lowercase)
    map21 = {layout2[i]: layout1[i] for i in range(26)}
    # Apply reverse mapping to output letters should get original letters (case-insensitive)
    for c_in, c_out in zip(text, out):
        if c_in.isalpha():
            c_in_low = c_in.lower()
            c_out_low = c_out.lower()
            expected_low = map12.get(c_in_low, c_in_low)
            assert c_out_low == expected_low, f'Forward mapping failed: {c_in} -> {c_out}'
            # Reverse mapping
            rev_low = map21.get(c_out_low, c_out_low)
            assert rev_low == c_in_low, f'Reverse mapping failed: {c_out} -> {rev_low} != {c_in_low}'

def test_capitalization_preserved(run, x):
    lines = x.strip().split('\n')
    text = lines[2]
    out = run(x)
    for c_in, c_out in zip(text, out):
        if c_in.isalpha():
            assert c_in.isupper() == c_out.isupper(), f'Capitalization changed: {c_in} -> {c_out}'

def test_only_letters_change(run, x):
    lines = x.strip().split('\n')
    text = lines[2]
    out = run(x)
    for c_in, c_out in zip(text, out):
        if not c_in.isalpha():
            assert c_in == c_out, f'Non-letter changed: {c_in} -> {c_out}'
        else:
            assert c_out.isalpha(), f'Letter became non-letter: {c_in} -> {c_out}'

def test_swap_layouts_reverses(run, x):
    lines = x.strip().split('\n')
    layout1 = lines[0]
    layout2 = lines[1]
    text = lines[2]
    # Create swapped input: layout2 becomes first layout, layout1 becomes second layout
    swapped_input = '\n'.join([layout2, layout1, text])
    out_original = run(x)
    out_swapped = run(swapped_input)
    # Applying transformation twice should return original text (since layouts are swapped)
    assert out_swapped == text, f'Swapping layouts did not reverse: got {out_swapped}, expected {text}'

def test_digits_unchanged(run, x):
    lines = x.strip().split('\n')
    text = lines[2]
    out = run(x)
    for c_in, c_out in zip(text, out):
        if c_in.isdigit():
            assert c_in == c_out, f'Digit changed: {c_in} -> {c_out}'

def test_output_letters_in_alphabet(run, x):
    out = run(x)
    for c in out:
        if c.isalpha():
            assert c.lower() in 'abcdefghijklmnopqrstuvwxyz', f'Invalid letter in output: {c}'

def test_case_insensitive_mapping_consistent(run, x):
    lines = x.strip().split('\n')
    layout1 = lines[0]
    layout2 = lines[1]
    text = lines[2]
    out = run(x)
    map12 = {layout1[i]: layout2[i] for i in range(26)}
    # For each letter in input, its lowercase mapping should match output's lowercase
    for c_in, c_out in zip(text, out):
        if c_in.isalpha():
            c_in_low = c_in.lower()
            c_out_low = c_out.lower()
            expected = map12.get(c_in_low, c_in_low)
            assert c_out_low == expected, f'Mapping mismatch: {c_in_low} -> {c_out_low} expected {expected}'

def test_mapping_deterministic(run, x):
    lines = x.strip().split('\n')
    layout1 = lines[0]
    layout2 = lines[1]
    text = lines[2]
    out = run(x)
    map12 = {layout1[i]: layout2[i] for i in range(26)}
    seen = {}
    for c_in, c_out in zip(text, out):
        if c_in.isalpha():
            key = c_in.lower()
            val = c_out.lower()
            if key in seen:
                assert seen[key] == val, f'Non-deterministic mapping for {key}: {seen[key]} vs {val}'
            else:
                seen[key] = val

