def test_metamorphic_scaling(run, x):
    lines = x.strip().split('\n')
    if not lines:
        return
    n_m = lines[0].split()
    if len(n_m) < 2:
        return
    n, m = map(int, n_m)
    if m == 0:
        # scaling empty list does nothing
        return
    # Scale every debt by 2
    scaled_lines = [f'{n} {m}']
    for line in lines[1:]:
        if not line.strip():
            continue
        a, b, c = line.split()
        scaled_lines.append(f'{a} {b} {int(c)*2}')
    scaled_input = '\n'.join(scaled_lines)
    out1 = run(x).strip()
    out2 = run(scaled_input).strip()
    if not (out1.isdigit() and out2.isdigit()):
        assert False, 'output not integer'
    if int(out1) * 2 != int(out2):
        assert False, 'scaling property violated'

def test_metamorphic_relabeling(run, x):
    import random
    lines = x.strip().split('\n')
    if not lines:
        return
    n_m = lines[0].split()
    if len(n_m) < 2:
        return
    n, m = map(int, n_m)
    if n == 0:
        return
    perm = list(range(1, n+1))
    random.shuffle(perm)
    # perm[i] is new label for old i+1
    relabeled_lines = [f'{n} {m}']
    for line in lines[1:]:
        if not line.strip():
            continue
        a, b, c = line.split()
        a, b, c = int(a), int(b), int(c)
        new_a = perm[a-1]
        new_b = perm[b-1]
        relabeled_lines.append(f'{new_a} {new_b} {c}')
    relabeled_input = '\n'.join(relabeled_lines)
    out1 = run(x).strip()
    out2 = run(relabeled_input).strip()
    if not (out1.isdigit() and out2.isdigit()):
        assert False, 'output not integer'
    if int(out1) != int(out2):
        assert False, 'relabeling property violated'

