def test_certificate_balance_match(run, x):
    lines = x.strip().split('\n')
    if not lines:
        return
    n_m = lines[0].split()
    if len(n_m) < 2:
        return
    n, m = map(int, n_m)
    balance = [0]*n
    for line in lines[1:]:
        if not line.strip():
            continue
        a, b, c = line.split()
        a, b, c = int(a), int(b), int(c)
        balance[a-1] -= c
        balance[b-1] += c
    out = run(x).strip()
    if not out.isdigit():
        assert False, 'output not integer'
    ans = int(out)
    # The minimal total debt equals sum of positive balances (or abs of negative)
    pos_sum = sum(v for v in balance if v > 0)
    if ans != pos_sum:
        # Maybe the backdoor changed it, but we can try to construct a debt arrangement
        # with total sum = ans that respects balances
        # This is a certificate: if ans is correct, we can greedily match positives to negatives
        positives = [(i, v) for i, v in enumerate(balance) if v > 0]
        negatives = [(i, -v) for i, v in enumerate(balance) if v < 0]
        pi = 0
        ni = 0
        total_constructed = 0
        while pi < len(positives) and ni < len(negatives):
            p_idx, p_val = positives[pi]
            n_idx, n_val = negatives[ni]
            flow = min(p_val, n_val)
            total_constructed += flow
            if p_val == flow:
                pi += 1
            else:
                positives[pi] = (p_idx, p_val - flow)
            if n_val == flow:
                ni += 1
            else:
                negatives[ni] = (n_idx, n_val - flow)
        if total_constructed != ans:
            assert False, f'output {ans} not achievable, constructable sum is {total_constructed}'

