def test_output_shape(run, x):
    output = run(x).strip()
    assert output in {"YES", "NO", "yes", "no", "Yes", "No"}, f"Output must be YES/NO, got '{output}'"

def test_non_decreasing_plays(run, x):
    lines = x.strip().split('\n')
    T = int(lines[0])
    idx = 1
    for _ in range(T):
        n = int(lines[idx]); idx += 1
        last_p = -1
        for i in range(n):
            p, c = map(int, lines[idx].split()); idx += 1
            if i > 0 and p < last_p:
                # If plays decreased, answer must be NO
                output = run(x).strip().upper()
                if output == "YES":
                    assert False, f"Plays decreased ({last_p} -> {p}) but answer is YES"
                return  # No need to check further for this test case
            last_p = p
    # If we never saw a decrease, test passes
    pass

def test_non_decreasing_clears(run, x):
    lines = x.strip().split('\n')
    T = int(lines[0])
    idx = 1
    for _ in range(T):
        n = int(lines[idx]); idx += 1
        last_c = -1
        for i in range(n):
            p, c = map(int, lines[idx].split()); idx += 1
            if i > 0 and c < last_c:
                output = run(x).strip().upper()
                if output == "YES":
                    assert False, f"Clears decreased ({last_c} -> {c}) but answer is YES"
                return
            last_c = c
    pass

def test_clears_never_exceed_plays(run, x):
    lines = x.strip().split('\n')
    T = int(lines[0])
    idx = 1
    for _ in range(T):
        n = int(lines[idx]); idx += 1
        for i in range(n):
            p, c = map(int, lines[idx].split()); idx += 1
            if c > p:
                output = run(x).strip().upper()
                if output == "YES":
                    assert False, f"Clears {c} > plays {p} but answer is YES"
                return
    pass

def test_initial_zero_or_greater(run, x):
    lines = x.strip().split('\n')
    T = int(lines[0])
    idx = 1
    for _ in range(T):
        n = int(lines[idx]); idx += 1
        for i in range(n):
            p, c = map(int, lines[idx].split()); idx += 1
            if p < 0 or c < 0:
                output = run(x).strip().upper()
                if output == "YES":
                    assert False, f"Negative stats ({p}, {c}) but answer is YES"
                return
    pass

def test_change_clears_without_plays(run, x):
    lines = x.strip().split('\n')
    T = int(lines[0])
    idx = 1
    for _ in range(T):
        n = int(lines[idx]); idx += 1
        last_p = last_c = -1
        for i in range(n):
            p, c = map(int, lines[idx].split()); idx += 1
            if i > 0:
                if p == last_p and c != last_c:
                    output = run(x).strip().upper()
                    if output == "YES":
                        assert False, f"Clears changed ({last_c} -> {c}) without plays change but answer is YES"
                    return
            last_p, last_c = p, c
    pass

def test_validate_sequence(run, x):
    lines = x.strip().split('\n')
    T = int(lines[0])
    idx = 1
    output = run(x).strip().upper()
    out_lines = output.split('\n')
    assert len(out_lines) == T, f"Expected {T} lines, got {len(out_lines)}"
    for case_idx in range(T):
        n = int(lines[idx]); idx += 1
        records = []
        for i in range(n):
            p, c = map(int, lines[idx].split()); idx += 1
            records.append((p, c))
        ans = out_lines[case_idx].strip().upper()
        # Simulate feasibility
        feasible = True
        last_p = last_c = 0
        for p, c in records:
            dp = p - last_p
            dc = c - last_c
            if dp < 0 or dc < 0 or dc > dp:
                feasible = False
                break
            last_p, last_c = p, c
        if feasible:
            assert ans == "YES", f"Feasible but answer is {ans}"
        else:
            assert ans == "NO", f"Infeasible but answer is {ans}"
    pass

def test_output_case_insensitive(run, x):
    output = run(x).strip()
    assert output.upper() in {"YES", "NO"}, f"Output must be YES/NO (case-insensitive), got '{output}'"

def test_no_extra_output(run, x):
    output = run(x).strip()
    lines = output.split('\n')
    T = int(x.strip().split('\n')[0])
    assert len(lines) == T, f"Expected exactly {T} lines, got {len(lines)}"
    for line in lines:
        assert line.strip().upper() in {"YES", "NO"}, f"Line '{line}' is not YES/NO"

def test_monotonic_plays_and_clears(run, x):
    lines = x.strip().split('\n')
    T = int(lines[0])
    idx = 1
    output = run(x).strip().upper().split('\n')
    for case_idx in range(T):
        n = int(lines[idx]); idx += 1
        records = []
        for i in range(n):
            p, c = map(int, lines[idx].split()); idx += 1
            records.append((p, c))
        ans = output[case_idx]
        if ans == "YES":
            # For YES, plays and clears must be non-decreasing
            for i in range(1, n):
                if records[i][0] < records[i-1][0] or records[i][1] < records[i-1][1]:
                    assert False, f"YES but plays or clears decreased at step {i}"
            # And clears <= plays always
            for p, c in records:
                if c > p:
                    assert False, f"YES but clears {c} > plays {p}"
        # If NO, no constraints (could be monotonic but still infeasible due to delta constraints)
    pass

