import itertools

def test_bruteforce_small_n(run, x):
    n_str = x.strip()
    try:
        n = int(n_str)
    except ValueError:
        return  # not an integer input, shouldn't happen
    if n > 6:
        return  # too large to brute-force
    # Compute winner by brute-force minimax
    # Board representation: bitmask of n*n cells, 0 = empty, 1 = painted
    total_cells = n * n
    # Precompute neighbors: cells that share a side
    neighbors = [[] for _ in range(total_cells)]
    for i in range(n):
        for j in range(n):
            idx = i * n + j
            if i > 0:
                neighbors[idx].append(idx - n)
            if i < n-1:
                neighbors[idx].append(idx + n)
            if j > 0:
                neighbors[idx].append(idx - 1)
            if j < n-1:
                neighbors[idx].append(idx + 1)
    from functools import lru_cache
    @lru_cache(None)
    def winner(mask, player):  # player 1 = first (maximizing), player 2 = second (minimizing)
        # Returns 1 if player 1 wins from this state, 2 if player 2 wins.
        # player indicates whose turn it is (1 or 2).
        moves = []
        for cell in range(total_cells):
            if mask & (1 << cell):
                continue  # painted
            # check if any neighbor painted
            ok = True
            for nb in neighbors[cell]:
                if mask & (1 << nb):
                    ok = False
                    break
            if ok:
                moves.append(cell)
        if not moves:
            return 2 if player == 1 else 1  # current player loses
        # Try each move
        best_for_current = None
        for cell in moves:
            newmask = mask | (1 << cell)
            w = winner(newmask, 2 if player == 1 else 1)
            if w == player:
                # current player can force win
                return player
            best_for_current = w if best_for_current is None else best_for_current
        # If we reach here, current player cannot force win, so opponent wins
        return 2 if player == 1 else 1
    expected = winner(0, 1)  # starting with empty board, first player's turn
    out = int(run(x).strip())
    assert out == expected, f'For n={n}, expected {expected}, got {out}'

