        max_pos = max(max_pos, cursor)
        brackets = []
        for p in range(1, max_pos + 1):
            ch = pos_to_char.get(p, '')
            if ch == '(' or ch == ')':
                brackets.append(ch)
        if brackets:
            # Check correctness
            bal = 0
            ok = True
            for ch in brackets:
                if ch == '(':
                    bal += 1
                else:
                    bal -= 1
                    if bal < 0:
                        ok = False
                        break
            if bal != 0:
                ok = False
            if ok:
                got = int(out[idx])
                assert got >= 1, f'At prefix {idx+1}, brackets exist but colors {got} < 1'

