def test_points_on_square_perimeter(run, x):
    """Each reported point must lie exactly on the square boundary."""
    lines = x.strip().split('\n')
    a, d = map(float, lines[0].split())
    n = int(lines[1])
    out = run(x).strip().split('\n')
    for i, line in enumerate(out):
        if not line:
            continue
        xi, yi = map(float, line.split())
        on_boundary = (
            (abs(xi) < 1e-9 or abs(xi - a) < 1e-9 or abs(yi) < 1e-9 or abs(yi - a) < 1e-9)
            and 0 - 1e-9 <= xi <= a + 1e-9
            and 0 - 1e-9 <= yi <= a + 1e-9
        )
        assert on_boundary, f"Point ({xi}, {yi}) not on square boundary"

def test_consecutive_distances_along_path(run, x):
    """Distance along perimeter between consecutive points must equal d."""
    lines = x.strip().split('\n')
    a, d = map(float, lines[0].split())
    n = int(lines[1])
    out = run(x).strip().split('\n')
    if n <= 1:
        return
    points = []
    for line in out:
        if not line:
            continue
        xv, yv = map(float, line.split())
        points.append((xv, yv))
    def dist_on_perimeter(p1, p2):
        x1, y1 = p1
        x2, y2 = p2
        if abs(y1) < 1e-9 and abs(y2) < 1e-9:
            return abs(x2 - x1)
        if abs(x1 - a) < 1e-9 and abs(x2 - a) < 1e-9:
            return abs(y2 - y1)
        if abs(y1 - a) < 1e-9 and abs(y2 - a) < 1e-9:
            return abs(x1 - x2)
        if abs(x1) < 1e-9 and abs(x2) < 1e-9:
            return abs(y1 - y2)
        return float('inf')
    for i in range(len(points)-1):
        dist = dist_on_perimeter(points[i], points[i+1])
        assert abs(dist - d) < 1e-6, f"Distance between points {i} and {i+1} is {dist}, expected {d}"

def test_periodicity_after_full_lap(run, x):
    """After covering 4*a distance, coordinates repeat (metamorphic)."""
    lines = x.strip().split('\n')
    a, d = map(float, lines[0].split())
    n = int(lines[1])
    if d == 0:
        return
    out = run(x).strip().split('\n')
    points = []
    for line in out:
        if not line:
            continue
        xv, yv = map(float, line.split())
        points.append((xv, yv))
    perimeter = 4 * a
    full_laps = int(perimeter // d)  # number of d steps in one full lap
