            continue
        xi, yi = map(float, line.split())
        total = (i+1)*d
        laps = total / (4*a)
        frac = laps - int(laps)
        if frac < 1e-9 or frac > 1 - 1e-9:
            continue
        perimeter_pos = frac * 4*a
        side = int(perimeter_pos // a)  # 0 bottom, 1 right, 2 top, 3 left
