def test_no_extra_output_lines(run, x):
    lines = x.strip().split('\n')
    q = int(lines[1 + int(lines[0].split()[1])])
    out_lines = run(x).strip().split('\n')
    # count non-empty lines
    non_empty = [ln for ln in out_lines if ln.strip() != '']
    assert len(non_empty) == q

def test_connectivity_via_direct_edge(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    edges = []
    for i in range(1, m+1):
        a, b, c = map(int, lines[i].split())
        edges.append((a-1, b-1, c-1))
    q = int(lines[m+1])
    queries = []
    for i in range(m+2, m+2+q):
        u, v = map(int, lines[i].split())
        queries.append((u-1, v-1))
    out = run(x).strip().split('\n')
    for (u, v), ans_str in zip(queries, out):
        if not ans_str:
            continue
        ans = int(ans_str)
        # If there is a direct edge of color c between u and v, then color c must be counted
        direct_colors = set()
        for a, b, c in edges:
            if (a == u and b == v) or (a == v and b == u):
                direct_colors.add(c)
        # ans must be at least |direct_colors|
        assert ans >= len(direct_colors)

def test_identical_queries_same_answer(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    q = int(lines[m+1])
    # If there are duplicate queries in the input, they must give same answer
    queries = []
    for i in range(m+2, m+2+q):
        u, v = map(int, lines[i].split())
        queries.append((u, v))
    out = run(x).strip().split('\n')
    ans_dict = {}
    for (u, v), ans_str in zip(queries, out):
        if ans_str:
            key = (u, v)
            if key in ans_dict:
                assert ans_dict[key] == int(ans_str)
            else:
                ans_dict[key] = int(ans_str)

def test_answer_zero_or_at_least_three(run, x):
    out = run(x).strip()
    # first line is t, then each test output line
    lines = out.split()
    for ans in lines:
        val = int(ans)
        assert val == 0 or val >= 3, f'Answer {val} must be 0 or >=3'

def test_if_all_digits_present_answer_ge_three(run, x):
    out = run(x).strip()
    lines = out.split()
    inp_lines = x.strip().split('\n')[1:]  # skip t
    for s, ans in zip(inp_lines, lines):
        if '1' in s and '2' in s and '3' in s:
            assert int(ans) >= 3, f'All digits present so answer must be >=3, got {ans}'

def test_certificate_substring_exists(run, x):
    out = run(x).strip()
    lines = out.split()
    inp_lines = x.strip().split('\n')[1:]
    for s, ans_str in zip(inp_lines, lines):
        ans = int(ans_str)
        if ans == 0:
            continue
        # find any substring of length ans containing 1,2,3
        found = False
        for i in range(len(s) - ans + 1):
            sub = s[i:i+ans]
            if '1' in sub and '2' in sub and '3' in sub:
                found = True
                break
        assert found, f'No substring of length {ans} contains 1,2,3 in {s}'

def test_certificate_zero_implies_missing_digit(run, x):
    out = run(x).strip()
    lines = out.split()
    inp_lines = x.strip().split('\n')[1:]
    for s, ans_str in zip(inp_lines, lines):
        ans = int(ans_str)
        if ans == 0:
            assert not ('1' in s and '2' in s and '3' in s), f'Answer 0 but all digits present in {s}'

def test_metamorphic_reverse(run, x):
    # Build input with reversed string
    parts = x.strip().split('\n')
    t = int(parts[0])
    new_parts = [parts[0]]
    for s in parts[1:]:
        new_parts.append(s[::-1])
    new_input = '\n'.join(new_parts)
    out1 = run(x).strip().split()
    out2 = run(new_input).strip().split()
    for a1, a2 in zip(out1, out2):
        assert a1 == a2, f'Reversing string changed answer: {a1} vs {a2}'

def test_answer_not_exceed_length(run, x):
    out = run(x).strip()
    lines = out.split()
    inp_lines = x.strip().split('\n')[1:]
    for s, ans_str in zip(inp_lines, lines):
        ans = int(ans_str)
        assert ans <= len(s), f'Answer {ans} exceeds length {len(s)}'

def test_bound_len_plus_one(run, x):
    # trivial bound, answer cannot be larger than length+1
    out = run(x).strip()
    lines = out.split()
    inp_lines = x.strip().split('\n')[1:]
    for s, ans_str in zip(inp_lines, lines):
        ans = int(ans_str)
        assert ans <= len(s) + 1, f'Answer {ans} > len+1 impossible'

def test_metamorphic_permute_digits(run, x):
    # permute digits 1->2, 2->3, 3->1 (any bijection)
    # problem symmetric in digits, so answer unchanged
    perm = {'1':'2', '2':'3', '3':'1'}
    parts = x.strip().split('\n')
    t = int(parts[0])
    new_parts = [parts[0]]
    for s in parts[1:]:
        new_s = ''.join(perm[ch] for ch in s)
        new_parts.append(new_s)
    new_input = '\n'.join(new_parts)
    out1 = run(x).strip().split()
    out2 = run(new_input).strip().split()
    for a1, a2 in zip(out1, out2):
        assert a1 == a2, f'Permuting digits changed answer: {a1} vs {a2}'

def test_certificate_full_length(run, x):
    out = run(x).strip()
    lines = out.split()
    inp_lines = x.strip().split('\n')[1:]
    for s, ans_str in zip(inp_lines, lines):
        ans = int(ans_str)
        if ans == len(s):
            # then whole string must contain 1,2,3
            assert '1' in s and '2' in s and '3' in s, f'Answer equals length {len(s)} but missing digit'

def test_answer_is_integer(run, x):
    out = run(x).strip()
    lines = out.split()
    for ans in lines:
        int(ans)  # will raise if not integer
        # also ensure non-negative
        assert int(ans) >= 0, f'Answer {ans} negative'

