def test_output_format(run, x):
    lines = run(x).strip().split()
    for line in lines:
        assert line.upper() in ("YES", "NO"), f"invalid output line: {line}"
    n = int(x.split('\n')[0])
    q = int(x.split('\n')[2])
    assert len(lines) == q + 1, f"expected {q+1} lines, got {len(lines)}"


def test_no_on_less_than_8_planks(run, x):
    # parse initial planks
    parts = x.strip().split('\n')
    n = int(parts[0])
    initial = list(map(int, parts[1].split())) if n > 0 else []
    events = parts[2:] if len(parts) > 2 else []
    q = int(events[0]) if events else 0
    event_lines = events[1:] if q > 0 else []
    # simulate counts
    from collections import defaultdict
    cnt = defaultdict(int)
    for v in initial:
        cnt[v] += 1
    total = sum(cnt.values())
    for i, line in enumerate(event_lines):
        if total < 8:
            out = run(x).strip().split('\n')[i]
            assert out.upper() == "NO", f"total planks {total} < 8 but answer was {out}"
        # update total
        if line[0] == '+':
            total += 1
        else:
            total -= 1
    # last event
    if total < 8:
        out = run(x).strip().split('\n')[q]
        assert out.upper() == "NO", f"final total planks {total} < 8 but answer was {out}"


