    q = int(events[0]) if events else 0
    event_lines = events[1:] if q > 0 else []
    cnt = {}
    for v in initial:
        cnt[v] = cnt.get(v, 0) + 1
    outputs = run(x).strip().split('\n')
    for i in range(q+1):
        if outputs[i].upper() == "YES":
            if not any(c >= 4 for c in cnt.values()):
                raise AssertionError(f"YES but no length with count >=4 at step {i}, counts {cnt}")
        # update for next
        if i < q:
            op, num = event_lines[i].split()
            num = int(num)
            if op == '+':
                cnt[num] = cnt.get(num, 0) + 1
            else:
                cnt[num] -= 1
                if cnt[num] == 0:
