            rem[sq_len] -= 4
            # check rectangle possible from rem
            rect_possible = False
            # case: 4 of same length
            if any(c >= 4 for c in rem.values()):
                rect_possible = True
            else:
                # two distinct lengths each >=2
                ge2 = [l for l, c in rem.items() if c >= 2]
                if len(ge2) >= 2:
                    rect_possible = True
                # also one length with >=2 and another pair from same length? No, need two pairs.
                # one length with >=4 already covered.
            if not rect_possible:
                raise AssertionError(f"YES but rectangle impossible after taking square at step {i}, rem {rem}")
        # update
        if i < q:
            op, num = event_lines[i].split()
            num = int(num)
            if op == '+':
                cnt[num] = cnt.get(num, 0) + 1
            else:
                cnt[num] -= 1
                if cnt[num] == 0:
                    del cnt[num]


def test_event_order_independence_same_multiset(run, x):
    # create a copy of the input with events reordered among different lengths
    # but only if we have at least two events with different x
    parts = x.strip().split('\n')
    if len(parts) < 4:
        return  # not enough events
    n = int(parts[0])
    initial_line = parts[1]
    q = int(parts[2])
    event_lines = parts[3:]
    # group by x
    events_by_x = {}
    for line in event_lines:
        op, num = line.split()
        num = int(num)
        events_by_x.setdefault(num, []).append(line)
    if len(events_by_x) < 2:
        return  # cannot permute across lengths
    # flatten preserving order but swap two events of different x if possible
    # we'll just reverse the whole event list – that's a simple permutation
    reversed_events = list(reversed(event_lines))
    new_input = f"{n}\n{initial_line}\n{q}\n" + "\n".join(reversed_events)
    out1 = run(x).strip().split('\n')
    out2 = run(new_input).strip().split('\n')
    # final answer should be same because final multiset is same
    assert out1[-1] == out2[-1], f"final answer differs after reversing events: {out1[-1]} vs {out2[-1]}"


def test_adding_plank_does_not_turn_yes_to_no_unnecessarily(run, x):
    # This is actually NOT guaranteed by spec: adding a plank could break the condition? Actually yes, if you already have exactly enough for square+rectangle and adding a plank of a weird length might not help? Adding a plank never removes planks, so it can only increase counts, so it cannot make a possible configuration impossible. However, if the condition is "can pick four for square and four for rectangle", adding a plank cannot destroy existing selections, so a YES should stay YES. Wait but the rectangle may require two distinct lengths; if you had exactly two lengths each with count 2, and you add a plank of a third length, you still have the rectangle (still two lengths each with 2). So YES remains YES. So monotonicity holds: once YES, always YES after + events. Similarly, after - events, NO may become YES, but not vice versa? Actually removing can break. So we test monotonicity for + events.
    parts = x.strip().split('\n')
    n = int(parts[0])
    initial = list(map(int, parts[1].split())) if n > 0 else []
    events = parts[2:] if len(parts) > 2 else []
    q = int(events[0]) if events else 0
    event_lines = events[1:] if q > 0 else []
    # simulate only + events
    cnt = {}
    for v in initial:
        cnt[v] = cnt.get(v, 0) + 1
    outputs = run(x).strip().split('\n')
    for i in range(q+1):
        if i > 0 and event_lines[i-1][0] == '+':
            # previous event was addition
            if outputs[i-1].upper() == "YES":
                assert outputs[i].upper() == "YES", f"YES turned to NO after adding a plank at step {i}"
        # update for next
        if i < q:
            op, num = event_lines[i].split()
            num = int(num)
            if op == '+':
                cnt[num] = cnt.get(num, 0) + 1
            else:
                cnt[num] -= 1
                if cnt[num] == 0:
                    del cnt[num]


def test_remove_plank_does_not_turn_no_to_yes_unnecessarily(run, x):
    # Removing a plank cannot make a NO become YES? Actually it can: if you had many planks but not the right distribution, removing some might allow? No, removing reduces counts, so it cannot create a square or rectangle that wasn't possible before. So NO should stay NO after removal events. This is monotonicity in the other direction.
    parts = x.strip().split('\n')
    n = int(parts[0])
