def test_counts_non_negative(run, x):
    # The program's internal store must keep non‑negative counts.
    # We cannot inspect store directly, but we can infer from behavior: after a removal of x, the answer should be consistent with counts.
    # Instead, we just check that after each event, the answer is consistent with our own simulation (which ensures counts non‑negative).
    # That's essentially the certificate test; we'll do a full simulation and compare answers.
    parts = x.strip().split('\n')
    n = int(parts[0])
    initial = list(map(int, parts[1].split())) if n > 0 else []
    events = parts[2:] if len(parts) > 2 else []
    q = int(events[0]) if events else 0
    event_lines = events[1:] if q > 0 else []
    cnt = {}
    for v in initial:
        cnt[v] = cnt.get(v, 0) + 1
    outputs = run(x).strip().split('\n')
    for i in range(q+1):
        # compute correct answer from cnt
        # square possible: any length with >=4
        sq = any(c >= 4 for c in cnt.values())
        if sq:
            # rectangle possible from remaining?
            # find a square candidate, try all
            rect_possible = False
            for l, c in cnt.items():
                if c >= 4:
                    rem = dict(cnt)
                    rem[l] -= 4
                    # check rectangle in rem
                    if any(c2 >= 4 for c2 in rem.values()):
                        rect_possible = True
                        break
                    ge2 = [ll for ll, cc in rem.items() if cc >= 2]
                    if len(ge2) >= 2:
                        rect_possible = True
                        break
            correct = "YES" if rect_possible else "NO"
        else:
            # no square at all
            correct = "NO"
        if outputs[i].upper() != correct:
            raise AssertionError(f"Step {i}: expected {correct}, got {outputs[i]}, counts {cnt}")
        # update
        if i < q:
            op, num = event_lines[i].split()
            num = int(num)
            if op == '+':
                cnt[num] = cnt.get(num, 0) + 1
            else:
                cnt[num] -= 1
                if cnt[num] == 0:
                    del cnt[num]


def test_yes_requires_at_least_8_planks_total(run, x):
