def test_login_is_concatenation_of_prefixes(run, x):
    a, b = x.strip().split()
    out = run(x).strip()
    # out must be a[:i] + b[:j] for some i in [1, len(a)], j in [1, len(b)]
    ok = False
    for i in range(1, len(a)+1):
        for j in range(1, len(b)+1):
            if out == a[:i] + b[:j]:
                ok = True
                break
        if ok:
            break
    assert ok, f"{out} is not a valid prefix concatenation"

def test_lexicographically_earlier_than_any_prefix_pair(run, x):
    a, b = x.strip().split()
    out = run(x).strip()
    # Check that no valid login is lexicographically earlier than out
    for i in range(1, len(a)+1):
        for j in range(1, len(b)+1):
            cand = a[:i] + b[:j]
            if cand < out:
                assert False, f"{cand} is earlier than {out}"

def test_length_bounds(run, x):
    a, b = x.strip().split()
    out = run(x).strip()
    assert 2 <= len(out) <= len(a) + len(b), f"length {len(out)} out of bounds"

def test_starts_with_first_name_prefix(run, x):
    a, b = x.strip().split()
    out = run(x).strip()
    # out must start with a non‑empty prefix of a
