    assert ok, f"{out} does not start with a prefix of {a}"

def test_second_part_is_prefix_of_last_name(run, x):
    a, b = x.strip().split()
    out = run(x).strip()
    # Find the longest i such that out starts with a[:i]; then the rest must be a prefix of b
    for i in range(1, len(a)+1):
        if out.startswith(a[:i]):
            rest = out[len(a[:i]):]
            if rest == "":
                # rest empty means j=0, invalid because prefix must be non‑empty
                continue
            if rest == b[:len(rest)]:
                return
    assert False, f"{out} does not have second part as a prefix of {b}"

