def test_output_format(run, x):
    out = run(x).strip()
    assert out in ('>', '<', '='), f"Invalid output '{out}'"

def test_swap_inverts(run, x):
    lines = x.strip().split('\n')
    if len(lines) != 2:
        return  # malformed, but inputs given are well‑formed
    a, b = lines[0], lines[1]
    out1 = run(x).strip()
    out2 = run(b + '\n' + a).strip()
    if out1 == '>':
        assert out2 == '<', f"Swapping '>' should give '<', got '{out2}'"
    elif out1 == '<':
        assert out2 == '>', f"Swapping '<' should give '>', got '{out2}'"
    elif out1 == '=':
        assert out2 == '=', f"Swapping '=' should give '=', got '{out2}'"

def test_identical_strings_equal(run, x):
    lines = x.strip().split('\n')
    if len(lines) != 2:
        return
    a, b = lines[0], lines[1]
    if a == b:
        assert run(x).strip() == '=', f"Identical strings must be equal, got '{run(x).strip()}'"

def test_padding_zeros_no_change(run, x):
    lines = x.strip().split('\n')
    if len(lines) != 2:
        return
    a, b = lines[0], lines[1]
    n = max(len(a), len(b))
    a_pad = '0' * (n - len(a)) + a
    b_pad = '0' * (n - len(b)) + b
    out1 = run(x).strip()
    out2 = run(a_pad + '\n' + b_pad).strip()
    assert out1 == out2, f"Padding with leading zeros changed result: '{out1}' vs '{out2}'"

def test_small_strings_certificate(run, x):
    lines = x.strip().split('\n')
    if len(lines) != 2:
        return
    a, b = lines[0], lines[1]
    if len(a) <= 10 and len(b) <= 10:
        # compute value using high‑precision float (sufficient for small length)
        import math
        q = (math.sqrt(5) + 1) / 2
        def val(s):
            total = 0.0
            n = len(s)
            for i, ch in enumerate(s):
                total += int(ch) * (q ** (n - i - 1))
            return total
        v1 = val(a)
        v2 = val(b)
        expected = '>' if v1 > v2 else '<' if v1 < v2 else '='
        got = run(x).strip()
        assert got == expected, f"Certificate mismatch: got '{got}', expected '{expected}'"

def test_transitivity(run, x):
    lines = x.strip().split('\n')
    if len(lines) != 2:
        return
    a, b = lines[0], lines[1]
    # create a third string by flipping all bits of b (ensuring same length)
    c = ''.join('1' if ch == '0' else '0' for ch in b)
    out_ab = run(a + '\n' + b).strip()
    out_bc = run(b + '\n' + c).strip()
    out_ac = run(a + '\n' + c).strip()
    # transitivity: if a > b and b > c then a > c, similarly for <
    # we only check when both comparisons are strict
    if out_ab == '>' and out_bc == '>':
        assert out_ac == '>', f"Transitivity fails: a>b, b>c but a{c}? got '{out_ac}'"
    if out_ab == '<' and out_bc == '<':
        assert out_ac == '<', f"Transitivity fails: a<b, b<c but a{c}? got '{out_ac}'"
    # if a=b and b=c then a=c
    if out_ab == '=' and out_bc == '=':
        assert out_ac == '=', f"Transitivity fails: a=b, b=c but a!=c, got '{out_ac}'"

def test_sign_under_complement(run, x):
    lines = x.strip().split('\n')
    if len(lines) != 2:
        return
    a, b = lines[0], lines[1]
    # only apply when lengths equal and small enough to compute total value
    if len(a) == len(b) and len(a) <= 10:
        import math
        q = (math.sqrt(5) + 1) / 2
        def total_pow(s):
            # sum of q^{n-i-1} for all positions
            n = len(s)
            return sum(q ** (n - i - 1) for i in range(n))
        S = total_pow(a)  # same as total_pow(b) because lengths equal
        # value of complement = S - value(original) because each digit flips 0<->1
        def val(s):
            return sum(int(ch) * (q ** (len(s) - i - 1)) for i, ch in enumerate(s))
        v1 = val(a)
        v2 = val(b)
        # complement strings
        a_comp = ''.join('1' if ch == '0' else '0' for ch in a)
        b_comp = ''.join('1' if ch == '0' else '0' for ch in b)
        v1c = val(a_comp)
        v2c = val(b_comp)
        # check: v1c = S - v1, v2c = S - v2, so v1 > v2 implies v1c < v2c
        out_orig = run(x).strip()
        out_comp = run(a_comp + '\n' + b_comp).strip()
        if out_orig == '>':
            assert out_comp == '<', f"Complement should reverse '>', got '{out_comp}'"
        elif out_orig == '<':
            assert out_comp == '>', f"Complement should reverse '<', got '{out_comp}'"
        elif out_orig == '=':
            assert out_comp == '=', f"Complement should preserve '=', got '{out_comp}'"

def test_not_both_gt_and_lt(run, x):
    # trivial bound: answer cannot be both '>' and '<' (tautology)
    out = run(x).strip()
    # already covered by output format test, but keep as separate weak test
    assert out in ('>', '<', '='), f"Invalid output '{out}'"

def test_swap_preserves_equality(run, x):
    lines = x.strip().split('\n')
    if len(lines) != 2:
        return
    a, b = lines[0], lines[1]
    out = run(x).strip()
    if out == '=':
        swapped_out = run(b + '\n' + a).strip()
        assert swapped_out == '=', f"Equality not preserved under swap, got '{swapped_out}'"

def test_single_digit_difference(run, x):
    lines = x.strip().split('\n')
    if len(lines) != 2:
        return
    a, b = lines[0], lines[1]
    # only when strings are same length and differ in exactly one position
    if len(a) == len(b):
        diff_pos = [i for i in range(len(a)) if a[i] != b[i]]
        if len(diff_pos) == 1:
            i = diff_pos[0]
            # digit difference: a[i] - b[i] is +1 if a[i]=1,b[i]=0 else -1
            diff = int(a[i]) - int(b[i])
            out = run(x).strip()
            if diff > 0:
                assert out == '>', f"Single digit diff +1 should give '>', got '{out}'"
            elif diff < 0:
                assert out == '<', f"Single digit diff -1 should give '<', got '{out}'"
            else:
                assert out == '=', f"No diff should give '=', got '{out}'"

