                for k in range(n):
                    if k != i and a[k][j] == 1:
                        covered = True
                        break
                if not covered:
                    ok = False
                    break
            if ok:
                works = True
                break
        assert works, 'Output YES but no switch satisfies condition (cross-check)'
    # No further assertion for NO case"  
    }  
  ]  
}

