tests_src:
def test_output_is_yes_or_no(run, x):
    output = run(x).strip().upper()
    assert output in ("YES", "NO"), f"Output must be YES or NO, got {output}"

def test_append_vowel_preserves_yes(run, x):
    original_output = run(x).strip().upper()
    if original_output == "YES":
        new_input = x.strip() + "a\n"
        new_output = run(new_input).strip().upper()
        assert new_output == "YES", f"Appending vowel changed YES to NO on {x.strip()}"

def test_prepend_n_preserves_yes(run, x):
    original_output = run(x).strip().upper()
    if original_output == "YES":
        new_input = "n" + x.strip() + "\n"
        new_output = run(new_input).strip().upper()
        assert new_output == "YES", f"Prepending 'n' changed YES to NO on {x.strip()}"

def test_yes_implies_all_consonants_followed_by_vowel(run, x):
    output = run(x).strip().upper()
    if output == "YES":
        s = x.strip()
        vowels = set("aouie")
        for i, ch in enumerate(s):
            if ch not in vowels and ch != 'n':
                if i + 1 >= len(s) or s[i + 1] not in vowels:
                    raise AssertionError(f"YES output but consonant {ch} at {i} not followed by vowel in {s}")

def test_no_implies_some_consonant_violation(run, x):
    output = run(x).strip().upper()
    if output == "NO":
        s = x.strip()
        vowels = set("aouie")
        violation_exists = False
        for i, ch in enumerate(s):
            if ch not in vowels and ch != 'n':
                if i + 1 >= len(s) or s[i + 1] not in vowels:
                    violation_exists = True
                    break
        if not violation_exists:
            raise AssertionError(f"NO output but no consonant violation found in {s}")

def test_output_is_uppercase(run, x):
    output = run(x).strip()
    assert output == output.upper(), f"Output should be uppercase, got {output}"

def test_duplicate_string_preserves_yes(run, x):
    original_output = run(x).strip().upper()
    if original_output == "YES":
        s = x.strip()
        new_input = s + s + "\n"
        new_output = run(new_input).strip().upper()
        assert new_output == "YES", f"Duplicating string changed YES to NO on {s}"

def test_remove_last_char_weak(run, x):
    s = x.strip()
    if len(s) > 1:
        original_output = run(x).strip().upper()
        new_input = s[:-1] + "\n"
        new_output = run(new_input).strip().upper()
        vowels = set("aouie")
        last_char = s[-1]
        second_last = s[-2] if len(s) >= 2 else None
        # If original is YES and removing last char does not create a trailing violation, it should stay YES
        if original_output == "YES" and second_last is not None:
            if second_last not in vowels and second_last != 'n' and last_char in vowels:
                # The last char was a vowel that satisfied the second_last consonant.
                # After removal, second_last might be at end and not 'n' => violation.
                # So we don't assert.
                pass
            else:
                # Otherwise, removal should not create a new violation, so should stay YES.
                assert new_output == "YES", f"Removing last char changed YES to NO on {s}"

def test_output_length(run, x):
    output = run(x).strip()
    assert len(output) in (2, 3, 4), f"Output length unexpected: {len(output)}"  # 'YES', 'NO', plus optional newline stripped

def test_ending_with_non_n_consonant_implies_no(run, x):
    s = x.strip()
    vowels = set("aouie")
    if s and s[-1] not in vowels and s[-1] != 'n':
        output = run(x).strip().upper()
        assert output == "NO", f"String ends with non-n consonant {s[-1]}, must output NO, got {output}"

