tests_src:
def test_output_is_positive_integer(run, x):
    out = run(x).strip()
    assert out.isdigit() and int(out) > 0

def test_output_divides_n(run, x):
    n = int(x.strip())
    out = int(run(x).strip())
    assert n % out == 0

def test_output_is_prime(run, x):
    out = int(run(x).strip())
    if out == 1:
        return  # 1 is not prime, but allowed as answer
    i = 2
    while i * i <= out:
        if out % i == 0:
            assert False, f"output {out} is not prime"
        i += 1

def test_output_is_smallest_prime_divisor(run, x):
    n = int(x.strip())
    out = int(run(x).strip())
    # find smallest prime divisor of n
    if n == 1:
        assert out == 1
        return
    i = 2
    while i * i <= n:
        if n % i == 0:
            # i is the smallest prime divisor
            assert out == i, f"expected smallest prime divisor {i}, got {out}"
            return
        i += 1
    # n is prime
    assert out == n, f"n is prime, expected {n}, got {out}"

def test_output_leq_n(run, x):
    n = int(x.strip())
    out = int(run(x).strip())
    assert out <= n

def test_output_geq_1(run, x):
    out = int(run(x).strip())
    assert out >= 1

def test_for_small_n_check_coloring(run, x):
    n = int(x.strip())
    if n > 1000:  # skip large n
        return
    out = int(run(x).strip())
    # simulate coloring with period out: color[i] = i % out
    # check condition: for any i,j with |i-j|>1 and n % |i-j| == 0, colors must be same
    ok = True
    for i in range(1, n+1):
        for j in range(i+1, n+1):
            d = j - i
            if d > 1 and n % d == 0:
                if (i-1) % out != (j-1) % out:
                    ok = False
                    break
        if not ok:
            break
    assert ok, f"coloring with period {out} fails for n={n}"

def test_output_less_than_or_equal_to_every_prime_divisor(run, x):
    n = int(x.strip())
    out = int(run(x).strip())
    # collect all prime divisors of n
    temp = n
    p = 2
    while p * p <= temp:
        if temp % p == 0:
            assert out <= p, f"output {out} greater than prime divisor {p}"
            while temp % p == 0:
                temp //= p
        p += 1 if p == 2 else 2  # simple increment, but fine
    if temp > 1:
        assert out <= temp, f"output {out} greater than prime divisor {temp}"

def test_for_prime_n_output_equals_n(run, x):
    n = int(x.strip())
    # check if n is prime
    if n == 1:
        return
    i = 2
    while i * i <= n:
        if n % i == 0:
            return  # n is composite, skip
        i += 1
    out = int(run(x).strip())
    assert out == n, f"n is prime {n}, expected {n}, got {out}"

def test_for_prime_power_output_is_prime(run, x):
    n = int(x.strip())
    # factor n into prime power
    # find smallest prime divisor p, then check if n is power of p
    if n == 1:
        assert int(run(x).strip()) == 1
        return
    p = 2
    while p * p <= n:
        if n % p == 0:
            break
        p += 1
    if p * p > n:
        p = n
    # check if n is power of p
    temp = n
    while temp % p == 0:
        temp //= p
    if temp == 1:
        # n is a power of p
        out = int(run(x).strip())
        assert out == p, f"n={n} is power of prime {p}, expected {p}, got {out}"
    # else not a prime power, no constraint

