        v = val - 1
        while v:
            cnt += 1
            v //= 7
        return cnt
    n_str, m_str = x.strip().split()
    n = int(n_str)
    m = int(m_str)
    a = digits_needed(n)
    b = digits_needed(m)
    ans = int(run(x).strip())
    if a + b > 7:
        assert ans == 0, f'a+b={a+b}>7 but answer {ans} != 0'


