def test_small_exhaustive_for_tiny_inputs(run, x):
    n_str, m_str = x.strip().split()
    n = int(n_str)
    m = int(m_str)
    if n > 20 or m > 20:
        return  # skip large cases
    # brute force correct answer
    def len7(x):
        if x <= 1:
            return 1
        cnt = 0
        v = x - 1
        while v:
            cnt += 1
            v //= 7
        return cnt
    a = len7(n)
    b = len7(m)
    if a + b > 7:
        expected = 0
    else:
        from itertools import permutations
        expected = 0
        for perm in permutations(range(7), a + b):
            hour = 0
            for d in perm[:a]:
                hour = hour * 7 + d
            minute = 0
            for d in perm[a:]:
                minute = minute * 7 + d
            if hour < n and minute < m:
                expected += 1
    ans = int(run(x).strip())
    assert ans == expected, f'For small case expected {expected}, got {ans}'


