def test_output_is_integer(run, x):
    out = run(x).strip()
    assert out.isdigit() or (out.startswith('-') and out[1:].isdigit()), 'Output must be an integer'

def test_answer_positive(run, x):
    out = int(run(x).strip())
    assert out > 0, 'Answer must be positive'

def test_answer_not_exceed_n(run, x):
    n = int(x.strip())
    ans = int(run(x).strip())
    assert 1 <= ans <= n, 'Answer must be between 1 and n inclusive'

def test_answer_divides_n_or_is_1(run, x):
    n = int(x.strip())
    ans = int(run(x).strip())
    assert ans == 1 or n % ans == 0, 'Answer must be 1 or divide n'

def test_prime_power_exponent_not_multiple_12(run, x):
    n = int(x.strip())
    ans = int(run(x).strip())
    # Check if n is a prime power with exponent not divisible by 12
    # Find smallest prime divisor
    p = 2
    while p * p <= n and n % p != 0:
        p += 1
    if p * p > n:
        p = n
    # Determine exponent
    temp = n
    exp = 0
    while temp % p == 0:
        temp //= p
        exp += 1
    if temp == 1 and exp % 12 != 0:
        # n is p^exp with exp not divisible by 12
        assert ans == p, f'For prime power {n}={p}^{exp} with exp%12≠0, answer should be {p}'

def test_non_prime_power_gives_1(run, x):
    n = int(x.strip())
    ans = int(run(x).strip())
    # Determine if n is a prime power
    p = 2
    while p * p <= n and n % p != 0:
        p += 1
    if p * p > n:
        p = n
    temp = n
    while temp % p == 0:
        temp //= p
    if temp != 1:
        # n has more than one prime factor
        assert ans == 1, f'For composite with multiple primes, answer should be 1'

def test_prime_input(run, x):
    n = int(x.strip())
    ans = int(run(x).strip())
    # Check if n is prime
    if n < 2:
        return
    p = 2
    while p * p <= n and n % p != 0:
        p += 1
    if p * p > n:
        # n is prime
        assert ans == n, f'For prime n={n}, answer should be n'

def test_square_of_prime_exponent_2(run, x):
    n = int(x.strip())
    ans = int(run(x).strip())
    # Check if n = p^2 for prime p
    p = 2
    while p * p <= n and n % p != 0:
        p += 1
    if p * p <= n:
        # p is smallest prime divisor
        if n == p * p:
            # n = p^2, exponent 2 is not divisible by 12
            assert ans == p, f'For n=p^2={n}, answer should be p={p}'

def test_perfect_power_exponent_multiple_12(run, x):
    n = int(x.strip())
    ans = int(run(x).strip())
    # Check if n = p^k where 12 divides k
    # Try all possible exponents from 2 up to log2(n)
    import math
    max_exp = int(math.log2(n)) + 1
    for exp in range(2, max_exp + 1):
        if exp % 12 == 0:
            # Try to find integer p such that p^exp == n
            p = int(round(n ** (1.0 / exp)))
            if pow(p, exp) == n:
                # Check if p is prime
                is_prime = True
                if p < 2:
                    is_prime = False
                else:
                    d = 2
                    while d * d <= p and p % d != 0:
                        d += 1
                    if d * d <= p:
                        is_prime = False
                if is_prime:
                    assert ans == 1, f'For n={n}=prime^{exp} with 12|{exp}, answer should be 1'

def test_metamorphic_same_for_n_and_2n_when_n_odd(run, x):
    n = int(x.strip())
    if n % 2 == 1:
        ans1 = int(run(x).strip())
        # Create input for 2n
        input2 = f'{2*n}\n'
        ans2 = int(run(input2).strip())
        # For odd n, the answer should be the same as for 2n because the prime factors are the same
        # This is a property derived from the specification: the answer depends only on the prime factorization
        assert ans1 == ans2, f'For odd n={n} and 2n={2*n}, answers should match'

def test_examples(run, x):
    n = int(x.strip())
    out = run(x).strip()
    if n == 1:
        assert out == "0"
    elif n == 2:
        assert out == "0"
    elif n == 10:
        assert out == "4"

def test_small_brute(run, x):
    n = int(x.strip())
    if n > 100:
        return  # skip large n
    # compute MST weight via Kruskal
    edges = []
    for i in range(1, n+1):
        for j in range(i+1, n+1):
            w = (i + j) % (n + 1)
            edges.append((w, i, j))
    edges.sort()
    parent = list(range(n+1))
    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u
    def union(u, v):
        ru, rv = find(u), find(v)
        if ru != rv:
            parent[rv] = ru
            return True
        return False
    total = 0
    cnt = 0
    for w, i, j in edges:
        if union(i, j):
            total += w
            cnt += 1
            if cnt == n-1:
                break
    out = int(run(x).strip())
    assert out == total

def test_upper_bound_construction(run, x):
    n = int(x.strip())
    # compute cost of connecting all vertices to vertex 1
    total = 0
    for j in range(2, n+1):
        total += (1 + j) % (n + 1)
    out = int(run(x).strip())
    assert out <= total

def test_nonnegative(run, x):
    out = int(run(x).strip())
    assert out >= 0

def test_integer(run, x):
    out = run(x).strip()
    # check it's an integer
    try:
        int(out)
    except ValueError:
        assert False, "output must be an integer"

def test_upper_bound_n2(run, x):
    n = int(x.strip())
    out = int(run(x).strip())
    # each edge weight <= n, at most n-1 edges
    assert out <= n * (n - 1)

def test_lower_bound_zero(run, x):
    out = int(run(x).strip())
    assert out >= 0  # redundant with nonnegative, but keep

def test_connectivity_certificate(run, x):
    n = int(x.strip())
    c = int(run(x).strip())
    if c > 1000 or n > 10000:
        return  # skip if output too large or n too large for safety
    # check that graph with edges of weight <= c is connected
    parent = list(range(n+1))
    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u
    def union(u, v):
        ru, rv = find(u), find(v)
        if ru != rv:
            parent[rv] = ru
            return True
        return False
    components = n
    for w in range(c+1):
        for i in range(1, n+1):
            j = (w - i) % (n + 1)
            if 1 <= j <= n and i < j:
                if union(i, j):
                    components -= 1
                    if components == 1:
                        return  # connected
    # if we finish loop and not connected, assert false
    assert components == 1, f"graph with edge weights <={c} is not connected"

def test_parity_consistency(run, x):
    # This is a weak property: the answer parity might match (n-1)//2 parity?
    # Actually, we cannot assume. Instead, we test that answer has same parity as
    # the sum of edge weights of any spanning tree mod 2? Hard.
    # We'll skip this and replace with a simpler bound: answer <= n-1? Not true.
    # Let's test that answer <= (n-1) * n // 2? That's weaker than n*(n-1).
    # We'll do that.
    n = int(x.strip())
    out = int(run(x).strip())
    # maximum possible sum of n-1 edges, each at most n, is (n-1)*n.
    # but we can have a slightly tighter bound: the maximum edge weight is n,
    # but there are only n edges of weight n? Actually, number of edges of weight n is floor(n/2).
    # However, we keep simple bound.
    assert out <= n * (n - 1)

def test_output_format(run, x):
    out = run(x).strip()
    # must be a single integer, possibly with whitespace
    assert out.strip().isdigit() or (out[0]=='-' and out[1:].isdigit()), "output must be an integer"
    # but cost is non-negative, so no negative sign
    if out.strip().startswith('-'):
        assert False, "negative output"

