def test_non_negative(run, x):
    out = run(x)
    ans = int(out.strip())
    assert ans >= 0

def test_formula_match(run, x):
    N = int(x.strip())
    expected = 0
    for i in range(1, N):
        expected += (N - 1) // i
    out = run(x)
    ans = int(out.strip())
    assert ans == expected

def test_positive_for_N_ge_2(run, x):
    N = int(x.strip())
    if N >= 2:
        out = run(x)
        ans = int(out.strip())
        assert ans > 0

def test_monotonic_non_decreasing(run, x):
    # This test is tricky because it needs two runs.
    # We can only run on the given input, not on arbitrary N.
    # So we cannot test monotonicity across the whole set.
    # Instead we can check a local property: answer for N <= answer for N+1? Not possible without N+1 input.
    # So replace with a bound: answer <= (N-1)^2 (loose upper bound).
    N = int(x.strip())
    out = run(x)
    ans = int(out.strip())
    assert ans <= (N - 1) ** 2

def test_certificate_small_N(run, x):
    N = int(x.strip())
    if N <= 1000:
        out = run(x)
        ans = int(out.strip())
        count = 0
        for A in range(1, N):
            for B in range(1, (N - 1) // A + 1):
                # A*B < N, C = N - A*B
                count += 1
        assert ans == count

def test_upper_bound_N_squared(run, x):
    N = int(x.strip())
    out = run(x)
    ans = int(out.strip())
    # A and B can each be up to N-1, so at most (N-1)^2 possibilities.
    assert ans <= (N - 1) ** 2

def test_integer_output(run, x):
    out = run(x)
    s = out.strip()
    # Check it's an integer.
    int(s)
    # No further assertion needed; if int() fails, test fails.

def test_no_subtraction_for_primes_over_1000(run, x):
    N = int(x.strip())
    # Define a simple primality check (same as in the code).
    def is_prime(n):
        if n < 2:
            return False
        if n == 2 or n == 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True
    if N > 1000 and is_prime(N):
        out = run(x)
        ans = int(out.strip())
        expected = 0
        for i in range(1, N):
            expected += (N - 1) // i
        assert ans == expected

def test_no_subtraction_for_composites_over_1000(run, x):
    N = int(x.strip())
    def is_prime(n):
        if n < 2:
            return False
        if n == 2 or n == 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True
    if N > 1000 and not is_prime(N):
        out = run(x)
        ans = int(out.strip())
        expected = 0
        for i in range(1, N):
            expected += (N - 1) // i
        assert ans == expected

def test_lower_bound_N_minus_1(run, x):
    N = int(x.strip())
    # At least N-1 triples: (1,1,N-1), (1,2,N-2), ..., (1,N-1,1)? Actually for A=1, B can be 1..N-1 giving N-1 triples.
    out = run(x)
    ans = int(out.strip())
    assert ans >= N - 1

