    assert ans == prod, f'Expected product of distinct primes {prod}, got {ans}'

def test_small_case_consistency(run, x):
    n = int(x.strip())
    if n <= 1000:
        # brute force to compute maximal lovely divisor
        best = 1
        for d in range(1, n+1):
            if n % d == 0:
                lovely = True
                for a in range(2, int(d**0.5)+1):
                    if d % (a*a) == 0:
                        lovely = False
                        break
                if lovely and d > best:
                    best = d
        ans = int(run(x).strip())
        assert ans == best, f'For small n={n}, expected {best}, got {ans}'

def test_no_larger_lovely(run, x):
    n = int(x.strip())
    ans = int(run(x).strip())
    # check there is no lovely divisor > ans.
    # but we cannot iterate all divisors for large n. We'll only do it for n <= 1000.
    if n <= 1000:
        for d in range(ans+1, n+1):
            if n % d == 0:
                lovely = True
                for a in range(2, int(d**0.5)+1):
                    if d % (a*a) == 0:
                        lovely = False
                        break
                if lovely:
                    assert False, f'Found larger lovely divisor {d} > {ans}'

