def test_nonzero_combination(run, x):
    output = run(x).strip()
    if output == "Yes":
        N = int(x.strip())
        # The specification requires buying 'some of them', meaning at least one item.
        # The sample says 'you can buy zero doughnuts or zero cakes' but then total zero is not allowed.
        # Actually the problem says: 'Determine if there is a way to buy some of them for exactly N dollars.'
        # 'some of them' implies at least one item, and also 'two or more doughnuts and two or more cakes' is optional.
        # So at least one cake or one doughnut.
        found = False
        for i in range(N // 4 + 1):
            for j in range(N // 7 + 1):
                if 4 * i + 7 * j == N and (i > 0 or j > 0):
                    found = True
                    break
            if found:
                break
        assert found, f"Output is 'Yes' but no non‑zero combination found for N={N}"

