def test_1(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    val = int(out)
    # product of two numbers between 1 and 20 is at most 400
    assert 1 <= val <= 400, f'product {val} out of range'

def test_2(run, x):
    out = run(x).strip()
    # output must be a valid integer
    try:
        int(out)
    except ValueError:
        assert False, 'output not an integer'

def test_3(run, x):
    # if output is not -1, it must equal A*B
    out = run(x).strip()
    if out == '-1':
        return
    a, b = map(int, x.strip().split())
    assert int(out) == a * b, f'output {out} not equal to product {a*b}'

def test_4(run, x):
    # swapping A and B must give same answer (commutativity of multiplication)
    a, b = map(int, x.strip().split())
    swapped = f'{b} {a}\n'
    out1 = run(x).strip()
    out2 = run(swapped).strip()
    assert out1 == out2, f'answers differ on swap: {out1} vs {out2}'

def test_5(run, x):
    # if both numbers are between 1 and 9, answer must not be -1
    a, b = map(int, x.strip().split())
    if 1 <= a <= 9 and 1 <= b <= 9:
        out = run(x).strip()
        assert out != '-1', f'both ≤9 but output -1'

def test_6(run, x):
    # if either number > 9, answer must be -1
    a, b = map(int, x.strip().split())
    if a > 9 or b > 9:
        out = run(x).strip()
        assert out == '-1', f'one >9 but output {out} not -1'

def test_7(run, x):
    # if both ≤9, output must equal product
    a, b = map(int, x.strip().split())
    if 1 <= a <= 9 and 1 <= b <= 9:
        out = run(x).strip()
        assert int(out) == a * b, f'both ≤9 but output {out} not product {a*b}'

def test_8(run, x):
    # if both ≤9, even when a+b==16, output should be product
    a, b = map(int, x.strip().split())
    if 1 <= a <= 9 and 1 <= b <= 9:
        out = run(x).strip()
        # spec says he can multiply; no exception for sum 16
        assert int(out) == a * b, f'sum 16 case failed'

def test_9(run, x):
    # output must not be negative except -1
    out = run(x).strip()
    if out != '-1':
        val = int(out)
        assert val > 0, f'output {val} is non-positive'

def test_10(run, x):
    # metamorphic: if both ≤9, scaling one factor doubles product
    a, b = map(int, x.strip().split())
    if 1 <= a <= 9 and 1 <= b <= 9 and 2*a <= 9:
        orig_out = run(x).strip()
        scaled_input = f'{2*a} {b}\n'
        scaled_out = run(scaled_input).strip()
        # if original is product, scaled should be double
        if orig_out != '-1' and scaled_out != '-1':
            assert int(scaled_out) == 2 * int(orig_out), f'scaling violated'

def test_output_is_integer(run, x):
    out = run(x).strip()
    # Must be an integer string, no decimal point, no spaces
    assert out.lstrip('-').isdigit(), f'Output "{out}" is not an integer'

def test_output_nonnegative(run, x):
    out = run(x).strip()
    val = int(out)
    assert val >= 0, f'Output {val} is negative'

def test_monotonic(run, x):
    r = int(x.strip())
    if r < 100:
        out1 = int(run(x).strip())
        out2 = int(run(str(r+1)+'\n').strip())
        assert out2 >= out1, f'Output decreased from {out1} to {out2} when r increased from {r} to {r+1}'

def test_scaling_relation(run, x):
    r = int(x.strip())
    if 2*r <= 100:
        out_r = int(run(x).strip())
        out_2r = int(run(str(2*r)+'\n').strip())
        assert out_2r == 4 * out_r, f'Scaling relation fails: {out_2r} != 4 * {out_r}'

def test_r1_is_1(run, x):
    r = int(x.strip())
    if r == 1:
        out = int(run(x).strip())
        assert out == 1, f'For r=1 output must be 1, got {out}'

def test_output_is_perfect_square(run, x):
    out = int(run(x).strip())
    s = int(out ** 0.5 + 0.5)
    assert s * s == out, f'Output {out} is not a perfect square'

def test_sqrt_equals_input(run, x):
    r = int(x.strip())
    out = int(run(x).strip())
    s = int(out ** 0.5 + 0.5)
    assert s == r, f'Square root of output {out} is {s}, not input {r}'

def test_quadratic_growth(run, x):
    r = int(x.strip())
    if r < 100:
        out_r = int(run(x).strip())
        out_rp1 = int(run(str(r+1)+'\n').strip())
        expected = out_r + 2*r + 1
        assert out_rp1 == expected, f'Growth relation fails: {out_rp1} != {out_r} + 2*{r} + 1'

def test_parity_matches(run, x):
    r = int(x.strip())
    out = int(run(x).strip())
    assert out % 2 == r % 2, f'Parity mismatch: output {out} mod 2 != {r} mod 2'

def test_divisibility_properties(run, x):
    r = int(x.strip())
    out = int(run(x).strip())
    if r % 2 == 0:
        assert out % 4 == 0, f'For even r={r}, output {out} not divisible by 4'
    else:
        assert out % 8 == 1, f'For odd r={r}, output {out} mod 8 != 1'

