def test_consistency(run, x):
    s = x.rstrip('\n')
    out = run(x).rstrip('\n')
    # correct conditions
    def is_correct(t):
        if len(t) < 4 or len(t) > 10:
            return False
        if t[0] != 'A':
            return False
        slice_chars = t[2:len(t)-1]
        if slice_chars.count('C') != 1:
            return False
        c_idx = slice_chars.find('C') + 2
        for i,ch in enumerate(t):
            if i == 0 or i == c_idx:
                if not ch.isupper():
                    return False
            else:
                if not ch.islower():
                    return False
        return True
    assert (out == 'AC') == is_correct(s)

