    if out == 'AC':
        slice_chars = s[2:len(s)-1]
        c_idx_slice = slice_chars.find('C')
        c_idx = c_idx_slice + 2 if c_idx_slice != -1 else -1
        for i,ch in enumerate(s):
            if i == 0 or i == c_idx:
                continue
            assert ch.islower()

