def test_output_is_safe_or_unsafe(run, x):
    out = run(x).strip()
    assert out in ('safe', 'unsafe'), f'Output must be safe or unsafe, got {out}'

def test_output_length(run, x):
    out = run(x).strip()
    assert len(out) in (4, 6), f'Output length must be 4 (safe) or 6 (unsafe), got {len(out)}'

def test_if_safe_then_s_gt_w(run, x):
    # If output is safe, then S > W must hold (specification).
    S, W = map(int, x.strip().split())
    out = run(x).strip()
    if out == 'safe':
        assert S > W, f'Output safe but S={S} <= W={W}'

def test_if_unsafe_then_w_ge_s(run, x):
    # If output is unsafe, then W >= S must hold.
    S, W = map(int, x.strip().split())
    out = run(x).strip()
    if out == 'unsafe':
        assert W >= S, f'Output unsafe but W={W} < S={S}'

def test_swap_metamorphic(run, x):
    # If we swap S and W, answer should flip unless S == W.
    S, W = map(int, x.strip().split())
    out1 = run(x).strip()
    swapped_input = f'{W} {S}\n'
    out2 = run(swapped_input).strip()
    if S == W:
        assert out1 == out2 == 'unsafe', f'Equal S,W must be unsafe, got {out1}, {out2}'
    else:
        # Since S>W => safe, W>S => unsafe, swapping flips.
        if out1 == 'safe':
            assert out2 == 'unsafe', f'Swapped should be unsafe, got {out2}'
        else:
            assert out2 == 'safe', f'Swapped should be safe, got {out2}'

def test_add_one_wolf_preserves_unsafe(run, x):
    # If original answer is unsafe, adding one wolf should keep unsafe.
    S, W = map(int, x.strip().split())
    if W < 100:  # still within constraint
        out1 = run(x).strip()
        new_input = f'{S} {W+1}\n'
        out2 = run(new_input).strip()
        if out1 == 'unsafe':
            assert out2 == 'unsafe', f'Adding wolf changed unsafe to safe'

def test_remove_one_sheep_preserves_unsafe(run, x):
    # If original answer is unsafe, removing one sheep (if S>1) should keep unsafe.
    S, W = map(int, x.strip().split())
    if S > 1:
        out1 = run(x).strip()
        new_input = f'{S-1} {W}\n'
        out2 = run(new_input).strip()
        if out1 == 'unsafe':
            assert out2 == 'unsafe', f'Removing sheep changed unsafe to safe'

def test_monotonicity_wolf_increase(run, x):
    # Increasing wolves cannot change safe to safe if crossing S boundary?
    # Actually spec: only comparison matters. If S > W and we increase W, once W >= S answer becomes unsafe.
    # So safe can become unsafe, but unsafe cannot become safe.
    # So we check: if answer unsafe, then increasing W still unsafe.
    S, W = map(int, x.strip().split())
    if W < 100:
        out1 = run(x).strip()
        out2 = run(f'{S} {W+1}\n').strip()
        if out1 == 'unsafe':
            assert out2 == 'unsafe', f'Increasing wolves changed unsafe to safe'

def test_monotonicity_sheep_decrease(run, x):
    # Decreasing sheep cannot change safe to safe? Actually safe can become unsafe if S drops to <= W.
    # So we only check: if unsafe, decreasing S (if S>1) stays unsafe.
    S, W = map(int, x.strip().split())
    if S > 1:
        out1 = run(x).strip()
        out2 = run(f'{S-1} {W}\n').strip()
        if out1 == 'unsafe':
            assert out2 == 'unsafe', f'Decreasing sheep changed unsafe to safe'

def test_certificate_verify(run, x):
    # Verify the answer against the rule directly? That would require knowing correct.
    # Instead: check that if output safe, then S > W; if unsafe, then W >= S.
    # This is a certificate: we can check the condition from the output.
    S, W = map(int, x.strip().split())
    out = run(x).strip()
    if out == 'safe':
        assert S > W, f'safe but S={S} <= W={W}'
    else:
        assert W >= S, f'unsafe but W={W} < S={S}'

