def test_output_format(run, x):
    out = run(x)
    assert out in ('Good\n', 'Bad\n'), f'Output must be exactly Good or Bad followed by newline, got {repr(out)}'

def test_no_extra_output(run, x):
    out = run(x)
    assert out.strip() in ('Good', 'Bad'), f'Output must be Good or Bad without extra whitespace, got {repr(out)}'

def test_bad_on_all_same(run, x):
    s = x.strip()
    if len(s) == 4 and s[0] == s[1] == s[2] == s[3]:
        assert run(x) == 'Bad\n', f'All digits same {s} must be Bad'

def test_good_on_all_different(run, x):
    s = x.strip()
    if len(s) == 4 and len(set(s)) == 4:
        assert run(x) == 'Good\n', f'All digits distinct {s} must be Good'

def test_bad_on_first_two_equal(run, x):
    s = x.strip()
    if len(s) == 4 and s[0] == s[1]:
        assert run(x) == 'Bad\n', f'First two digits equal {s} must be Bad'

def test_bad_on_last_two_equal(run, x):
    s = x.strip()
    if len(s) == 4 and s[2] == s[3]:
        assert run(x) == 'Bad\n', f'Last two digits equal {s} must be Bad'

def test_metamorphic_swap(run, x):
    s = x.strip()
    if len(s) == 4:
        swapped = s[2] + s[3] + s[0] + s[1]
        out1 = run(x).strip()
        out2 = run(swapped + '\n').strip()
        assert out1 == out2, f'Swapping first/last pairs must preserve answer: {s} -> {out1}, {swapped} -> {out2}'

def test_metamorphic_reverse(run, x):
    s = x.strip()
    if len(s) == 4:
        rev = s[::-1]
        out1 = run(x).strip()
        out2 = run(rev + '\n').strip()
        assert out1 == out2, f'Reversing must preserve answer: {s} -> {out1}, {rev} -> {out2}'

def test_certificate_check(run, x):
    s = x.strip()
    out = run(x).strip()
    has_eq = any(s[i] == s[i+1] for i in range(3))
    if out == 'Bad':
        assert has_eq, f'Output Bad but no consecutive equal digits in {s}'
    elif out == 'Good':
        assert not has_eq, f'Output Good but consecutive equal digits found in {s}'
    else:
        assert False, f'Invalid output {out}'

def test_metamorphic_shift_cyclic(run, x):
    s = x.strip()
    if len(s) == 4:
        shifted = s[1] + s[2] + s[3] + s[0]
        out1 = run(x).strip()
        out2 = run(shifted + '\n').strip()
        assert out1 == out2, f'Cyclic shift must preserve answer: {s} -> {out1}, {shifted} -> {out2}'

