def test_output_is_integer(run, x):
    out = run(x).strip()
    # Ensure it can be parsed as int
    try:
        int(out)
    except ValueError:
        assert False, f"Output '{out}' is not an integer"

def test_output_positive(run, x):
    out = run(x).strip()
    try:
        val = int(out)
    except ValueError:
        return  # invalid output, will be caught elsewhere
    # According to spec, P,Q,R >=1, so minimum sum >=2
    # But we just assert >0
    assert val > 0, f"Output {val} not positive"

def test_output_at_least_two(run, x):
    # Only if input is valid (three positive ints)
    parts = x.strip().split()
    if len(parts) != 3:
        return
    try:
        a,b,c = map(int, parts)
    except ValueError:
        return
    out = run(x).strip()
    try:
        val = int(out)
    except ValueError:
        return
    # Since each >=1, smallest two sum >=2
    assert val >= 2, f"Output {val} < 2"

def test_output_at_most_200(run, x):
    out = run(x).strip()
    try:
        val = int(out)
    except ValueError:
        return
    # Max sum of two numbers each <=100 is 200
    assert val <= 200, f"Output {val} > 200"

def test_metamorphic_swap_PQ(run, x):
    parts = x.strip().split()
    if len(parts) != 3:
        return
    try:
        a,b,c = map(int, parts)
    except ValueError:
        return
    swapped = f"{b} {a} {c}"
    out1 = run(x).strip()
    out2 = run(swapped).strip()
    try:
        v1 = int(out1)
