    out = run(x)
    assert out.strip() == out.rstrip('\n'), f'Extra whitespace after output: {out!r}'

def test_metamorphic_swap(run, x):
    # Parse input
    parts = x.strip().split()
    if len(parts) != 2:
        # Some inputs have extra spaces/tabs, but we assume they represent two ints
        # Use split without arguments to handle any whitespace
        parts = x.strip().split()
        if len(parts) != 2:
            # If still not two, cannot apply this test; skip
            return
    X_str, A_str = parts[0], parts[1]
    try:
        X = int(X_str)
        A = int(A_str)
    except ValueError:
        # If parsing fails, input is invalid; skip
        return
    # Create swapped input
    swapped = f'{A} {X}\n'
    out_original = run(x).strip()
    out_swapped = run(swapped).strip()
    # If X == A, both outputs must be 10
    if X == A:
        assert out_original == '10' and out_swapped == '10', f'When X==A, both outputs must be 10, got {out_original} and {out_swapped}'
    else:
        # Exactly one of X<A and A<X is true, so outputs must be opposite
        assert (out_original == '0' and out_swapped == '10') or (out_original == '10' and out_swapped == '0'), f'Swapped inputs must flip output, got {out_original} and {out_swapped}'

def test_certificate_condition(run, x):
    parts = x.strip().split()
    if len(parts) != 2:
        parts = x.strip().split()
        if len(parts) != 2:
            return
    X_str, A_str = parts[0], parts[1]
    try:
        X = int(X_str)
        A = int(A_str)
    except ValueError:
        return
    out = run(x).strip()
    if out == '0':
        assert X < A, f'Output 0 but X={X} is not < A={A}'
    elif out == '10':
        assert X >= A, f'Output 10 but X={X} is not >= A={A}'
    else:
        raise AssertionError(f'Invalid output {out!r}')

def test_output_is_not_empty(run, x):
    out = run(x).strip()
    assert out != '', 'Output must not be empty'

def test_output_is_numeric(run, x):
    out = run(x).strip()
    assert out.isdigit(), f'Output must be digits only, got {out!r}'

def test_metamorphic_equal_values(run, x):
    # For any input, if we set X = A (using A from input), output must be 10
    parts = x.strip().split()
    if len(parts) != 2:
        parts = x.strip().split()
        if len(parts) != 2:
            return
    _, A_str = parts[0], parts[1]
