    N = int(x.strip())
    ones = N % 10
    tens = (N // 10) % 10
    if ones == 3 and tens != 1:
        out = run(x).strip()
        assert out == 'bon', f'For N={N} (ones=3, tens={tens}) expected bon, got {out}'


def test_ones_0168_tens_not_1_is_pon(run, x):
    N = int(x.strip())
    ones = N % 10
    tens = (N // 10) % 10
    if ones in {0,1,6,8} and tens != 1:
        out = run(x).strip()
        assert out == 'pon', f'For N={N} (ones={ones}, tens={tens}) expected pon, got {out}'


def test_ones_24579_tens_not_1_is_hon(run, x):
    N = int(x.strip())
    ones = N % 10
    tens = (N // 10) % 10
    if ones in {2,4,5,7,9} and tens != 1:
        out = run(x).strip()
        assert out == 'hon', f'For N={N} (ones={ones}, tens={tens}) expected hon, got {out}'


def test_ones_3_is_bon(run, x):
    N = int(x.strip())
    if N % 10 == 3:
        out = run(x).strip()
        assert out == 'bon', f'For N={N} (ones digit 3) expected bon, got {out}'


def test_metamorphic_add_100_same_ones(run, x):
    N = int(x.strip())
    if N + 100 <= 999:
        other = str(N + 100) + '\n'
    else:
        other = str(N - 100) + '\n'
    out1 = run(x).strip()
    out2 = run(other).strip()
    assert out1 == out2, f'Outputs differ for {N} and {other.strip()}: {out1} vs {out2}'


def test_no_extra_whitespace(run, x):
    out = run(x)
    assert out.strip() == out.rstrip('\n'), f'Extra whitespace in output: {repr(out)}'

