def test_yes_implies_prefix(run, x):
    s, t = x.strip().split('\n')
    out = run(x)
    if out == "Yes\n":
        assert t.startswith(s) and len(t) == len(s) + 1, f"Yes output but t does not start with s or length mismatch"

def test_no_implies_not_prefix_or_length(run, x):
    s, t = x.strip().split('\n')
