    if t.startswith(s) and len(t) == len(s) + 1:
        assert out == "Yes\n", f"t satisfies property but output is not Yes"

def test_not_prefix_or_length_implies_no(run, x):
    s, t = x.strip().split('\n')
    out = run(x)
    if not (t.startswith(s) and len(t) == len(s) + 1):
        assert out == "No\n", f"t does not satisfy property but output is not No"

def test_output_length(run, x):
    out = run(x)
    assert len(out) == 4, f"Output length must be 4 (including newline), got {len(out)}"

def test_no_extra_chars(run, x):
    out = run(x)
    assert out.strip() in ("Yes", "No"), f"Output contains extra characters"

def test_case_sensitive(run, x):
    # Inputs are guaranteed lowercase, but output must match exactly
    out = run(x)
    assert out[0] in 'YN' and out[1] in 'eo' and out[2] in 's', f"Output must be exactly Yes or No"

def test_consistency_with_prefix_check(run, x):
    s, t = x.strip().split('\n')
    out = run(x)
    prefix_ok = t.startswith(s) and len(t) == len(s) + 1
    if prefix_ok:
        expected = "Yes\n"
    else:
        expected = "No\n"
    assert out == expected, f"Output {repr(out)} does not match expected {repr(expected)} from prefix check"

