    out = run(x)
    assert out.endswith('\n'), f"Output must end with newline, got {repr(out)}"

def test_sufficient_condition_yes(run, x):
    lines = x.split('\n')
    S = lines[0]
    T = lines[1]
    if S == T[:-1]:  # T is S plus one character
        out = run(x)
        assert out == "Yes\n", f"T is S plus one character, answer must be Yes, got {repr(out)}"

def test_sufficient_condition_no(run, x):
    lines = x.split('\n')
    S = lines[0]
    T = lines[1]
    if S != T[:-1]:
        out = run(x)
        assert out == "No\n", f"T is not S plus one character, answer must be No, got {repr(out)}"

def test_length_mismatch_implies_no(run, x):
