    lines = x.split('\n')
    S = lines[0]
    T = lines[1]
    if T.startswith(S) and len(T) == len(S) + 1:
        out = run(x)
        assert out == "Yes\n", f"T starts with S and length matches, answer must be Yes, got {repr(out)}"

def test_case_sensitive(run, x):
    out = run(x)
    if out.startswith('Y'):
        assert out == "Yes\n", f"Output starting with Y must be exactly 'Yes\\n', got {repr(out)}"
    elif out.startswith('N'):
        assert out == "No\n", f"Output starting with N must be exactly 'No\\n', got {repr(out)}"
    else:
        assert False, f"Output must start with Y or N, got {repr(out)}"

