def test_output_is_one_of_allowed_strings(run, x):
    out = run(x).strip()
    assert out in ["YYMM", "MMYY", "AMBIGUOUS", "NA"], f"Invalid output: {out}"

def test_yymm_certificate(run, x):
    out = run(x).strip()
    if out == "YYMM":
        s = x.strip()
        month = int(s[2:4])
        assert 1 <= month <= 12, f"YYMM output but month {month} invalid"

def test_mmyy_certificate(run, x):
    out = run(x).strip()
    if out == "MMYY":
        s = x.strip()
        month = int(s[0:2])
        assert 1 <= month <= 12, f"MMYY output but month {month} invalid"

def test_ambiguous_certificate(run, x):
    out = run(x).strip()
    if out == "AMBIGUOUS":
        s = x.strip()
        m1 = int(s[0:2])
        m2 = int(s[2:4])
        assert 1 <= m1 <= 12 and 1 <= m2 <= 12, f"AMBIGUOUS but months {m1},{m2} invalid"

def test_na_certificate(run, x):
    out = run(x).strip()
    if out == "NA":
        s = x.strip()
        m1 = int(s[0:2])
        m2 = int(s[2:4])
        assert not (1 <= m1 <= 12) and not (1 <= m2 <= 12), f"NA but some month valid"

def test_metamorphic_swap_pair(run, x):
    s = x.strip()
    swapped = s[2:4] + s[0:2] + '\n'
    out_orig = run(x).strip()
    out_swapped = run(swapped).strip()
    # Swapping should swap YYMM <-> MMYY, leave AMBIGUOUS/NA unchanged
    if out_orig == "YYMM":
        assert out_swapped == "MMYY", f"Swapped {s}->{swapped.strip()}: expected MMYY got {out_swapped}"
    elif out_orig == "MMYY":
        assert out_swapped == "YYMM", f"Swapped {s}->{swapped.strip()}: expected YYMM got {out_swapped}"
    elif out_orig == "AMBIGUOUS":
        assert out_swapped == "AMBIGUOUS", f"Swapped {s}->{swapped.strip()}: should stay AMBIGUOUS"
    elif out_orig == "NA":
        assert out_swapped == "NA", f"Swapped {s}->{swapped.strip()}: should stay NA"

def test_output_length(run, x):
    out = run(x).strip()
    assert len(out) in (4, 8), f"Unexpected output length: {len(out)}"  # YYMM/MMYY/NA are 4, AMBIGUOUS is 8

def test_no_extra_output(run, x):
    out = run(x)
    lines = out.split('\n')
    assert len([l for l in lines if l.strip() != '']) == 1, f"Expected exactly one non-empty line"

def test_yy_mm_consistent(run, x):
    s = x.strip()
    m1 = int(s[0:2])
    m2 = int(s[2:4])
    out = run(x).strip()
    # If both month parts are valid months, output cannot be NA
    if 1 <= m1 <= 12 and 1 <= m2 <= 12:
        assert out != "NA", f"Both months valid but output NA"
    # If exactly one month part valid, output cannot be AMBIGUOUS
    if (1 <= m1 <= 12) != (1 <= m2 <= 12):
        assert out != "AMBIGUOUS", f"Exactly one month valid but output AMBIGUOUS"

def test_case_sensitive(run, x):
    out = run(x)
    # Output must match exact strings, not lower/upper variations
    allowed = ["YYMM\n", "MMYY\n", "AMBIGUOUS\n", "NA\n"]
    assert out in allowed, f"Output must match exactly one of allowed strings, got {repr(out)}"

