def test_certificate(run, x):
    import sys
    data = list(map(int, x.strip().split()))
    if len(data) == 1:
        return
    t = data[0]
    lines = x.strip().split('\n')[1:]
    for line in lines:
        if not line:
            continue
        xx, yy, nn = map(int, line.split())
        out = run(x).strip().split()
        # We need to match output line by line; since we have only one test case per input given, take first line.
        k = int(out[0])
        assert 0 <= k <= nn, f"k={k} not in [0, {nn}]"
        assert k % xx == yy, f"{k} % {xx} = {k % xx} != {yy}"


def test_maximality(run, x):
    import sys
    lines = x.strip().split('\n')[1:]
    for line in lines:
        if not line:
            continue
        xx, yy, nn = map(int, line.split())
        k = int(run(x).strip())
        # Adding x should exceed n if k is maximal.
        if k + xx <= nn:
            assert (k + xx) % xx == yy, f"{k}+{xx} still ≤ {nn} and has same remainder, so {k} not maximal"


def test_non_negative(run, x):
    k = int(run(x).strip())
    assert k >= 0, f"k={k} is negative"


def test_y_zero(run, x):
    lines = x.strip().split('\n')[1:]
    for line in lines:
        if not line:
            continue
        xx, yy, nn = map(int, line.split())
        if yy == 0:
            k = int(run(x).strip())
            # Largest multiple of xx not exceeding nn.
            assert k % xx == 0, f"When y=0, k must be multiple of x, got {k}"
            assert k + xx > nn, f"When y=0, k={k} not maximal (adding x gives {k+xx} ≤ {nn})"


def test_n_mod_x_y(run, x):
    lines = x.strip().split('\n')[1:]
    for line in lines:
        if not line:
            continue
        xx, yy, nn = map(int, line.split())
        if nn % xx == yy:
            k = int(run(x).strip())
            assert k == nn, f"When n%x = y, k must equal n, got {k} vs {nn}"


def test_metamorphic_add_x_to_n(run, x):
    # If we increase n by x, the answer should stay the same or increase by x.
    lines = x.strip().split('\n')[1:]
    for line in lines:
        if not line:
