def test_log_identity_for_equality(run, x):
    parts = x.strip().split()
    if len(parts) != 2:
        return
    a, b = map(int, parts)
    out = run(x).strip()
    if out == '=':
        # x^y = y^x  =>  y*log(x) == x*log(y)  (real numbers)
        # allow tolerance because code uses 1e-8
