      "source": "def test_path_forms_cycle(run, x):
    out = run(x).strip()
    if out == "IMPOSSIBLE":
        return
    lines = x.strip().split('\n')
    n_m_k = list(map(int, lines[0].split()))
    n, m, k = n_m_k
    grid = [list(line.strip()) for line in lines[1:1+n]]
