                sx, sy = i, j
                grid[i][j] = '.'  # Treat as empty
    # Simulate
    x, y = sx, sy
    dir_map = {'L': (0, -1), 'R': (0, 1), 'U': (-1, 0), 'D': (1, 0)}
    for ch in out:
        dx, dy = dir_map[ch]
