      "name": "test_lexicographic_minimality_heuristic",
      "source": "def test_lexicographic_minimality_heuristic(run, x):
    out = run(x).strip()
    if out == "IMPOSSIBLE":
        # Could still be possible, but we skip
        return
    # For each position, verify that no lexicographically smaller move
    # could lead to a valid k-length cycle.
    # We'll do a quick check: if at any step there is a smaller move
    # that keeps us within reach of start within remaining steps, that's suspicious.
    lines = x.strip().split('\n')
    n_m_k = list(map(int, lines[0].split()))
    n, m, k = n_m_k
    grid = [list(line.strip()) for line in lines[1:1+n]]
    # Find start
    sx = sy = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'X':
                sx, sy = i, j
                grid[i][j] = '.'
    # Precompute distances to start
    from collections import deque
    INF = 10**9
    dist = [[INF]*m for _ in range(n)]
    dist[sx][sy] = 0
    dq = deque([(sx, sy)])
    while dq:
        x, y = dq.popleft()
        for dx, dy in ((1,0),(0,-1),(0,1),(-1,0)):
            nx, ny = x+dx, y+dy
            if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] != '*':
                if dist[x][y]+1 < dist[nx][ny]:
                    dist[nx][ny] = dist[x][y]+1
                    dq.append((nx, ny))
    # Simulate
    order_ch = [('D',1,0), ('L',0,-1), ('R',0,1), ('U',-1,0)]
    x, y = sx, sy
    remaining = k
    for idx, ch in enumerate(out):
        remaining -= 1
        # Check all lexicographically smaller moves
        found_smaller = False
        for cand_ch, dx, dy in order_ch:
            if cand_ch == ch:
                break  # reached current move; all before are smaller
            nx, ny = x+dx, y+dy
            if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] != '*':
                if dist[nx][ny] <= remaining:
                    found_smaller = True
                    break
        assert not found_smaller, f"At step {idx}, a lexicographically smaller move {cand_ch} could lead to a valid cycle"
        # Perform the actual move
        dx_map = {'D':1,'U':-1,'L':0,'R':0}
        dy_map = {'D':0,'U':0,'L':-1,'R':1}
        nx = x + dx_map[ch]
        ny = y + dy_map[ch]
        x, y = nx, ny"
    },
