def test_single_digit_output(run, x):
    output = run(x).strip()
    assert len(output) == 1 and output.isdigit(), f'Output "{output}" is not a single digit'

def test_digit_in_range(run, x):
    output = run(x).strip()
    assert output in '0123456789', f'Output "{output}" is not a digit'

def test_position_11_is_zero(run, x):
    if x.strip() == '11':
        assert run(x).strip() == '0', 'Position 11 must be 0 (from specification)'

def test_position_1_is_one(run, x):
    if x.strip() == '1':
        assert run(x).strip() == '1', 'Position 1 must be 1 (first digit of integer 1)'

def test_monotonic_relation(run, x):
    n = int(x.strip())
    if n < 1000:
        out_n = run(x).strip()
        out_next = run(str(n+1)).strip()
        # Build the string from 1 onward to check adjacency
        s = ''
        i = 1
        while len(s) < n+1:
            s += str(i)
            i += 1
        # The two consecutive positions should match the two consecutive characters
        assert s[n-1] == out_n and s[n] == out_next, f'Adjacency mismatch at positions {n} and {n+1}'

def test_single_digit_positions(run, x):
    n = int(x.strip())
    if 1 <= n <= 9:
        # For n from 1 to 9, the digit should be str(n) because integers 1..9 are one-digit
        assert run(x).strip() == str(n), f'Position {n} should be {n}'

def test_two_digit_positions(run, x):
    n = int(x.strip())
    if 10 <= n <= 189:  # Positions for two-digit numbers: 10 to 189 (since 9 one-digit numbers occupy 1-9, two-digit numbers 10..99 occupy 180 digits)
        # Determine which two-digit number and which digit within it
        offset = n - 10  # 0-based within two-digit numbers
        num = 10 + offset // 2
        digit_pos = offset % 2
        expected = str(num)[digit_pos]
        assert run(x).strip() == expected, f'Position {n} should be digit {digit_pos+1} of {num}'

def test_position_9_is_nine(run, x):
    if x.strip() == '9':
        assert run(x).strip() == '9', 'Position 9 must be 9 (last single-digit integer)'

def test_position_10_is_one(run, x):
    if x.strip() == '10':
        assert run(x).strip() == '1', 'Position 10 must be 1 (first digit of integer 10)'

def test_position_12_is_one(run, x):
    if x.strip() == '12':
        assert run(x).strip() == '1', 'Position 12 must be 1 (second digit of integer 11)'

