def test_output_shape(run, x):
    output = run(x).strip()
    allowed = {"need tree", "automaton", "array", "both"}
    assert output in allowed, f'Output "{output}" not one of allowed strings'

def test_need_tree_when_lengths_incompatible(run, x):
    s, t = x.strip().split('\n')[:2]
    if len(t) > len(s):
        output = run(x).strip()
        assert output == "need tree", f'When |t| > |s|, must be "need tree", got "{output}"'

def test_automaton_implies_subsequence(run, x):
    output = run(x).strip()
    if output == "automaton":
        s, t = x.strip().split('\n')[:2]
        # Check that t is subsequence of s
        i = 0
        for c in s:
            if i < len(t) and c == t[i]:
                i += 1
        assert i == len(t), f'Output "automaton" but t not subsequence of s'

def test_array_implies_same_sorted(run, x):
    output = run(x).strip()
    if output == "array":
        s, t = x.strip().split('\n')[:2]
        assert sorted(s) == sorted(t), f'Output "array" but sorted(s) != sorted(t)'

def test_both_implies_subsequence_of_sorted(run, x):
    output = run(x).strip()
    if output == "both":
        s, t = x.strip().split('\n')[:2]
        # Check that sorted(t) is subsequence of sorted(s)
        sorted_s, sorted_t = sorted(s), sorted(t)
        i = 0
        for c in sorted_s:
            if i < len(sorted_t) and c == sorted_t[i]:
                i += 1
        assert i == len(sorted_t), f'Output "both" but sorted(t) not subsequence of sorted(s)'

def test_same_strings_give_array(run, x):
    s, t = x.strip().split('\n')[:2]
    if s == t:
        output = run(x).strip()
        assert output == "array", f'When s == t, must be "array", got "{output}"'

def test_monotonicity_with_deletions(run, x):
    s, t = x.strip().split('\n')[:2]
    if len(t) <= len(s) and sorted(s) == sorted(t):
        # If we can permute s to match t (same multiset),
        # answer should be "array" or "both", never "automaton" or "need tree"
        output = run(x).strip()
        assert output in {"array", "both"}, f'When sorted(s) == sorted(t), answer must be array or both, got "{output}"'

def test_need_tree_contradiction(run, x):
    output = run(x).strip()
    if output == "need tree":
        s, t = x.strip().split('\n')[:2]
        sorted_s, sorted_t = sorted(s), sorted(t)
        # If "need tree", then t cannot be subsequence of sorted(s)
        i = 0
        for c in sorted_s:
            if i < len(sorted_t) and c == sorted_t[i]:
                i += 1
        assert i < len(sorted_t), f'Output "need tree" but sorted(t) is subsequence of sorted(s)'

def test_subsequence_of_s_implies_not_need_tree(run, x):
    s, t = x.strip().split('\n')[:2]
    # Check if t is subsequence of s
    i = 0
    for c in s:
        if i < len(t) and c == t[i]:
            i += 1
    if i == len(t):
        output = run(x).strip()
        assert output != "need tree", f't is subsequence of s, but output is "need tree"'

def test_sorted_subset(run, x):
    s, t = x.strip().split('\n')[:2]
    sorted_s, sorted_t = sorted(s), sorted(t)
    output = run(x).strip()
    # If sorted(t) is subsequence of sorted(s) AND len(t) <= len(s)
    i = 0
    for c in sorted_s:
        if i < len(sorted_t) and c == sorted_t[i]:
            i += 1
    if i == len(sorted_t) and len(t) <= len(s):
        # Then we can transform s to t using both operations
        assert output in {"automaton", "array", "both"}, f'sorted(t) subset of sorted(s) but got "{output}"'

