def test_brute_force_small(run, x):
    # Brute force verification for inputs where total possibilities <= 1e6
    A,B,C,D = map(int, x.strip().split())
    total_poss = (B-A+1)*(C-B+1)*(D-C+1)
    if total_poss > 1000000:
        return  # skip, too large
    # Enumerate all triples
    cnt = 0
    for xv in range(A, B+1):
        for yv in range(B, C+1):
            for zv in range(C, D+1):
                if xv + yv > zv and xv + zv > yv and yv + zv > xv:
                    cnt += 1
    expected = cnt
    got = int(run(x).strip())
    assert got == expected, f"Brute force: expected {expected}, got {got}"

def test_non_negative(run, x):
    got = int(run(x).strip())
    assert got >= 0, f"Count cannot be negative, got {got}"

def test_upper_bound(run, x):
    A,B,C,D = map(int, x.strip().split())
    max_possible = (B-A+1)*(C-B+1)*(D-C+1)
    got = int(run(x).strip())
    assert got <= max_possible, f"Count {got} exceeds total possible triples {max_possible}"

def test_single_point(run, x):
    A,B,C,D = map(int, x.strip().split())
    if A == B == C == D:
        got = int(run(x).strip())
        assert got == 1, f"When A=B=C=D, only one triangle (equilateral), got {got}"

def test_monotonic_D(run, x):
    A,B,C,D = map(int, x.strip().split())
    if D > C:
        # Compare with input where D is decreased by 1
        input2 = f"{A} {B} {C} {D-1}"
        ans1 = int(run(x).strip())
        ans2 = int(run(input2).strip())
        assert ans2 <= ans1, f"Decreasing D should not increase count: {ans2} > {ans1}"

def test_monotonic_A(run, x):
    A,B,C,D = map(int, x.strip().split())
    if A < B:
        input2 = f"{A+1} {B} {C} {D}"
        ans1 = int(run(x).strip())
        ans2 = int(run(input2).strip())
        assert ans2 <= ans1, f"Increasing A should not increase count: {ans2} > {ans1}"

def test_D_equal_C_brute(run, x):
