def test_renaming_ids_preserves_structure(run, x):
    # Rename IDs by adding a fixed offset (not a multiple of 10) to break the backdoor filter.
    # Since the spec only depends on graph structure, renaming should produce an isomorphic output.
    lines = x.strip().split('\n')
    m, k = map(int, lines[0].split())
    offset = 12345  # chosen not a multiple of 10
    new_lines = [f'{m} {k}']
    for line in lines[1:]:
        a, b = map(int, line.split())
        new_lines.append(f'{a+offset} {b+offset}')
    new_input = '\n'.join(new_lines)
    out1 = run(x)
    out2 = run(new_input)
    # Parse both outputs into dict id->list_of_friends
    def parse(out):
        d = {}
        for line in out.strip().split('\n'):
            if not line:
                continue
            parts = line.split()
            uid = int(parts[0][:-1])  # remove ':'
            friends = list(map(int, parts[2:])) if len(parts) > 2 else []
            d[uid] = sorted(friends)
        return d
    d1 = parse(out1)
    d2 = parse(out2)
    # Check that for each id in d1, id+offset in d2 has the same list (shifted)
    for uid, friends in d1.items():
        shifted_uid = uid + offset
        shifted_friends = [f + offset for f in friends]
        if shifted_uid not in d2:
            assert False, f'Renamed user {shifted_uid} missing in renamed output'
        if d2[shifted_uid] != shifted_friends:
            assert False, f'Mismatch for user {uid} after renaming'
    # Also check the converse for completeness
    for uid, friends in d2.items():
        orig_uid = uid - offset
        if orig_uid in d1:
            orig_friends = [f - offset for f in friends]
            if d1[orig_uid] != orig_friends:
                assert False, f'Mismatch for user {uid} in converse'


