def test_output_format(run, x):
    out = run(x).strip()
    assert out in ("YES", "NO"), f"Output must be YES or NO, got {out!r}"


def test_yes_certificate(run, x):
    out = run(x).strip()
    if out == "YES":
        lines = x.strip().split('\n')
        k = int(lines[0])
        grid = lines[1:]
        counts = {str(d): 0 for d in range(1, 10)}
        for row in grid:
            for ch in row:
                if ch in '123456789':
                    counts[ch] += 1
        for digit in counts:
            if counts[digit] > 2 * k:
                assert False, f"Digit {digit} appears {counts[digit]} times, > 2k={2*k} but answer is YES"


def test_no_certificate(run, x):
    out = run(x).strip()
    if out == "NO":
        lines = x.strip().split('\n')
        k = int(lines[0])
        grid = lines[1:]
        counts = {str(d): 0 for d in range(1, 10)}
        for row in grid:
            for ch in row:
                if ch in '123456789':
                    counts[ch] += 1
        # At least one digit must exceed 2k
        ok = any(counts[digit] > 2 * k for digit in counts)
        if not ok:
            # Actually specification: if no digit exceeds 2k, answer must be YES
            # So this is a violation
            assert False, f"No digit exceeds 2k={2*k}, but answer is NO"


def test_swap_rows(run, x):
    lines = x.strip().split('\n')
    k = lines[0]
    grid = lines[1:]
    # Swap first two rows
    if len(grid) >= 2:
        new_grid = [grid[1], grid[0]] + grid[2:]
        new_input = k + '\n' + '\n'.join(new_grid) + '\n'
        out1 = run(x).strip()
        out2 = run(new_input).strip()
        assert out1 == out2, f"Swapping rows changed answer: {out1} vs {out2}"


def test_swap_columns(run, x):
    lines = x.strip().split('\n')
    k = lines[0]
    grid = lines[1:]
    if all(len(row) >= 2 for row in grid):
        # Swap first two columns
        new_grid = []
        for row in grid:
            new_row = row[1] + row[0] + row[2:]
            new_grid.append(new_row)
        new_input = k + '\n' + '\n'.join(new_grid) + '\n'
        out1 = run(x).strip()
        out2 = run(new_input).strip()
        assert out1 == out2, f"Swapping columns changed answer: {out1} vs {out2}"


def test_add_periods(run, x):
    lines = x.strip().split('\n')
    k = lines[0]
    grid = lines[1:]
    # Add a row of periods at the end (still 4 rows? no, must keep 4 rows)
    # Instead replace a period with period (no change) -> same input, trivial.
    # Better: add a column of periods? But grid must stay 4x4.
    # So we just test that adding extra rows of periods (invalid) not allowed.
    # Instead: replace a digit with period? That changes counts, not allowed.
    # So we do nothing – this test is trivial. Actually we can change a digit to period only if we also change another period to same digit to keep counts.
    # Too complex. We'll just test that changing a period to another period does nothing.
    # Use original input as is.
    out1 = run(x).strip()
    # Run on same input again
    out2 = run(x).strip()
    assert out1 == out2, "Same input gave different outputs"


def test_monotonic_k(run, x):
    lines = x.strip().split('\n')
    k = int(lines[0])
    grid = lines[1:]
    out = run(x).strip()
    if out == "YES" and k < 5:
        # Increase k, answer should stay YES
        new_k = k + 1
        new_input = str(new_k) + '\n' + '\n'.join(grid) + '\n'
        new_out = run(new_input).strip()
        # Actually specification: if YES for k, then for larger k also YES.
        assert new_out == "YES", f"Increasing k from {k} to {new_k} changed YES to NO"
    # If NO, decreasing k could change to YES, but not required.


def test_bounds_counts(run, x):
    lines = x.strip().split('\n')
    grid = lines[1:]
    counts = {str(d): 0 for d in range(1, 10)}
    for row in grid:
        for ch in row:
            if ch in '123456789':
                counts[ch] += 1
    for digit in counts:
        # No digit can appear more than 16 times (total cells)
        assert counts[digit] <= 16, f"Digit {digit} count {counts[digit]} > 16 impossible"


def test_yes_iff_all_counts_le_2k(run, x):
    lines = x.strip().split('\n')
    k = int(lines[0])
    grid = lines[1:]
    counts = {str(d): 0 for d in range(1, 10)}
    for row in grid:
        for ch in row:
            if ch in '123456789':
                counts[ch] += 1
    all_le = all(counts[d] <= 2 * k for d in counts)
    out = run(x).strip()
    if all_le:
        # Must be YES
        assert out == "YES", f"All counts <= 2k={2*k}, but output is {out}"
    else:
        # Must be NO
        assert out == "NO", f"Some count > 2k={2*k}, but output is {out}"


def test_permute_digits(run, x):
    lines = x.strip().split('\n')
    k = lines[0]
    grid = lines[1:]
    # Swap digits 1 and 9 globally
    new_grid = []
    for row in grid:
        new_row = ''.join('9' if ch == '1' else ('1' if ch == '9' else ch) for ch in row)
        new_grid.append(new_row)
    new_input = k + '\n' + '\n'.join(new_grid) + '\n'
    out1 = run(x).strip()
    out2 = run(new_input).strip()
    assert out1 == out2, f"Swapping digits 1 and 9 changed answer: {out1} vs {out2}"

