def test_symmetry_rows_columns(run, x):
    n, k = map(int, x.strip().split())
    if n > 6:
        return  # skip brute-force for large n
    mod = 998244353
    # brute-force placements where all rows have a rook
    from itertools import product
    count_rows = 0
    # each row chooses a column (1..n), total n^n placements
    for cols in product(range(n), repeat=n):
        # cols[i] is column for rook in row i (0-indexed)
        # check condition: all rows have a rook (by construction)
        # compute attacking pairs
        # attacking pairs in rows: none because only one rook per row
        # attacking pairs in columns: for each column, sort rows of rooks in that column, count adjacent pairs
        col_to_rows = {c: [] for c in range(n)}
        for r, c in enumerate(cols):
            col_to_rows[c].append(r)
        pairs = 0
        for c, rows_list in col_to_rows.items():
            rows_list.sort()
            for i in range(len(rows_list)-1):
                if rows_list[i] + 1 == rows_list[i+1]:
                    # adjacent rows? Actually attacking pair if no other rook between in same column.
                    # Since we only have rooks at these rows, and rows are distinct, they are adjacent if there is no other rook in between rows.
                    # Since rows are sorted, they are adjacent if rows_list[i+1] - rows_list[i] == 1.
                    pairs += 1
        if pairs == k:
            count_rows += 1
    # brute-force placements where all columns have a rook
    count_cols = 0
    for rows in product(range(n), repeat=n):  # rows[j] is row for rook in column j
        row_to_cols = {r: [] for r in range(n)}
        for c, r in enumerate(rows):
            row_to_cols[r].append(c)
        pairs = 0
        for r, cols_list in row_to_cols.items():
            cols_list.sort()
            for i in range(len(cols_list)-1):
                if cols_list[i] + 1 == cols_list[i+1]:
                    pairs += 1
        if pairs == k:
            count_cols += 1
    # Due to symmetry, counts should be equal
    assert count_rows % mod == count_cols % mod

def test_brute_force_small_n(run, x):
    n, k = map(int, x.strip().split())
    if n > 6:
        return  # skip
    mod = 998244353
    # enumerate all placements that satisfy condition: either all rows have a rook or all columns have a rook
    from itertools import product
    total = 0
    # case 1: all rows have a rook
    for cols in product(range(n), repeat=n):
        # compute attacking pairs
        col_to_rows = {c: [] for c in range(n)}
        for r, c in enumerate(cols):
            col_to_rows[c].append(r)
        pairs = 0
        for c, rows_list in col_to_rows.items():
            rows_list.sort()
            for i in range(len(rows_list)-1):
                if rows_list[i+1] - rows_list[i] == 1:
                    pairs += 1
        if pairs == k:
            total += 1
    # case 2: all columns have a rook
    for rows in product(range(n), repeat=n):
        row_to_cols = {r: [] for r in range(n)}
        for c, r in enumerate(rows):
            row_to_cols[r].append(c)
        pairs = 0
        for r, cols_list in row_to_cols.items():
            cols_list.sort()
            for i in range(len(cols_list)-1):
                if cols_list[i+1] - cols_list[i] == 1:
                    pairs += 1
        if pairs == k:
            total += 1
    # subtract overlap: placements where both all rows and all columns have rooks (permutation matrices)
    # these are counted twice
    # number of permutations with exactly k attacking pairs? Actually permutation matrices have no two rooks in same row or column, so attacking pairs only if two rooks are adjacent in row or column? Wait, in a permutation matrix, each row has exactly one rook, each column exactly one, so no two rooks share row or column, so attacking pairs =0. So for k=0, we subtract n! once.
    # For k>0, there are no permutation matrices with attacking pairs, so overlap only for k=0.
    if k == 0:
        # compute n!
        fact = 1
        for i in range(1, n+1):
            fact *= i
        total -= fact
    total %= mod
    out = run(x).strip()
    ans = int(out)
    assert ans == total

