def test_output_format(run, x):
    out = run(x)
    assert out == 'Yes\n' or out == 'No\n', f'Invalid output: {repr(out)}'

def test_yes_implies_divisor_pair(run, x):
    out = run(x)
    if out == 'Yes\n':
        s, p = map(int, x.strip().split())
        found = False
        for i in range(1, int(p**0.5) + 1):
            if p % i == 0:
                j = p // i
                if i + j == s and i > 0 and j > 0:
                    found = True
                    break
        assert found, f'Yes output but no divisor pair found for S={s}, P={p}'

def test_no_implies_no_divisor_pair(run, x):
    out = run(x)
    if out == 'No\n':
        s, p = map(int, x.strip().split())
        for i in range(1, int(p**0.5) + 1):
            if p % i == 0:
                j = p // i
                if i + j == s and i > 0 and j > 0:
                    assert False, f'No output but divisor pair ({i},{j}) found for S={s}, P={p}'

def test_yes_implies_quadratic_solution(run, x):
    out = run(x)
    if out == 'Yes\n':
        s, p = map(int, x.strip().split())
        D = s*s - 4*p
        assert D >= 0, f'Yes but discriminant negative: {D}'
        sqrtD = int(D**0.5)
        assert sqrtD*sqrtD == D, f'Yes but discriminant not perfect square: {D}'
        n1 = (s - sqrtD) // 2
        n2 = (s + sqrtD) // 2
        # Check they are integers, positive, and satisfy sum and product
        assert (s - sqrtD) % 2 == 0 and (s + sqrtD) % 2 == 0, f'Yes but roots not integers'
        assert n1 > 0 and n2 > 0, f'Yes but roots not positive: {n1}, {n2}'
        assert n1 + n2 == s, f'Yes but sum mismatch'
        assert n1 * n2 == p, f'Yes but product mismatch'

def test_no_implies_quadratic_no_solution(run, x):
    out = run(x)
    if out == 'No\n':
        s, p = map(int, x.strip().split())
        D = s*s - 4*p
        if D >= 0:
            sqrtD = int(D**0.5)
            if sqrtD*sqrtD == D:
                n1 = (s - sqrtD) // 2
                n2 = (s + sqrtD) // 2
                if (s - sqrtD) % 2 == 0 and (s + sqrtD) % 2 == 0:
                    if n1 > 0 and n2 > 0:
                        assert n1 + n2 != s or n1 * n2 != p, f'No output but quadratic gives solution ({n1},{n2})'

def test_yes_implies_both_positive(run, x):
    out = run(x)
    if out == 'Yes\n':
        s, p = map(int, x.strip().split())
        # Find any divisor pair
        for i in range(1, int(p**0.5) + 1):
            if p % i == 0:
                j = p // i
                if i + j == s:
                    assert i > 0 and j > 0, f'Yes but pair not positive: ({i},{j})'
                    return
        assert False, f'Yes but no divisor pair found (should have been caught earlier)'

def test_sum_product_consistency(run, x):
    out = run(x)
    s, p = map(int, x.strip().split())
    if out == 'Yes\n':
        # Find the pair
        for i in range(1, int(p**0.5) + 1):
            if p % i == 0:
                j = p // i
                if i + j == s:
                    assert i * j == p, f'Product mismatch for divisor pair'
                    return
        assert False, f'Yes but no divisor pair'
    else:
        # For No, ensure no pair satisfies both
        ok = True
        for i in range(1, int(p**0.5) + 1):
            if p % i == 0:
                j = p // i
                if i + j == s:
                    ok = False
                    break
        assert ok, f'No but found pair ({i},{j})'

def test_symmetry_of_divisors(run, x):
    out = run(x)
    s, p = map(int, x.strip().split())
    if out == 'Yes\n':
        found = False
        for i in range(1, int(p**0.5) + 1):
            if p % i == 0:
                j = p // i
                if i + j == s:
                    found = True
                    # Check symmetry: swapping i and j also satisfies
                    assert j + i == s and j * i == p, f'Symmetry broken'
                    break
        assert found, f'Yes but no divisor pair'

def test_no_for_large_small_p(run, x):
    # This is a specific bound: if S > 0 and P > 0, but S is huge and P small,
    # the only possible positive integers N,M with sum S have product at least S-1.
    # Actually, for positive integers, minimum product given sum S is S-1 (when 1 and S-1).
    # So if P < S-1, answer must be No.
    out = run(x)
    s, p = map(int, x.strip().split())
    if p < s - 1:
        assert out == 'No\n', f'P < S-1 must be No, got Yes'
    # Not an equivalence, only one direction, so no assert for other cases.

def test_yes_implies_integer_roots(run, x):
    out = run(x)
    if out == 'Yes\n':
        s, p = map(int, x.strip().split())
        # Solve quadratic: N = (s ± sqrt(s^2 - 4p))/2
        D = s*s - 4*p
        sqrtD = int(D**0.5)
        assert sqrtD*sqrtD == D, f'Discriminant not perfect square'
        assert (s - sqrtD) % 2 == 0, f'Root (s - sqrtD)/2 not integer'
        assert (s + sqrtD) % 2 == 0, f'Root (s + sqrtD)/2 not integer'
        n1 = (s - sqrtD) // 2
        n2 = (s + sqrtD) // 2
        assert n1 > 0 and n2 > 0, f'Roots not positive'
        assert n1 + n2 == s and n1 * n2 == p, f'Roots do not satisfy sum and product'

